INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u5-C1','math',5,2,'u5',2,'평면도형과 입체도형 — 두께가 없는 도형은 평면도형, 공간을 차지하고 두께가 있는 도형은 입체도형이며, 종이에 그린 그림이 평평해도 그림이 나타내는 물건이 두께가 있으면 입체도형임을 알기',ARRAY['6수03-03']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u5-C2','math',5,2,'u5',2,'직육면체와 구성 요소 — 직사각형 6개로 둘러싸인 입체도형을 직육면체라 하고, 면(6개)·모서리(12개)·꼭짓점(8개)을 보이지 않는 곳까지 세며, 면 6개의 변 24개가 둘씩 만나 모서리가 12개이고 같은 길이의 모서리가 4개씩 3묶음임을 알기',ARRAY['6수03-03']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u5-C3','math',5,2,'u5',3,'정육면체 — 정사각형 6개로 둘러싸인 입체도형을 정육면체라 하고, 모든 모서리의 길이가 같으며, 정사각형은 직사각형이므로 정육면체는 직육면체라고 할 수 있지만 직육면체가 모두 정육면체는 아님을 알기',ARRAY['6수03-03']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u5-C4','math',5,2,'u5',4,'직육면체의 겨냥도 — 보이는 모서리는 실선, 보이지 않는 모서리는 점선으로 그린 그림이 겨냥도이고, 직육면체의 겨냥도는 실선 9개·점선 3개(보이는 면 3·꼭짓점 7, 보이지 않는 면 3·모서리 3·꼭짓점 1)이며, 다른 사람이 그림만 보고 입체를 알 수 있도록 숨은 모서리도 점선으로 그림을 알기',ARRAY['6수03-04']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u5-C5','math',5,2,'u5',5,'직육면체의 밑면과 옆면 — 계속 늘여도 만나지 않는 두 면을 평행하다고 하고 이 두 면을 밑면이라 하며(평행한 면 3쌍, 놓인 위치가 아니라 관계로 정함), 밑면과 수직으로 만나는 면 4개를 옆면이라 하고, 직육면체에서 만나는 두 면은 수직임을 알기',ARRAY['6수03-03']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u5-C6','math',5,2,'u5',6,'직육면체의 전개도 — 모든 면이 이어지도록 모서리를 잘라 평면에 펼친 그림(잘린 모서리 실선·잘리지 않은 모서리 점선)에서 접었을 때 만나는 점·선분, 평행한 면·수직인 면을 찾고, 겹치는 면이 있거나 맞붙는 선분의 길이가 다르면 전개도가 아님을 알기',ARRAY['6수03-04']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u5-C7','math',5,2,'u5',7,'직육면체의 전개도 그리기 — 면 6개를 겹치지 않게 이어 그리고, 맞붙는 모서리는 길이가 같게, 마주 보는 면은 모양과 크기가 같게 그리며, 자르는 모서리에 따라 한 직육면체의 전개도가 여러 가지임을 알기',ARRAY['6수03-04']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M5-2-u5-C8','math',5,2,'u5',8,'문제 해결 — 주사위 전개도에서 평행한 면(눈의 수 합 7)과 수직인 면을 찾아 명령을 따라 굴린 결과를 구하고, 반복 횟수가 많으면 몇 번만 굴려 되풀이되는 규칙을 찾아 해결하기',ARRAY['6수03-04']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u5-X01','math',5,'u5',ARRAY['M5-2-u5-C1']::text[],'종이에 그린 그림이 평평하면 그 물건도 평면도형이라고 여기거나, 평면도형과 입체도형을 거꾸로 가른다','두께가 있으면 입체도형') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u5-X02','math',5,'u5',ARRAY['M5-2-u5-C2','M5-2-u5-C3']::text[],'직육면체를 모양이 아니라 색·크기·쓰임새로 가르거나, 직사각형이 아닌 면이 있어도 직육면체라고 여긴다','직사각형 6개로 둘러싸였나') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u5-X03','math',5,'u5',ARRAY['M5-2-u5-C2','M5-2-u5-C4']::text[],'면·모서리·꼭짓점의 이름과 뜻을 헷갈린다','면은 넓은 곳, 모서리는 선분, 꼭짓점은 점') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u5-X04','math',5,'u5',ARRAY['M5-2-u5-C2','M5-2-u5-C4']::text[],'보이는 것만 세어 면 3개·모서리 9개·꼭짓점 7개라고 한다','뒤쪽까지 빠짐없이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u5-X05','math',5,'u5',ARRAY['M5-2-u5-C2']::text[],'면 6개의 변을 모두 세어 모서리가 24개라고 하거나, 면·모서리·꼭짓점의 수를 서로 바꾸어 쓴다','모서리 하나에 면 두 개') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u5-X06','math',5,'u5',ARRAY['M5-2-u5-C3']::text[],'정육면체는 직육면체가 아니라고 하거나, 직육면체는 모두 정육면체라고 여긴다','정사각형도 직사각형') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u5-X09','math',5,'u5',ARRAY['M5-2-u5-C4']::text[],'겨냥도에서 보이지 않는 모서리를 실선으로 그리거나 아예 그리지 않는다','보이지 않으면 점선') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u5-X10','math',5,'u5',ARRAY['M5-2-u5-C4']::text[],'겨냥도의 실선·점선 개수나 보이는(보이지 않는) 면·모서리·꼭짓점의 수를 헷갈린다','실선 9 · 점선 3') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u5-X11','math',5,'u5',ARRAY['M5-2-u5-C5']::text[],'밑면을 아래에 놓인 면(위치)으로만 여기거나, 옆에 선 두 면은 밑면이 될 수 없다고 한다','밑면은 평행한 관계') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u5-X12','math',5,'u5',ARRAY['M5-2-u5-C5','M5-2-u5-C6']::text[],'평행한 면과 수직인 면을 헷갈린다(옆면끼리 모두 평행하다, 만나는 두 면이 평행하다 등)','만나면 수직, 안 만나면 평행') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u5-X13','math',5,'u5',ARRAY['M5-2-u5-C5','M5-2-u5-C6']::text[],'한 면과 평행한 면·수직인 면의 수를 잘못 센다(평행 2개, 수직 5개 등)','평행 1 · 수직 4') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u5-X14','math',5,'u5',ARRAY['M5-2-u5-C6','M5-2-u5-C7']::text[],'면이 6개면 전개도라고 여기고 겹치는 면이나 맞붙는 선분의 길이를 따지지 않는다','접은 모양을 떠올리기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u5-X15','math',5,'u5',ARRAY['M5-2-u5-C6']::text[],'전개도를 접었을 때 만나는 점·선분을 바로 옆 점이나 이름 차례로 짝 짓는다','한 꼭짓점에 세 면') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u5-X16','math',5,'u5',ARRAY['M5-2-u5-C6','M5-2-u5-C7']::text[],'전개도에서 잘린 모서리(실선)와 잘리지 않은 모서리(점선)를 바꾸어 그리거나 센다','잘린 곳 실선 · 접는 곳 점선') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u5-X17','math',5,'u5',ARRAY['M5-2-u5-C8']::text[],'주사위 명령을 거꾸로 따르거나(이웃한 면으로 굴림, 가장 작은↔큰), 되풀이 규칙의 주기를 잘못 써서 결과를 틀린다','한 번씩 따라 하고 규칙 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u5-X18','math',5,'u5',ARRAY['M5-2-u5-C1','M5-2-u5-C2','M5-2-u5-C3','M5-2-u5-C4','M5-2-u5-C5','M5-2-u5-C6','M5-2-u5-C7','M5-2-u5-C8']::text[],'묻는 말을 거꾸로 읽거나 놓친다 — 아닌↔인, 보이지 않는↔보이는, 평행↔수직','물음의 「아닌·보이지 않는」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u5-X19','math',5,'u5',ARRAY['M5-2-u5-C3']::text[],'정육면체의 성질을 놓친다 — 모든 모서리의 길이가 같고 면이 모두 크기가 같은 정사각형임을 모르고 「모서리의 길이가 서로 다르다」거나 직사각형·사다리꼴도 정육면체의 면이 된다고 한다','정육면체는 모서리의 길이가 모두 같아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M5-2-u5-X20','math',5,'u5',ARRAY['M5-2-u5-C6','M5-2-u5-C7']::text[],'전개도의 선분이 직육면체의 어느 모서리(가로·세로·높이)인지 짝 짓지 못해 길이를 잘못 쓴다','접었을 때 어느 모서리가 되는지 짝 지어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L02_basic#1','math',5,2,'u5','L02','tb_g5_2_math_u5_L02_basic','lesson_basic','M5-2-u5-C1',1,'mc','auto','어린이 놀이방에서 본 것 가운데 입체도형은 어느 것인가요?',ARRAY['M5-2-u5-X01']::text[],true,'{"seq":1,"concept":"M5-2-u5-C1","difficulty":1,"kind":"mc","stem":"어린이 놀이방에서 본 것 가운데 입체도형은 어느 것인가요?","options":[{"t":"달곰이가 가져온 주사위","correct":true},{"t":"놀이판에 그려진 직사각형 칸","mis":"M5-2-u5-X01"},{"t":"종이에 그린 삼각형","mis":"M5-2-u5-X01"},{"t":"칠판에 그린 정사각형","mis":"M5-2-u5-X01"}],"explanation":["놀이판 칸이나 종이에 그린 도형은 두께가 없어요 — 평면도형.","주사위·블록·상자는 손에 쥘 수 있고 두께가 있어요 — 입체도형.","정답은 「달곰이가 가져온 주사위」예요."],"variant_rule":{"alt":[{"stem":"다음 가운데 평면도형은 어느 것인가요?","options":[{"t":"놀이판에 그려진 직사각형 칸","correct":true},{"t":"나무 블록","mis":"M5-2-u5-X01"},{"t":"주사위","mis":"M5-2-u5-X01"},{"t":"선물 상자","mis":"M5-2-u5-X01"}],"explanation":["놀이판 칸이나 종이에 그린 도형은 두께가 없어요 — 평면도형.","주사위·블록·상자는 손에 쥘 수 있고 두께가 있어요 — 입체도형.","정답은 「놀이판에 그려진 직사각형 칸」이에요."]},{"stem":"입체도형을 바르게 설명한 것은 어느 것인가요?","options":[{"t":"공간을 차지하고 두께가 있는 도형","correct":true},{"t":"두께가 없이 종이 위에 그려진 도형","mis":"M5-2-u5-X01"},{"t":"꼭짓점이 4개인 도형","mis":"M5-2-u5-X02"},{"t":"직각이 있는 도형","mis":"M5-2-u5-X02"}],"explanation":["놀이판 칸이나 종이에 그린 도형은 두께가 없어요 — 평면도형.","주사위·블록·상자는 손에 쥘 수 있고 두께가 있어요 — 입체도형.","정답은 「공간을 차지하고 두께가 있는 도형」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L02_basic#2','math',5,2,'u5','L02','tb_g5_2_math_u5_L02_basic','lesson_basic','M5-2-u5-C2',1,'mc','auto','직육면체는 어떤 도형으로 둘러싸인 입체도형인가요?',ARRAY['M5-2-u5-X04','M5-2-u5-X02']::text[],true,'{"seq":2,"concept":"M5-2-u5-C2","difficulty":1,"kind":"mc","stem":"직육면체는 어떤 도형으로 둘러싸인 입체도형인가요?","options":[{"t":"직사각형 6개","correct":true},{"t":"직사각형 4개","mis":"M5-2-u5-X04"},{"t":"삼각형 6개","mis":"M5-2-u5-X02"},{"t":"원 2개와 직사각형 1개","mis":"M5-2-u5-X02"}],"explanation":["직육면체는 모양으로 정해요.","직사각형 6개로 둘러싸인 입체도형이 직육면체예요.","정답은 「직사각형 6개」예요."],"variant_rule":{"alt":[{"stem":"직사각형 6개로 둘러싸인 입체도형을 무엇이라고 하나요?","options":[{"t":"직육면체","correct":true},{"t":"직사각형","mis":"M5-2-u5-X01"},{"t":"육각형","mis":"M5-2-u5-X02"},{"t":"평면도형","mis":"M5-2-u5-X01"}],"explanation":["직육면체는 모양으로 정해요.","직사각형 6개로 둘러싸인 입체도형이 직육면체예요.","정답은 「직육면체」예요."]},{"stem":"나눔 행사에 가져갈 캠핑 상자, 서랍, 선물 상자, 도시락통의 같은 점을 수학적으로 말한 것은 어느 것인가요?","options":[{"t":"모두 직사각형 6개로 둘러싸여 있다","correct":true},{"t":"모두 집에서 쓰는 물건이다","mis":"M5-2-u5-X02"},{"t":"모두 색이 같다","mis":"M5-2-u5-X02"},{"t":"모두 크기가 같다","mis":"M5-2-u5-X02"}],"explanation":["직육면체는 모양으로 정해요.","직사각형 6개로 둘러싸인 입체도형이 직육면체예요.","정답은 「모두 직사각형 6개로 둘러싸여 있다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L02_basic#3','math',5,2,'u5','L02','tb_g5_2_math_u5_L02_basic','lesson_basic','M5-2-u5-C2',1,'mc','auto','직육면체에서 면과 면이 만나는 선분의 이름은 무엇인가요?',ARRAY['M5-2-u5-X03']::text[],true,'{"seq":3,"concept":"M5-2-u5-C2","difficulty":1,"kind":"mc","stem":"직육면체에서 면과 면이 만나는 선분의 이름은 무엇인가요?","options":[{"t":"모서리","correct":true},{"t":"꼭짓점","mis":"M5-2-u5-X03"},{"t":"면","mis":"M5-2-u5-X03"},{"t":"대각선","mis":"M5-2-u5-X03"}],"explanation":["직사각형 부분은 면, 면과 면이 만나는 선분은 모서리예요.","모서리와 모서리가 만나는 점은 꼭짓점이에요.","그래서 「모서리」예요."],"asset":{"type":"geo","items":[{"w":110.0,"h":66.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,44,"ne"],"ㅇ":[110.0,44,"e"],"ㅂ":[0,66.0,"sw"],"ㅅ":[88,66.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체에서 모서리와 모서리가 만나는 점의 이름은 무엇인가요?","options":[{"t":"꼭짓점","correct":true},{"t":"모서리","mis":"M5-2-u5-X03"},{"t":"면","mis":"M5-2-u5-X03"},{"t":"중심","mis":"M5-2-u5-X03"}],"explanation":["직사각형 부분은 면, 면과 면이 만나는 선분은 모서리예요.","모서리와 모서리가 만나는 점은 꼭짓점이에요.","그래서 「꼭짓점」이에요."],"asset":{"type":"geo","items":[{"w":110.0,"h":66.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,44,"ne"],"ㅇ":[110.0,44,"e"],"ㅂ":[0,66.0,"sw"],"ㅅ":[88,66.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체를 둘러싼 직사각형 부분의 이름은 무엇인가요?","options":[{"t":"면","correct":true},{"t":"모서리","mis":"M5-2-u5-X03"},{"t":"꼭짓점","mis":"M5-2-u5-X03"},{"t":"변","mis":"M5-2-u5-X03"}],"explanation":["직사각형 부분은 면, 면과 면이 만나는 선분은 모서리예요.","모서리와 모서리가 만나는 점은 꼭짓점이에요.","그래서 「면」이에요."],"asset":{"type":"geo","items":[{"w":110.0,"h":66.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,44,"ne"],"ㅇ":[110.0,44,"e"],"ㅂ":[0,66.0,"sw"],"ㅅ":[88,66.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L02_basic#4','math',5,2,'u5','L02','tb_g5_2_math_u5_L02_basic','lesson_basic','M5-2-u5-C2',1,'sa','auto','직육면체 모양 캠핑 상자의 면은 모두 몇 개인가요? 보이지 않는 곳까지 세어 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u5-C2","difficulty":1,"kind":"sa","stem":"직육면체 모양 캠핑 상자의 면은 모두 몇 개인가요? 보이지 않는 곳까지 세어 숫자로 쓰세요.","answer":["6"],"explanation":["앞·뒤, 위·아래, 왼쪽·오른쪽에 면이 둘씩 있어요.","2 × 3 = 6이에요.","그래서 면은 6개예요."],"mis":"M5-2-u5-X04","asset":{"type":"geo","items":[{"w":143.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[110,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[143.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[110,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체 모양 서랍의 모서리는 모두 몇 개인가요? 보이지 않는 곳까지 세어 숫자로 쓰세요.","answer":["12"],"explanation":["보이는 모서리 9개와 보이지 않는 모서리 3개가 있어요.","9 + 3 = 12예요.","그래서 모서리는 12개예요."],"asset":{"type":"geo","items":[{"w":121.0,"h":77.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[121.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[88,33.0,"sw"],"ㅁ":[33.0,44,"ne"],"ㅇ":[121.0,44,"e"],"ㅂ":[0,77.0,"sw"],"ㅅ":[88,77.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체 모양 도시락통의 꼭짓점은 모두 몇 개인가요? 보이지 않는 곳까지 세어 숫자로 쓰세요.","answer":["8"],"explanation":["윗면에 4개, 아랫면에 4개가 있어요.","4 + 4 = 8이에요.","그래서 꼭짓점은 8개예요."],"asset":{"type":"geo","items":[{"w":88.0,"h":66.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[88.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[66,22.0,"sw"],"ㅁ":[22.0,44,"ne"],"ㅇ":[88.0,44,"e"],"ㅂ":[0,66.0,"sw"],"ㅅ":[66,66.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L02_basic#5','math',5,2,'u5','L02','tb_g5_2_math_u5_L02_basic','lesson_basic','M5-2-u5-C2',2,'mc','auto','교과서 107쪽 그림이에요. 가: 위와 아래가 원 모양인 통 / 나: 직사각형 6개로 둘러싸인 상자 / 다: 위와 아래가 삼각형 모양인 기둥 / 라: 정사각형 6개로 둘러싸인 상자. 직육면체를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u5-X06','M5-2-u5-X02']::text[],true,'{"seq":5,"concept":"M5-2-u5-C2","difficulty":2,"kind":"mc","stem":"교과서 107쪽 그림이에요. 가: 위와 아래가 원 모양인 통 / 나: 직사각형 6개로 둘러싸인 상자 / 다: 위와 아래가 삼각형 모양인 기둥 / 라: 정사각형 6개로 둘러싸인 상자. 직육면체를 모두 고른 것은 어느 것인가요?","options":[{"t":"나, 라","correct":true},{"t":"나","mis":"M5-2-u5-X06"},{"t":"가, 나, 라","mis":"M5-2-u5-X02"},{"t":"나, 다, 라","mis":"M5-2-u5-X02"}],"explanation":["직육면체는 직사각형 6개로 둘러싸인 입체도형이에요.","정사각형도 직사각형이니 정사각형 6개로 둘러싸인 것도 직육면체예요.","정답은 나, 라예요."],"variant_rule":{"alt":[{"stem":"형성 평가 그림이에요. 가: 원 모양 면이 있는 통 / 나: 삼각형 면만 있는 뿔 / 다: 정사각형 6개로 둘러싸인 상자 / 라: 삼각형 면이 있는 기둥 / 마: 직사각형 6개로 둘러싸인 상자 / 바: 꼭짓점이 뾰족한 원뿔. 직육면체를 모두 고른 것은 어느 것인가요?","options":[{"t":"다, 마","correct":true},{"t":"마","mis":"M5-2-u5-X06"},{"t":"다, 라, 마","mis":"M5-2-u5-X02"},{"t":"나, 다, 마","mis":"M5-2-u5-X02"}],"explanation":["직육면체는 직사각형 6개로 둘러싸인 입체도형이에요.","정사각형도 직사각형이니 정사각형 6개로 둘러싸인 것도 직육면체예요.","정답은 다, 마예요."]},{"stem":"문제로 마무리 1번의 물건이에요. 가: 면이 모두 직사각형인 휴지 상자 / 나: 양쪽 면이 사다리꼴인 과자 상자 / 다: 삼각형 면이 있는 샌드위치 상자 / 라: 면이 모두 직사각형인 지우개. 직육면체 모양을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 라","correct":true},{"t":"가","mis":"M5-2-u5-X18"},{"t":"가, 나, 라","mis":"M5-2-u5-X02"},{"t":"가, 다, 라","mis":"M5-2-u5-X02"}],"explanation":["직육면체는 직사각형 6개로 둘러싸인 입체도형이에요.","정사각형도 직사각형이니 정사각형 6개로 둘러싸인 것도 직육면체예요.","정답은 가, 라예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L02_basic#6','math',5,2,'u5','L02','tb_g5_2_math_u5_L02_basic','lesson_basic','M5-2-u5-C1',2,'ox','auto','종이에 그린 주사위 그림을 보고 「주사위는 평면도형이다」라고 할 수 있어요.',ARRAY['M5-2-u5-X01']::text[],true,'{"seq":6,"concept":"M5-2-u5-C1","difficulty":2,"kind":"ox","stem":"종이에 그린 주사위 그림을 보고 「주사위는 평면도형이다」라고 할 수 있어요.","answer":"X","reason_options":[{"t":"그림이 나타내는 주사위는 두께가 있어 입체도형이므로","correct":true},{"t":"그림이 평평하므로","mis":"M5-2-u5-X01"}],"mis":"M5-2-u5-X01","explanation":["뜻을 떠올려 하나씩 따져 봐요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「그림이 나타내는 주사위는 두께가 있어 입체도형이므로」를 골라요."],"variant_rule":{"alt":[{"stem":"나무 블록의 한 면을 따라 그린 직사각형은 평면도형이에요.","answer":"O","reason_options":[{"t":"종이 위에 그린 직사각형은 두께가 없으므로","correct":true},{"t":"블록이 입체도형이므로 그 면을 따라 그린 것도 입체도형이므로","mis":"M5-2-u5-X01"}],"explanation":["뜻을 떠올려 하나씩 따져 봐요.","맞는 말이면 O, 틀린 말이면 X — 정답은 O예요.","까닭으로 「종이 위에 그린 직사각형은 두께가 없으므로」를 골라요."]},{"stem":"직육면체의 면은 모두 직사각형이에요.","answer":"O","reason_options":[{"t":"직사각형 6개로 둘러싸인 입체도형이 직육면체이므로","correct":true},{"t":"면 하나만 직사각형이면 직육면체이므로","mis":"M5-2-u5-X02"}],"explanation":["뜻을 떠올려 하나씩 따져 봐요.","맞는 말이면 O, 틀린 말이면 X — 정답은 O예요.","까닭으로 「직사각형 6개로 둘러싸인 입체도형이 직육면체이므로」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L02_basic#7','math',5,2,'u5','L02','tb_g5_2_math_u5_L02_basic','lesson_basic','M5-2-u5-C2',2,'match','auto','알맞게 이어 보세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u5-C2","difficulty":2,"kind":"match","stem":"알맞게 이어 보세요.","pairs":[{"l":"직육면체를 둘러싼 직사각형 부분","r":"면"},{"l":"면과 면이 만나는 선분","r":"모서리"},{"l":"모서리와 모서리가 만나는 점","r":"꼭짓점"}],"mis":"M5-2-u5-X03","explanation":["면·모서리·꼭짓점의 뜻과 수를 떠올려요.","면 6개, 모서리 12개, 꼭짓점 8개예요.","하나씩 짝 지으면 돼요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알맞게 이어 보세요.","pairs":[{"l":"직육면체의 면의 수","r":"6개"},{"l":"직육면체의 모서리의 수","r":"12개"},{"l":"직육면체의 꼭짓점의 수","r":"8개"}],"explanation":["면·모서리·꼭짓점의 뜻과 수를 떠올려요.","면 6개, 모서리 12개, 꼭짓점 8개예요.","하나씩 짝 지으면 돼요."]},{"stem":"이번에는 다른 보기예요. 알맞게 이어 보세요.","pairs":[{"l":"두께가 없는 도형","r":"평면도형"},{"l":"공간을 차지하는 도형","r":"입체도형"},{"l":"직사각형 6개로 둘러싸인 입체도형","r":"직육면체"}],"explanation":["면·모서리·꼭짓점의 뜻과 수를 떠올려요.","면 6개, 모서리 12개, 꼭짓점 8개예요.","하나씩 짝 지으면 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L02_basic#8','math',5,2,'u5','L02','tb_g5_2_math_u5_L02_basic','lesson_basic','M5-2-u5-C2',2,'mc','auto','직육면체에 대한 설명으로 옳은 것은 어느 것인가요?',ARRAY['M5-2-u5-X05','M5-2-u5-X03']::text[],true,'{"seq":8,"concept":"M5-2-u5-C2","difficulty":2,"kind":"mc","stem":"직육면체에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"직육면체는 직사각형 6개로 둘러싸여 있습니다.","correct":true},{"t":"직육면체의 모서리는 13개입니다.","mis":"M5-2-u5-X05"},{"t":"직육면체에는 모서리와 모서리가 만나는 면이 있습니다.","mis":"M5-2-u5-X03"},{"t":"직육면체의 꼭짓점은 12개입니다.","mis":"M5-2-u5-X05"}],"explanation":["직육면체는 면 6개, 모서리 12개, 꼭짓점 8개예요.","면과 면이 만나는 선분이 모서리, 모서리와 모서리가 만나는 점이 꼭짓점이에요.","바른 설명은 「직육면체는 직사각형 6개로 둘러싸여 있습니다.」예요."],"variant_rule":{"alt":[{"stem":"직육면체에 대해 바르게 설명한 것은 어느 것인가요?","options":[{"t":"면과 면이 만나는 선분은 모서리입니다.","correct":true},{"t":"면이 6개, 꼭짓점이 12개입니다.","mis":"M5-2-u5-X05"},{"t":"모서리와 모서리가 만나는 점은 면입니다.","mis":"M5-2-u5-X03"},{"t":"보이지 않는 꼭짓점은 세지 않습니다.","mis":"M5-2-u5-X04"}],"explanation":["직육면체는 면 6개, 모서리 12개, 꼭짓점 8개예요.","면과 면이 만나는 선분이 모서리, 모서리와 모서리가 만나는 점이 꼭짓점이에요.","바른 설명은 「면과 면이 만나는 선분은 모서리입니다.」예요."]},{"stem":"직육면체에 대해 바르게 설명한 것은 어느 것인가요?","options":[{"t":"한 꼭짓점에서 세 모서리가 만납니다.","correct":true},{"t":"면이 8개입니다.","mis":"M5-2-u5-X05"},{"t":"한 꼭짓점에서 두 모서리가 만납니다.","mis":"M5-2-u5-X03"},{"t":"모서리는 보이는 것만 9개입니다.","mis":"M5-2-u5-X04"}],"explanation":["직육면체는 면 6개, 모서리 12개, 꼭짓점 8개예요.","면과 면이 만나는 선분이 모서리, 모서리와 모서리가 만나는 점이 꼭짓점이에요.","바른 설명은 「한 꼭짓점에서 세 모서리가 만납니다.」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L02_basic#9','math',5,2,'u5','L02','tb_g5_2_math_u5_L02_basic','lesson_basic','M5-2-u5-C1',2,'mc','auto','교과서 103쪽 배운 내용이에요. 가: 네 각이 모두 직각이고 가로가 긴 사각형 / 나: 네 각이 모두 직각이고 네 변의 길이가 같은 사각형 / 다: 직각이 없는 사각형. 직사각형을 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u5-X06','M5-2-u5-X19','M5-2-u5-X02']::text[],true,'{"seq":9,"concept":"M5-2-u5-C1","difficulty":2,"kind":"mc","stem":"교과서 103쪽 배운 내용이에요. 가: 네 각이 모두 직각이고 가로가 긴 사각형 / 나: 네 각이 모두 직각이고 네 변의 길이가 같은 사각형 / 다: 직각이 없는 사각형. 직사각형을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 나","correct":true},{"t":"가","mis":"M5-2-u5-X06"},{"t":"나","mis":"M5-2-u5-X19"},{"t":"가, 나, 다","mis":"M5-2-u5-X02"}],"explanation":["이 단원에서 배울 직육면체는 직사각형으로 둘러싸여 있고, 면과 면 사이에 평행·수직이 있어요.","네 각이 모두 직각인 사각형이 직사각형이에요 — 정사각형 나도 직사각형이에요.","정답은 「가, 나」예요."],"variant_rule":{"alt":[{"stem":"교과서 103쪽 배운 내용이에요. 가: 네 각이 모두 직각이고 가로가 긴 사각형 / 나: 네 각이 모두 직각이고 네 변의 길이가 같은 사각형 / 다: 직각이 없는 사각형. 정사각형은 어느 것인가요?","options":[{"t":"나","correct":true},{"t":"가","mis":"M5-2-u5-X19"},{"t":"다","mis":"M5-2-u5-X02"},{"t":"가, 나","mis":"M5-2-u5-X19"}],"explanation":["이 단원에서 배울 직육면체는 직사각형으로 둘러싸여 있고, 면과 면 사이에 평행·수직이 있어요.","네 각이 모두 직각이고 네 변의 길이가 같은 사각형이 정사각형이에요.","정답은 「나」예요."]},{"stem":"교과서 103쪽 배운 내용이에요. 직선 가와 아무리 늘여도 만나지 않는 직선을 무엇이라고 하나요?","options":[{"t":"직선 가와 평행한 직선","correct":true},{"t":"직선 가와 수직인 직선","mis":"M5-2-u5-X12"},{"t":"직선 가와 만나는 직선","mis":"M5-2-u5-X12"},{"t":"직선 가의 대각선","mis":"M5-2-u5-X03"}],"explanation":["이 단원에서 배울 직육면체는 직사각형으로 둘러싸여 있고, 면과 면 사이에 평행·수직이 있어요.","아무리 늘여도 만나지 않는 두 직선은 평행하고, 만나서 직각을 이루면 수직이에요.","정답은 「직선 가와 평행한 직선」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L02_basic#10','math',5,2,'u5','L02','tb_g5_2_math_u5_L02_basic','lesson_basic','M5-2-u5-C2',3,'error','auto','친구들이 직육면체에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-2-u5-X04','M5-2-u5-X02']::text[],true,'{"seq":10,"concept":"M5-2-u5-C2","difficulty":3,"kind":"error","stem":"친구들이 직육면체에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"달곰 — 「보이는 모서리만 세면 9개니까 직육면체의 모서리는 9개야.」","correct":true,"mis_target":"M5-2-u5-X04"},{"t":"여울 — 「꼭짓점은 모두 8개야.」","mis":"M5-2-u5-X04"},{"t":"순달 — 「면은 모두 직사각형이야.」","mis":"M5-2-u5-X02"}],"explanation":["직육면체는 면 6개, 모서리 12개, 꼭짓점 8개예요.","보이지 않는 것까지 세고, 변을 두 번 세지 않아요.","달곰의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 직육면체에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"달곰 — 「면 6개의 변을 다 세면 24개니까 모서리는 24개야.」","correct":true,"mis_target":"M5-2-u5-X05"},{"t":"여울 — 「면과 면이 만나는 선분이 모서리야.」","mis":"M5-2-u5-X03"},{"t":"순달 — 「면은 6개야.」","mis":"M5-2-u5-X04"}],"explanation":["직육면체는 면 6개, 모서리 12개, 꼭짓점 8개예요.","보이지 않는 것까지 세고, 변을 두 번 세지 않아요.","달곰의 말이 틀렸어요."]},{"stem":"이번에는 다른 보기예요. 친구들이 직육면체에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"달곰 — 「꼭짓점은 보이는 것만 세니까 7개야.」","correct":true,"mis_target":"M5-2-u5-X04"},{"t":"여울 — 「모서리와 모서리가 만나는 점이 꼭짓점이야.」","mis":"M5-2-u5-X03"},{"t":"순달 — 「모서리는 12개야.」","mis":"M5-2-u5-X05"}],"explanation":["직육면체는 면 6개, 모서리 12개, 꼭짓점 8개예요.","보이지 않는 것까지 세고, 변을 두 번 세지 않아요.","달곰의 말이 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L02_challenge#1','math',5,2,'u5','L02','tb_g5_2_math_u5_L02_challenge','lesson_challenge','M5-2-u5-C1',2,'mc','auto','나무 블록 그림을 본 친구가 「그림이 평평하니까 블록은 평면도형이야.」라고 했어요. 바르게 고친 말은 어느 것인가요?',ARRAY['M5-2-u5-X01','M5-2-u5-X02','M5-2-u5-X03']::text[],true,'{"seq":1,"concept":"M5-2-u5-C1","difficulty":2,"kind":"mc","stem":"나무 블록 그림을 본 친구가 「그림이 평평하니까 블록은 평면도형이야.」라고 했어요. 바르게 고친 말은 어느 것인가요?","options":[{"t":"그림이 나타내는 블록은 두께가 있으므로 입체도형이다","correct":true},{"t":"맞다 — 그림이 평평하면 평면도형이다","mis":"M5-2-u5-X01"},{"t":"블록이 작으면 평면도형이다","mis":"M5-2-u5-X02"},{"t":"면이 직사각형이므로 블록도 직사각형이다","mis":"M5-2-u5-X03"}],"explanation":["종이에 그린 그림은 평평해요.","그러나 그림이 나타내는 블록은 공간을 차지하고 두께가 있어요.","그래서 블록은 입체도형이에요."],"asset":{"type":"geo","items":[{"w":88.0,"h":66.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[88.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[66,22.0,"sw"],"ㅁ":[22.0,44,"ne"],"ㅇ":[88.0,44,"e"],"ㅂ":[0,66.0,"sw"],"ㅅ":[66,66.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"주사위 그림을 본 친구가 「그림이 평평하니까 주사위는 평면도형이야.」라고 했어요. 바르게 고친 말은 어느 것인가요?","options":[{"t":"그림이 나타내는 주사위는 두께가 있으므로 입체도형이다","correct":true},{"t":"맞다 — 그림이 평평하면 평면도형이다","mis":"M5-2-u5-X01"},{"t":"주사위가 작으면 평면도형이다","mis":"M5-2-u5-X02"},{"t":"면이 직사각형이므로 주사위도 직사각형이다","mis":"M5-2-u5-X03"}],"explanation":["종이에 그린 그림은 평평해요.","그러나 그림이 나타내는 주사위는 공간을 차지하고 두께가 있어요.","그래서 주사위는 입체도형이에요."],"asset":{"type":"geo","items":[{"w":88.0,"h":66.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[88.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[66,22.0,"sw"],"ㅁ":[22.0,44,"ne"],"ㅇ":[88.0,44,"e"],"ㅂ":[0,66.0,"sw"],"ㅅ":[66,66.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"선물 상자 그림을 본 친구가 「그림이 평평하니까 상자는 평면도형이야.」라고 했어요. 바르게 고친 말은 어느 것인가요?","options":[{"t":"그림이 나타내는 상자는 두께가 있으므로 입체도형이다","correct":true},{"t":"맞다 — 그림이 평평하면 평면도형이다","mis":"M5-2-u5-X01"},{"t":"상자가 작으면 평면도형이다","mis":"M5-2-u5-X02"},{"t":"면이 직사각형이므로 상자도 직사각형이다","mis":"M5-2-u5-X03"}],"explanation":["종이에 그린 그림은 평평해요.","그러나 그림이 나타내는 상자는 공간을 차지하고 두께가 있어요.","그래서 상자는 입체도형이에요."],"asset":{"type":"geo","items":[{"w":88.0,"h":66.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[88.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[66,22.0,"sw"],"ㅁ":[22.0,44,"ne"],"ㅇ":[88.0,44,"e"],"ㅂ":[0,66.0,"sw"],"ㅅ":[66,66.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L02_challenge#2','math',5,2,'u5','L02','tb_g5_2_math_u5_L02_challenge','lesson_challenge','M5-2-u5-C2',2,'mc','auto','교실에서 찾은 직육면체 모양의 필통을 살펴보았어요. 필통에서 「직사각형과 직사각형이 만나서 생기는 선분」을 무엇이라고 하나요?',ARRAY['M5-2-u5-X03','M5-2-u5-X11']::text[],true,'{"seq":2,"concept":"M5-2-u5-C2","difficulty":2,"kind":"mc","stem":"교실에서 찾은 직육면체 모양의 필통을 살펴보았어요. 필통에서 「직사각형과 직사각형이 만나서 생기는 선분」을 무엇이라고 하나요?","options":[{"t":"모서리","correct":true},{"t":"꼭짓점","mis":"M5-2-u5-X03"},{"t":"면","mis":"M5-2-u5-X03"},{"t":"밑면","mis":"M5-2-u5-X11"}],"explanation":["직육면체를 둘러싼 직사각형 부분은 면이에요.","면과 면이 만나는 선분은 모서리, 모서리와 모서리가 만나는 점은 꼭짓점이에요.","정답은 「모서리」예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":44.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[110,22.0,"sw"],"ㅁ":[22.0,22,"ne"],"ㅇ":[132.0,22,"e"],"ㅂ":[0,44.0,"sw"],"ㅅ":[110,44.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"교실에서 찾은 직육면체 모양의 필통을 살펴보았어요. 필통에서 「선분과 선분이 만나서 생기는 점」을 무엇이라고 하나요?","options":[{"t":"꼭짓점","correct":true},{"t":"모서리","mis":"M5-2-u5-X03"},{"t":"면","mis":"M5-2-u5-X03"},{"t":"옆면","mis":"M5-2-u5-X11"}],"explanation":["직육면체를 둘러싼 직사각형 부분은 면이에요.","면과 면이 만나는 선분은 모서리, 모서리와 모서리가 만나는 점은 꼭짓점이에요.","정답은 「꼭짓점」이에요."],"asset":{"type":"geo","items":[{"w":132.0,"h":44.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[110,22.0,"sw"],"ㅁ":[22.0,22,"ne"],"ㅇ":[132.0,22,"e"],"ㅂ":[0,44.0,"sw"],"ㅅ":[110,44.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"교실에서 찾은 직육면체 모양의 필통을 살펴보았어요. 필통에서 「직육면체를 둘러싼 직사각형 부분」을 무엇이라고 하나요?","options":[{"t":"면","correct":true},{"t":"모서리","mis":"M5-2-u5-X03"},{"t":"꼭짓점","mis":"M5-2-u5-X03"},{"t":"전개도","mis":"M5-2-u5-X16"}],"explanation":["직육면체를 둘러싼 직사각형 부분은 면이에요.","면과 면이 만나는 선분은 모서리, 모서리와 모서리가 만나는 점은 꼭짓점이에요.","정답은 「면」이에요."],"asset":{"type":"geo","items":[{"w":132.0,"h":44.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[110,22.0,"sw"],"ㅁ":[22.0,22,"ne"],"ㅇ":[132.0,22,"e"],"ㅂ":[0,44.0,"sw"],"ㅅ":[110,44.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L02_challenge#3','math',5,2,'u5','L02','tb_g5_2_math_u5_L02_challenge','lesson_challenge','M5-2-u5-C2',3,'mc','auto','면 6개의 변을 모두 세면 6 × 4 = 24(개)인데 직육면체의 모서리는 12개예요. 왜 그럴까요?',ARRAY['M5-2-u5-X04','M5-2-u5-X05','M5-2-u5-X03']::text[],true,'{"seq":3,"concept":"M5-2-u5-C2","difficulty":3,"kind":"mc","stem":"면 6개의 변을 모두 세면 6 × 4 = 24(개)인데 직육면체의 모서리는 12개예요. 왜 그럴까요?","options":[{"t":"모서리 하나에서 면 두 개의 변이 만나기 때문이다","correct":true},{"t":"보이지 않는 모서리는 세지 않기 때문이다","mis":"M5-2-u5-X04"},{"t":"면 하나에 변이 2개뿐이기 때문이다","mis":"M5-2-u5-X05"},{"t":"꼭짓점이 8개이기 때문이다","mis":"M5-2-u5-X03"}],"explanation":["면 6개에는 변(꼭짓점)이 모두 6 × 4 = 24개 있어요.","변 24개가 둘씩 한 모서리가 되니 24 ÷ 2 = 12예요.","정답은 「모서리 하나에서 면 두 개의 변이 만나기 때문이다」예요."],"variant_rule":{"alt":[{"stem":"면 6개의 꼭짓점을 모두 세면 6 × 4 = 24(개)인데 직육면체의 꼭짓점은 8개예요. 왜 그럴까요?","options":[{"t":"꼭짓점 하나에 면 세 개의 꼭짓점이 모이기 때문이다","correct":true},{"t":"보이는 꼭짓점만 세기 때문이다","mis":"M5-2-u5-X04"},{"t":"꼭짓점 하나에 면 두 개가 모이기 때문이다","mis":"M5-2-u5-X05"},{"t":"모서리가 12개이기 때문이다","mis":"M5-2-u5-X03"}],"explanation":["면 6개에는 변(꼭짓점)이 모두 6 × 4 = 24개 있어요.","면의 꼭짓점 24개가 셋씩 한 꼭짓점이 되니 24 ÷ 3 = 8이에요.","정답은 「꼭짓점 하나에 면 세 개의 꼭짓점이 모이기 때문이다」예요."]},{"stem":"직육면체의 모서리 수를 바르게 구한 방법은 어느 것인가요?","options":[{"t":"면 6개의 변을 모두 센 24를 2로 나눈다","correct":true},{"t":"면 6개의 변을 모두 센 24를 그대로 쓴다","mis":"M5-2-u5-X05"},{"t":"보이는 모서리 9개만 센다","mis":"M5-2-u5-X04"},{"t":"꼭짓점 8개에 4를 더한다","mis":"M5-2-u5-X03"}],"explanation":["면 6개에는 변(꼭짓점)이 모두 6 × 4 = 24개 있어요.","변 24개가 둘씩 한 모서리가 되니 24 ÷ 2 = 12예요.","정답은 「면 6개의 변을 모두 센 24를 2로 나눈다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L02_challenge#4','math',5,2,'u5','L02','tb_g5_2_math_u5_L02_challenge','lesson_challenge','M5-2-u5-C2',3,'ox','auto','직육면체에서 면과 면이 만나는 선분을 꼭짓점이라고 해요.',ARRAY['M5-2-u5-X03']::text[],true,'{"seq":4,"concept":"M5-2-u5-C2","difficulty":3,"kind":"ox","stem":"직육면체에서 면과 면이 만나는 선분을 꼭짓점이라고 해요.","answer":"X","reason_options":[{"t":"면과 면이 만나는 선분은 모서리이므로","correct":true},{"t":"두 면이 만나는 곳은 모두 꼭짓점이므로","mis":"M5-2-u5-X03"}],"mis":"M5-2-u5-X03","explanation":["뜻을 떠올려 하나씩 따져 봐요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「면과 면이 만나는 선분은 모서리이므로」를 골라요."],"variant_rule":{"alt":[{"stem":"직육면체의 모서리는 24개예요.","answer":"X","reason_options":[{"t":"면 6개의 변 24개가 둘씩 만나 모서리는 12개이므로","correct":true},{"t":"면 하나에 변이 4개이고 면이 6개이므로","mis":"M5-2-u5-X05"}],"explanation":["뜻을 떠올려 하나씩 따져 봐요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「면 6개의 변 24개가 둘씩 만나 모서리는 12개이므로」를 골라요."]},{"stem":"상자를 한쪽에서 볼 때 보이지 않는 꼭짓점도 꼭짓점의 수에 넣어야 해요.","answer":"O","reason_options":[{"t":"직육면체의 꼭짓점은 보이지 않는 것까지 모두 8개이므로","correct":true},{"t":"보이는 꼭짓점만 세면 되므로","mis":"M5-2-u5-X04"}],"explanation":["뜻을 떠올려 하나씩 따져 봐요.","맞는 말이면 O, 틀린 말이면 X — 정답은 O예요.","까닭으로 「직육면체의 꼭짓점은 보이지 않는 것까지 모두 8개이므로」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L02_challenge#5','math',5,2,'u5','L02','tb_g5_2_math_u5_L02_challenge','lesson_challenge','M5-2-u5-C2',3,'mc','auto','가: 원 모양 면이 있는 통 / 나: 직사각형 6개로 둘러싸인 상자 / 다: 정사각형 2개와 직사각형 4개로 둘러싸인 상자 / 라: 직사각형 6개로 둘러싸인 납작한 상자 / 마: 육각형 면이 있는 기둥 / 바: 삼각형 면이 있는 기둥. 직육면체가 아닌 것을 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u5-X02','M5-2-u5-X06']::text[],true,'{"seq":5,"concept":"M5-2-u5-C2","difficulty":3,"kind":"mc","stem":"가: 원 모양 면이 있는 통 / 나: 직사각형 6개로 둘러싸인 상자 / 다: 정사각형 2개와 직사각형 4개로 둘러싸인 상자 / 라: 직사각형 6개로 둘러싸인 납작한 상자 / 마: 육각형 면이 있는 기둥 / 바: 삼각형 면이 있는 기둥. 직육면체가 아닌 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 마, 바","correct":true},{"t":"가, 바","mis":"M5-2-u5-X02"},{"t":"가, 다, 마, 바","mis":"M5-2-u5-X06"},{"t":"마, 바","mis":"M5-2-u5-X02"}],"explanation":["직사각형 6개로 둘러싸인 입체도형만 직육면체예요(정사각형도 직사각형).","원·삼각형·육각형·사다리꼴 모양의 면이 있으면 직육면체가 아니에요.","직육면체가 아닌 것은 가, 마, 바예요."],"variant_rule":{"alt":[{"stem":"가: 직사각형 6개로 둘러싸인 캠핑 상자 / 나: 원 모양 면이 있는 통 / 다: 삼각형 면이 있는 샌드위치 상자 / 라: 정사각형 6개로 둘러싸인 주사위. 직육면체가 아닌 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"나, 다","correct":true},{"t":"나","mis":"M5-2-u5-X02"},{"t":"나, 다, 라","mis":"M5-2-u5-X06"},{"t":"다","mis":"M5-2-u5-X02"}],"explanation":["직사각형 6개로 둘러싸인 입체도형만 직육면체예요(정사각형도 직사각형).","원·삼각형·육각형·사다리꼴 모양의 면이 있으면 직육면체가 아니에요.","직육면체가 아닌 것은 나, 다예요."]},{"stem":"가: 직사각형 6개로 둘러싸인 서랍 / 나: 양쪽 면이 사다리꼴인 과자 상자 / 다: 직사각형 6개로 둘러싸인 도시락통 / 라: 원 모양 면이 있는 통. 직육면체가 아닌 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"나, 라","correct":true},{"t":"라","mis":"M5-2-u5-X02"},{"t":"가, 나, 라","mis":"M5-2-u5-X18"},{"t":"나","mis":"M5-2-u5-X02"}],"explanation":["직사각형 6개로 둘러싸인 입체도형만 직육면체예요(정사각형도 직사각형).","원·삼각형·육각형·사다리꼴 모양의 면이 있으면 직육면체가 아니에요.","직육면체가 아닌 것은 나, 라예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=E