INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L02_challenge#6','math',5,2,'u5','L02','tb_g5_2_math_u5_L02_challenge','lesson_challenge','M5-2-u5-C2',3,'sa','auto','교과서 118쪽에 나온 가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체예요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u5-C2","difficulty":3,"kind":"sa","stem":"교과서 118쪽에 나온 가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체예요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["직육면체에는 길이가 같은 모서리가 4개씩 3묶음 있어요.","3 × 4 + 2 × 4 + 5 × 4 = 40이에요.","그래서 40 cm예요."],"mis":"M5-2-u5-X07","asset":{"type":"geo","items":[{"w":88.0,"h":132.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[88.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[66,22.0,"sw"],"ㅁ":[22.0,110,"ne"],"ㅇ":[88.0,110,"e"],"ㅂ":[0,132.0,"sw"],"ㅅ":[66,132.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33.0,140.0],"3 cm"],[[93.0,125.0],"2 cm"],[[48,77.0],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"문제로 마무리 8번에 나온 가로 5 cm, 세로 3 cm, 높이 4 cm인 직육면체예요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["직육면체에는 길이가 같은 모서리가 4개씩 3묶음 있어요.","5 × 4 + 3 × 4 + 4 × 4 = 48이에요.","그래서 48 cm예요."],"asset":{"type":"geo","items":[{"w":143.0,"h":121.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[110,33.0,"sw"],"ㅁ":[33.0,88,"ne"],"ㅇ":[143.0,88,"e"],"ㅂ":[0,121.0,"sw"],"ㅅ":[110,121.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[55.0,129.0],"5 cm"],[[142.5,108.5],"3 cm"],[[92,77.0],"4 cm"]]}],"tag":false}},{"stem":"수학익힘 77쪽에 나온 가로 8 cm, 세로 6 cm, 높이 5 cm인 직육면체예요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["76"],"explanation":["직육면체에는 길이가 같은 모서리가 4개씩 3묶음 있어요.","8 × 4 + 6 × 4 