INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L02_challenge#8','math',5,2,'u5','L02','tb_g5_2_math_u5_L02_challenge','lesson_challenge','M5-2-u5-C2',4,'sa','auto','단원 평가에 나온 가로 7 cm, 세로 3 cm인 직육면체의 모든 모서리의 길이의 합이 56 cm예요. 높이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u5-C2","difficulty":4,"kind":"sa","stem":"단원 평가에 나온 가로 7 cm, 세로 3 cm인 직육면체의 모든 모서리의 길이의 합이 56 cm예요. 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["길이가 같은 모서리가 4개씩이니 가로·세로·높이 하나씩의 합은 56 ÷ 4 = 14예요.","높이는 14 − 7 − 3 = 4예요.","그래서 4 cm예요."],"mis":"M5-2-u5-X07","variant_rule":{"alt":[{"stem":"문제로 마무리 8번에 나온 가로 5 cm, 세로 3 cm인 직육면체의 모든 모서리의 길이의 합이 48 cm예요. 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["길이가 같은 모서리가 4개씩이니 가로·세로·높이 하나씩의 합은 48 ÷ 4 = 12예요.","높이는 12 − 5 − 3 = 4예요.","그래서 4 cm예요."]},{"stem":"교과서 118쪽에 나온 가로 3 cm, 세로 2 cm인 직육면체의 모든 모서리의 길이의 합이 40 cm예요. 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["길이가 같은 모서리가 4개씩이니 가로·세로·높이 하나씩의 합은 40 ÷ 4 = 10이에요.","높이는 10 − 3 − 2 = 5예요.","그래서 5 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L02_challenge#9','math',5,2,'u5','L02','tb_g5_2_math_u5_L02_challenge','lesson_challenge','M5-2-u5-C2',4,'sa','auto','단원 평가에 나온 가로 9 cm, 세로 7 cm, 높이 3 cm인 직육면체예요. 길이가 7 cm인 모서리의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u5-C2","difficulty":4,"kind":"sa","stem":"단원 평가에 나온 가로 9 cm, 세로 7 cm, 높이 3 cm인 직육면체예요. 길이가 7 cm인 모서리의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["직육면체에서 세로와 길이가 같은 모서리는 모두 4개예요.","7 × 4 = 28이에요.","그래서 28 cm예요."],"mis":"M5-2-u5-X07","asset":{"type":"geo","items":[{"w":150.0,"h":78.0,"pts":{"ㄱ":[42.0,0,"nw"],"ㄹ":[150.0,0,"ne"],"ㄴ":[0,42.0,"w"],"ㄷ":[108,42.0,"sw"],"ㅁ":[42.0,36,"ne"],"ㅇ":[150.0,36,"e"],"ㅂ":[0,78.0,"sw"],"ㅅ":[108,78.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[54.0,86.0],"9 cm"],[[145.0,61.0],"7 cm"],[[90,60.0],"3 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가에 나온 가로 9 cm, 세로 4 cm, 높이 6 cm인 직육면체예요. 길이가 6 cm인 모서리의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["직육면체에서 높이와 길이가 같은 모서리는 모두 4개예요.","6 × 4 = 24예요.","그래서 24 cm예요."],"asset":{"type":"geo","items":[{"w":143.0,"h":104.0,"pts":{"ㄱ":[26.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,26.0,"w"],"ㄷ":[117,26.0,"sw"],"ㅁ":[26.0,78,"ne"],"ㅇ":[143.0,78,"e"],"ㅂ":[0,104.0,"sw"],"ㅅ":[117,104.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[58.5,112.0],"9 cm"],[[146.0,95.0],"4 cm"],[[99,65.0],"6 cm"]]}],"tag":false}},{"stem":"단원 평가에 나온 가로 6 cm, 세로 9 cm, 높이 5 cm인 직육면체예요. 길이가 9 cm인 모서리의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["직육면체에서 세로와 길이가 같은 모서리는 모두 4개예요.","9 × 4 = 36이에요.","그래서 36 cm예요."],"asset":{"type":"geo","items":[{"w":147.0,"h":133.0,"pts":{"ㄱ":[63.0,0,"nw"],"ㄹ":[147.0,0,"ne"],"ㄴ":[0,63.0,"w"],"ㄷ":[84,63.0,"sw"],"ㅁ":[63.0,70,"ne"],"ㅇ":[147.0,70,"e"],"ㅂ":[0,133.0,"sw"],"ㅅ":[84,133.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[42.0,141.0],"6 cm"],[[131.5,105.5],"9 cm"],[[66,98.0],"5 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L02_challenge#10','math',5,2,'u5','L02','tb_g5_2_math_u5_L02_challenge','lesson_challenge','M5-2-u5-C2',4,'essay','teacher','순달이는 「직육면체는 면이 6개이고 면마다 변이 4개씩 있으니 모서리는 24개야.」라고 했어요. 순달이의 말이 맞는지 판단하고, 직육면체의 모서리가 몇 개인지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u5-C2","difficulty":4,"kind":"essay","stem":"순달이는 「직육면체는 면이 6개이고 면마다 변이 4개씩 있으니 모서리는 24개야.」라고 했어요. 순달이의 말이 맞는지 판단하고, 직육면체의 모서리가 몇 개인지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 순달이의 말은 틀렸다. 면 6개의 변은 6 × 4 = 24(개)이지만, 모서리 하나에서 면 두 개의 변이 만나므로 변 두 개가 모서리 하나가 된다. 그래서 모서리는 24 ÷ 2 = 12(개)이다.","scoring_points":["순달이의 말이 틀렸다고 썼는가","모서리 하나에서 면 두 개의 변이 만난다고 썼는가","모서리가 12개라고 구했는가"]},"explanation":["면 6개의 변은 6 × 4 = 24(개)예요.","모서리 하나에 면 두 개의 변이 만나요.","24 ÷ 2 = 12(개)예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
