INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L03_basic#3','math',5,2,'u5','L03','tb_g5_2_math_u5_L03_basic','lesson_basic','M5-2-u5-C3',1,'mc','auto','형성 평가 그림이에요. 가: 윗변이 짧은 사다리꼴 / 나: 네 변의 길이가 같고 네 각이 직각인 사각형 / 다: 세로가 더 긴 직사각형 / 라: 네 각이 직각이 아닌 사각형. 정육면체의 면이 될 수 있는 도형은 어느 것인가요?',ARRAY['M5-2-u5-X19','M5-2-u5-X02']::text[],true,'{"seq":3,"concept":"M5-2-u5-C3","difficulty":1,"kind":"mc","stem":"형성 평가 그림이에요. 가: 윗변이 짧은 사다리꼴 / 나: 네 변의 길이가 같고 네 각이 직각인 사각형 / 다: 세로가 더 긴 직사각형 / 라: 네 각이 직각이 아닌 사각형. 정육면체의 면이 될 수 있는 도형은 어느 것인가요?","options":[{"t":"나","correct":true},{"t":"다","mis":"M5-2-u5-X19"},{"t":"가","mis":"M5-2-u5-X02"},{"t":"라","mis":"M5-2-u5-X02"}],"explanation":["정육면체는 정사각형 6개로 둘러싸인 입체도형이에요.","그래서 면은 네 변의 길이가 같고 네 각이 직각인 정사각형이에요.","정답은 「나」예요."],"variant_rule":{"alt":[{"stem":"단원 평가 그림이에요. 가: 삼각형 / 나: 네 변의 길이가 같고 네 각이 직각인 사각형 / 다: 가로가 더 긴 직사각형. 정육면체의 면이 될 수 있는 도형은 어느 것인가요?","options":[{"t":"나","correct":true},{"t":"다","mis":"M5-2-u5-X19"},{"t":"가","mis":"M5-2-u5-X02"},{"t":"가, 나, 다","mis":"M5-2-u5-X19"}],"explanation":["정육면체는 정사각형 6개로 둘러싸인 입체도형이에요.","그래서 면은 네 변의 길이가 같고 네 각이 직각인 정사각형이에요.","정답은 「나」예요."]},{"stem":"정육면체의 면은 어떤 도형인가요?","options":[{"t":"크기가 같은 정사각형","correct":true},{"t":"크기가 다른 직사각형","mis":"M5-2-u5-X19"},{"t":"사다리꼴","mis":"M5-2-u5-X02"},{"t":"삼각형","mis":"M5-2-u5-X02"}],"explanation":["정육면체는 정사각형 6개로 둘러싸인 입체도형이에요.","그래서 면은 네 변의 길이가 같고 네 각이 직각인 정사각형이에요.","정답은 「크기가 같은 정사각형」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L03_basic#4','math',5,2,'u5','L03','tb_g5_2_math_u5_L03_basic','lesson_basic','M5-2-u5-C3',1,'mc','auto','교실에서 정육면체 모양의 물건을 찾았어요. 정육면체 모양인 것은 어느 것인가요?',ARRAY['M5-2-u5-X06','M5-2-u5-X02']::text[],true,'{"seq":4,"concept":"M5-2-u5-C3","difficulty":1,"kind":"mc","stem":"교실에서 정육면체 모양의 물건을 찾았어요. 정육면체 모양인 것은 어느 것인가요?","options":[{"t":"주사위","correct":true},{"t":"필통","mis":"M5-2-u5-X06"},{"t":"사물함","mis":"M5-2-u5-X06"},{"t":"교과서","mis":"M5-2-u5-X02"}],"explanation":["정육면체는 정사각형 6개로 둘러싸인 입체도형이에요.","쓰임새나 색이 아니라 면의 모양과 수로 정해요.","정답은 「주사위」예요."],"variant_rule":{"alt":[{"stem":"동생과 방을 정리하며 모은 물건(갑 휴지, 루빅큐브, 탁상시계)의 같은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"정사각형 6개로 둘러싸여 있다","correct":true},{"t":"모두 장난감이다","mis":"M5-2-u5-X02"},{"t":"모두 색이 같다","mis":"M5-2-u5-X02"},{"t":"직사각형 4개로 둘러싸여 있다","mis":"M5-2-u5-X04"}],"explanation":["정육면체는 정사각형 6개로 둘러싸인 입체도형이에요.","쓰임새나 색이 아니라 면의 모양과 수로 정해요.","정답은 「정사각형 6개로 둘러싸여 있다」예요."],"asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"정사각형 6개로 둘러싸인 입체도형을 무엇이라고 하나요?","options":[{"t":"정육면체","correct":true},{"t":"정사각형","mis":"M5-2-u5-X01"},{"t":"평면도형","mis":"M5-2-u5-X01"},{"t":"삼각형","mis":"M5-2-u5-X02"}],"explanation":["정육면체는 정사각형 6개로 둘러싸인 입체도형이에요.","쓰임새나 색이 아니라 면의 모양과 수로 정해요.","정답은 「정육면체」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=E