INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L03_basic#5','math',5,2,'u5','L03','tb_g5_2_math_u5_L03_basic','lesson_basic','M5-2-u5-C3',2,'mc','auto','직육면체와 정육면체의 같은 점이 아닌 것은 어느 것인가요?',ARRAY['M5-2-u5-X18']::text[],true,'{"seq":5,"concept":"M5-2-u5-C3","difficulty":2,"kind":"mc","stem":"직육면체와 정육면체의 같은 점이 아닌 것은 어느 것인가요?","options":[{"t":"모든 모서리의 길이가 같다","correct":true},{"t":"면이 6개다","mis":"M5-2-u5-X18"},{"t":"모서리가 12개다","mis":"M5-2-u5-X18"},{"t":"꼭짓점이 8개다","mis":"M5-2-u5-X18"}],"explanation":["면은 6개, 모서리는 12개, 꼭짓점은 8개로 수가 같아요.","정육면체는 면이 모두 크기가 같은 정사각형이라 모든 모서리의 길이가 같아요.","정답은 「모든 모서리의 길이가 같다」예요."],"variant_rule":{"alt":[{"stem":"직육면체와 정육면체의 다른 점은 어느 것인가요?","options":[{"t":"면의 모양 — 정육면체는 면이 모두 정사각형이다","correct":true},{"t":"면의 수 — 정육면체는 면이 8개다","mis":"M5-2-u5-X04"},{"t":"모서리의 수 — 정육면체는 모서리가 6개다","mis":"M5-2-u5-X05"},{"t":"꼭짓점의 수 — 정육면체는 꼭짓점이 12개다","mis":"M5-2-u5-X05"}],"explanation":["면은 6개, 모서리는 12개, 꼭짓점은 8개로 수가 같아요.","정육면체는 면이 모두 크기가 같은 정사각형이라 모든 모서리의 길이가 같아요.","정답은 「면의 모양 — 정육면체는 면이 모두 정사각형이다」예요."]},{"stem":"정육면체에만 있는 성질은 어느 것인가요?","options":[{"t":"모든 면의 크기가 같다","correct":true},{"t":"면이 직사각형이다","mis":"M5-2-u5-X06"},{"t":"꼭짓점이 8개다","mis":"M5-2-u5-X18"},{"t":"평행한 면이 3쌍이다","mis":"M5-2-u5-X18"}],"explanation":["면은 6개, 모서리는 12개, 꼭짓점은 8개로 수가 같아요.","정육면체는 면이 모두 크기가 같은 정사각형이라 모든 모서리의 길이가 같아요.","정답은 「모든 면의 크기가 같다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L03_basic#6','math',5,2,'u5','L03','tb_g5_2_math_u5_L03_basic','lesson_basic','M5-2-u5-C3',2,'sa','auto','한 모서리의 길이가 3 cm인 정육면체 모양이에요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u5-C3","difficulty":2,"kind":"sa","stem":"한 모서리의 길이가 3 cm인 정육면체 모양이에요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["정육면체는 모서리 12개의 길이가 모두 같아요.","3 × 12 = 36이에요.","그래서 36 cm예요."],"mis":"M5-2-u5-X07","asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33,111],"3 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"과자 상자 — 한 모서리의 길이가 5 cm인 정육면체 모양이에요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["정육면체는 모서리 12개의 길이가 모두 같아요.","5 × 12 = 60이에요.","그래서 60 cm예요."],"asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33,111],"5 cm"]]}],"tag":false}},{"stem":"한 모서리의 길이가 8 cm인 정육면체 모양이에요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["96"],"explanation":["정육면체는 모서리 12개의 길이가 모두 같아요.","8 × 12 = 96이에요.","그래서 96 cm예요."],"asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33,111],"8 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L03_basic#7','math',5,2,'u5','L03','tb_g5_2_math_u5_L03_basic','lesson_basic','M5-2-u5-C3',2,'error','auto','정육면체에 대해 친구들이 말했어요. 잘못 설명한 친구는 누구인가요?',ARRAY['M5-2-u5-X19','M5-2-u5-X06']::text[],true,'{"seq":7,"concept":"M5-2-u5-C3","difficulty":2,"kind":"error","stem":"정육면체에 대해 친구들이 말했어요. 잘못 설명한 친구는 누구인가요?","options":[{"t":"민지 — 「정육면체는 모든 모서리의 길이가 달라요.」","correct":true,"mis_target":"M5-2-u5-X19"},{"t":"연희 — 「정육면체는 면의 크기가 모두 같아요.」","mis":"M5-2-u5-X06"},{"t":"세영 — 「정육면체는 정사각형으로 둘러싸여 있어요.」","mis":"M5-2-u5-X06"}],"explanation":["정육면체는 정사각형 6개로 둘러싸여 있어요.","그래서 모든 모서리의 길이가 같고 면의 크기도 모두 같아요.","잘못 설명한 친구는 민지예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 정육면체에 대해 친구들이 말했어요. 잘못 설명한 친구는 누구인가요?","options":[{"t":"서연 — 「정육면체는 모서리의 길이가 서로 달라요.」","correct":true,"mis_target":"M5-2-u5-X19"},{"t":"태민 — 「정육면체는 평행한 면이 모두 3쌍이에요.」","mis":"M5-2-u5-X06"},{"t":"지우 — 「직육면체는 직사각형 6개로 둘러싸인 입체도형을 말해요.」","mis":"M5-2-u5-X06"}],"explanation":["정육면체는 정사각형 6개로 둘러싸여 있어요.","그래서 모든 모서리의 길이가 같고 면의 크기도 모두 같아요.","잘못 설명한 친구는 서연이에요."]},{"stem":"이번에는 다른 보기예요. 정육면체에 대해 친구들이 말했어요. 잘못 설명한 친구는 누구인가요?","options":[{"t":"민지 — 「정육면체는 면의 크기가 서로 달라요.」","correct":true,"mis_target":"M5-2-u5-X19"},{"t":"세영 — 「정육면체와 직육면체는 꼭짓점의 수가 같아요.」","mis":"M5-2-u5-X06"},{"t":"연희 — 「정육면체는 모서리가 12개예요.」","mis":"M5-2-u5-X06"}],"explanation":["정육면체는 정사각형 6개로 둘러싸여 있어요.","그래서 모든 모서리의 길이가 같고 면의 크기도 모두 같아요.","잘못 설명한 친구는 민지예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L03_basic#8','math',5,2,'u5','L03','tb_g5_2_math_u5_L03_basic','lesson_basic','M5-2-u5-C3',2,'ox','auto','정육면체는 직육면체라고 할 수 있어요.',ARRAY['M5-2-u5-X06']::text[],true,'{"seq":8,"concept":"M5-2-u5-C3","difficulty":2,"kind":"ox","stem":"정육면체는 직육면체라고 할 수 있어요.","answer":"O","reason_options":[{"t":"정사각형은 직사각형이므로 정사각형 6개는 직사각형 6개이기도 하므로","correct":true},{"t":"이름이 다르므로","mis":"M5-2-u5-X06"}],"mis":"M5-2-u5-X06","explanation":["정육면체의 뜻과 성질을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 O예요.","까닭으로 「정사각형은 직사각형이므로 정사각형 6개는 직사각형 6개이기도 하므로」를 골라요."],"variant_rule":{"alt":[{"stem":"직육면체는 모두 정육면체라고 할 수 있어요.","answer":"X","reason_options":[{"t":"직육면체의 면은 정사각형이 아닐 수 있으므로","correct":true},{"t":"면이 6개로 같으므로","mis":"M5-2-u5-X06"}],"explanation":["정육면체의 뜻과 성질을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「직육면체의 면은 정사각형이 아닐 수 있으므로」를 골라요."]},{"stem":"정육면체는 모든 모서리의 길이가 같아요.","answer":"O","reason_options":[{"t":"면이 모두 크기가 같은 정사각형이므로","correct":true},{"t":"마주 보는 모서리만 같으므로","mis":"M5-2-u5-X06"}],"explanation":["정육면체의 뜻과 성질을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 O예요.","까닭으로 「면이 모두 크기가 같은 정사각형이므로」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L03_basic#9','math',5,2,'u5','L03','tb_g5_2_math_u5_L03_basic','lesson_basic','M5-2-u5-C3',2,'mc','auto','친구가 「정육면체는 직육면체가 아니야.」라고 했어요. 바르게 고친 말은 어느 것인가요?',ARRAY['M5-2-u5-X06','M5-2-u5-X04']::text[],true,'{"seq":9,"concept":"M5-2-u5-C3","difficulty":2,"kind":"mc","stem":"친구가 「정육면체는 직육면체가 아니야.」라고 했어요. 바르게 고친 말은 어느 것인가요?","options":[{"t":"정사각형은 직사각형이므로 정육면체는 직육면체라고 할 수 있다","correct":true},{"t":"맞다 — 이름이 다르다","mis":"M5-2-u5-X06"},{"t":"직육면체는 모두 정육면체다","mis":"M5-2-u5-X06"},{"t":"면의 수가 달라서 견줄 수 없다","mis":"M5-2-u5-X04"}],"explanation":["정사각형은 네 각이 직각이므로 직사각형이에요.","정육면체는 직육면체의 한 종류이고, 면·모서리·꼭짓점의 수는 같아요.","정답은 「정사각형은 직사각형이므로 정육면체는 직육면체라고 할 수 있다」예요."],"variant_rule":{"alt":[{"stem":"친구가 「직육면체는 모두 정육면체야.」라고 했어요. 바르게 고친 말은 어느 것인가요?","options":[{"t":"직육면체의 면은 정사각형이 아닐 수도 있으므로 모두 정육면체는 아니다","correct":true},{"t":"맞다 — 면이 6개로 같다","mis":"M5-2-u5-X06"},{"t":"정육면체는 직육면체가 아니다","mis":"M5-2-u5-X06"},{"t":"직육면체는 꼭짓점이 더 많다","mis":"M5-2-u5-X04"}],"explanation":["정사각형은 네 각이 직각이므로 직사각형이에요.","정육면체는 직육면체의 한 종류이고, 면·모서리·꼭짓점의 수는 같아요.","정답은 「직육면체의 면은 정사각형이 아닐 수도 있으므로 모두 정육면체는 아니다」예요."]},{"stem":"친구가 「정육면체는 모서리가 짧아서 모서리 수가 직육면체보다 적어.」라고 했어요. 바르게 고친 말은 어느 것인가요?","options":[{"t":"정육면체도 모서리가 12개로 직육면체와 같다","correct":true},{"t":"맞다 — 크기가 작으면 모서리가 적다","mis":"M5-2-u5-X04"},{"t":"정육면체는 모서리가 6개다","mis":"M5-2-u5-X05"},{"t":"정육면체는 모서리가 24개다","mis":"M5-2-u5-X05"}],"explanation":["정사각형은 네 각이 직각이므로 직사각형이에요.","정육면체는 직육면체의 한 종류이고, 면·모서리·꼭짓점의 수는 같아요.","정답은 「정육면체도 모서리가 12개로 직육면체와 같다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L03_basic#10','math',5,2,'u5','L03','tb_g5_2_math_u5_L03_basic','lesson_basic','M5-2-u5-C3',3,'sa','auto','직육면체 모양의 빵(15 cm, 7 cm, 7 cm)을 잘라 만들 수 있는 가장 큰 정육면체의 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M5-2-u5-C3","difficulty":3,"kind":"sa","stem":"직육면체 모양의 빵(15 cm, 7 cm, 7 cm)을 잘라 만들 수 있는 가장 큰 정육면체의 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["정육면체는 모든 모서리의 길이가 같아요.","빵의 가장 짧은 모서리가 7 cm라 더 길게 자를 수 없어요.","그래서 7 cm예요."],"mis":"M5-2-u5-X08","variant_rule":{"alt":[{"stem":"정육면체를 보고 가로와 세로를 알맞게 썼을 때 한 모서리가 8 cm인 정육면체의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["정육면체는 모든 모서리의 길이가 같아요.","정육면체는 모든 모서리의 길이가 같으니 가로도 8 cm예요.","그래서 8 cm예요."]},{"stem":"직육면체 모양의 빵(15 cm, 7 cm, 7 cm)을 잘라 가장 큰 정육면체를 만들었을 때 그 정육면체의 모든 모서리의 길이의 합는 몇 cm인가요? 숫자로 쓰세요.","answer":["84"],"explanation":["정육면체는 모든 모서리의 길이가 같아요.","가장 큰 정육면체의 한 모서리는 7 cm이고 7 × 12 = 84예요.","그래서 84 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L03_challenge#1','math',5,2,'u5','L03','tb_g5_2_math_u5_L03_challenge','lesson_challenge','M5-2-u5-C3',2,'sa','auto','정육면체의 모든 모서리의 길이의 합이 120 cm예요. 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u5-C3","difficulty":2,"kind":"sa","stem":"정육면체의 모든 모서리의 길이의 합이 120 cm예요. 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["정육면체는 모서리 12개의 길이가 모두 같아요.","120 ÷ 12 = 10이에요.","그래서 10 cm예요."],"mis":"M5-2-u5-X07","variant_rule":{"alt":[{"stem":"정육면체의 모든 모서리의 길이의 합이 96 cm예요. 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["정육면체는 모서리 12개의 길이가 모두 같아요.","96 ÷ 12 = 8이에요.","그래서 8 cm예요."]},{"stem":"정육면체의 모든 모서리의 길이의 합이 60 cm예요. 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["정육면체는 모서리 12개의 길이가 모두 같아요.","60 ÷ 12 = 5예요.","그래서 5 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L03_challenge#2','math',5,2,'u5','L03','tb_g5_2_math_u5_L03_challenge','lesson_challenge','M5-2-u5-C3',2,'ox','auto','정육면체의 꼭짓점은 직육면체의 꼭짓점보다 적어요.',ARRAY['M5-2-u5-X04']::text[],true,'{"seq":2,"concept":"M5-2-u5-C3","difficulty":2,"kind":"ox","stem":"정육면체의 꼭짓점은 직육면체의 꼭짓점보다 적어요.","answer":"X","reason_options":[{"t":"둘 다 꼭짓점이 8개이므로","correct":true},{"t":"정육면체가 더 작은 도형이므로","mis":"M5-2-u5-X04"}],"mis":"M5-2-u5-X04","explanation":["정육면체의 뜻과 성질을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「둘 다 꼭짓점이 8개이므로」를 골라요."],"variant_rule":{"alt":[{"stem":"한 모서리가 5 cm인 정육면체의 모든 모서리의 길이의 합은 60 cm예요.","answer":"O","reason_options":[{"t":"5 × 12 = 60이므로","correct":true},{"t":"5 × 6 = 30이므로","mis":"M5-2-u5-X07"}],"explanation":["정육면체의 뜻과 성질을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 O예요.","까닭으로 「5 × 12 = 60이므로」를 골라요."]},{"stem":"면 하나가 정사각형인 직육면체는 정육면체예요.","answer":"X","reason_options":[{"t":"면 6개가 모두 정사각형이어야 정육면체이므로","correct":true},{"t":"정사각형 면이 하나라도 있으면 되므로","mis":"M5-2-u5-X06"}],"explanation":["정육면체의 뜻과 성질을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「면 6개가 모두 정사각형이어야 정육면체이므로」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L03_challenge#3','math',5,2,'u5','L03','tb_g5_2_math_u5_L03_challenge','lesson_challenge','M5-2-u5-C3',3,'error','auto','친구들이 정육면체에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-2-u5-X06','M5-2-u5-X04']::text[],true,'{"seq":3,"concept":"M5-2-u5-C3","difficulty":3,"kind":"error","stem":"친구들이 정육면체에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지우 — 「정육면체는 면이 정사각형이니까 직육면체가 아니야.」","correct":true,"mis_target":"M5-2-u5-X06"},{"t":"윤수 — 「정육면체는 모서리의 길이가 모두 같아.」","mis":"M5-2-u5-X06"},{"t":"서연 — 「정육면체의 꼭짓점은 8개야.」","mis":"M5-2-u5-X04"}],"explanation":["정육면체는 정사각형 6개로 둘러싸인 직육면체예요.","모서리 12개의 길이가 모두 같아요.","지우의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 정육면체에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 「직육면체도 모든 모서리의 길이가 같아.」","correct":true,"mis_target":"M5-2-u5-X06"},{"t":"지우 — 「정육면체는 정사각형 6개로 둘러싸여 있어.」","mis":"M5-2-u5-X02"},{"t":"윤수 — 「정육면체의 모서리는 12개야.」","mis":"M5-2-u5-X05"}],"explanation":["정육면체는 정사각형 6개로 둘러싸인 직육면체예요.","모서리 12개의 길이가 모두 같아요.","태민의 말이 틀렸어요."]},{"stem":"이번에는 다른 보기예요. 친구들이 정육면체에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"연희 — 「한 모서리가 3 cm인 정육면체의 모서리 길이의 합은 18 cm야.」","correct":true,"mis_target":"M5-2-u5-X07"},{"t":"세영 — 「정육면체는 직육면체라고 할 수 있어.」","mis":"M5-2-u5-X06"},{"t":"민지 — 「정육면체의 면은 6개야.」","mis":"M5-2-u5-X04"}],"explanation":["정육면체는 정사각형 6개로 둘러싸인 직육면체예요.","모서리 12개의 길이가 모두 같아요.","연희의 말이 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L03_challenge#4','math',5,2,'u5','L03','tb_g5_2_math_u5_L03_challenge','lesson_challenge','M5-2-u5-C3',3,'mc','auto','직육면체와 정육면체에 대해 친구들이 말했어요. 지우 「직육면체는 직사각형 6개로 둘러싸인 입체도형을 말해요.」 · 윤수 「직육면체는 옆면이 서로 평행해요.」 · 서연 「정육면체는 모서리의 길이가 서로 달라요.」 · 태민 「정육면체는 평행한 면이 모두 3쌍이에요.」 바르게 설명한 친구를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u5-X12','M5-2-u5-X19']::text[],true,'{"seq":4,"concept":"M5-2-u5-C3","difficulty":3,"kind":"mc","stem":"직육면체와 정육면체에 대해 친구들이 말했어요. 지우 「직육면체는 직사각형 6개로 둘러싸인 입체도형을 말해요.」 · 윤수 「직육면체는 옆면이 서로 평행해요.」 · 서연 「정육면체는 모서리의 길이가 서로 달라요.」 · 태민 「정육면체는 평행한 면이 모두 3쌍이에요.」 바르게 설명한 친구를 모두 고른 것은 어느 것인가요?","options":[{"t":"지우, 태민","correct":true},{"t":"지우, 윤수","mis":"M5-2-u5-X12"},{"t":"서연, 태민","mis":"M5-2-u5-X19"},{"t":"지우, 윤수, 태민","mis":"M5-2-u5-X12"}],"explanation":["직육면체는 직사각형 6개, 정육면체는 정사각형 6개로 둘러싸여 있고, 면 6·모서리 12·꼭짓점 8로 수가 같아요.","직육면체의 옆면은 이웃하면 수직이고, 정육면체는 모서리의 길이가 모두 같아요.","바르게 설명한 친구는 지우, 태민이에요."],"variant_rule":{"alt":[{"stem":"직육면체와 정육면체에 대해 친구들이 말했어요. 연희 「정육면체는 면의 크기가 모두 같아요.」 · 세영 「정육면체는 정사각형으로 둘러싸여 있어요.」 · 민지 「정육면체는 모든 모서리의 길이가 달라요.」 바르게 설명한 친구를 모두 고른 것은 어느 것인가요?","options":[{"t":"연희, 세영","correct":true},{"t":"세영, 민지","mis":"M5-2-u5-X19"},{"t":"연희, 민지","mis":"M5-2-u5-X19"},{"t":"연희, 세영, 민지","mis":"M5-2-u5-X19"}],"explanation":["직육면체는 직사각형 6개, 정육면체는 정사각형 6개로 둘러싸여 있고, 면 6·모서리 12·꼭짓점 8로 수가 같아요.","직육면체의 옆면은 이웃하면 수직이고, 정육면체는 모서리의 길이가 모두 같아요.","바르게 설명한 친구는 연희, 세영이에요."]},{"stem":"직육면체와 정육면체에 대해 친구들이 말했어요. 지우 「직육면체와 정육면체는 면, 모서리, 꼭짓점의 수가 각각 같아요.」 · 윤수 「직육면체와 정육면체의 면은 8개로 같아요.」 · 서연 「정육면체는 모서리의 길이가 모두 달라요.」 · 태민 「직육면체는 한 꼭짓점에서 세 모서리가 만나요.」 바르게 설명한 친구를 모두 고른 것은 어느 것인가요?","options":[{"t":"지우, 태민","correct":true},{"t":"지우, 윤수","mis":"M5-2-u5-X05"},{"t":"서연, 태민","mis":"M5-2-u5-X19"},{"t":"윤수, 서연","mis":"M5-2-u5-X05"}],"explanation":["직육면체는 직사각형 6개, 정육면체는 정사각형 6개로 둘러싸여 있고, 면 6·모서리 12·꼭짓점 8로 수가 같아요.","직육면체의 옆면은 이웃하면 수직이고, 정육면체는 모서리의 길이가 모두 같아요.","바르게 설명한 친구는 지우, 태민이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L03_challenge#5','math',5,2,'u5','L03','tb_g5_2_math_u5_L03_challenge','lesson_challenge','M5-2-u5-C3',3,'sa','auto','정육면체의 모든 모서리의 길이의 합이 96 cm예요. 한 면의 넓이는 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u5-C3","difficulty":3,"kind":"sa","stem":"정육면체의 모든 모서리의 길이의 합이 96 cm예요. 한 면의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["한 모서리의 길이는 96 ÷ 12 = 8(cm)예요.","정육면체의 면은 한 변이 8 cm인 정사각형이에요.","넓이는 8 × 8 = 64(cm²)예요."],"mis":"M5-2-u5-X07","variant_rule":{"alt":[{"stem":"정육면체의 모든 모서리의 길이의 합이 120 cm예요. 한 면의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["100"],"explanation":["한 모서리의 길이는 120 ÷ 12 = 10(cm)예요.","정육면체의 면은 한 변이 10 cm인 정사각형이에요.","넓이는 10 × 10 = 100(cm²)예요."]},{"stem":"정육면체의 모든 모서리의 길이의 합이 60 cm예요. 한 면의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["한 모서리의 길이는 60 ÷ 12 = 5(cm)예요.","정육면체의 면은 한 변이 5 cm인 정사각형이에요.","넓이는 5 × 5 = 25(cm²)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L03_challenge#6','math',5,2,'u5','L03','tb_g5_2_math_u5_L03_challenge','lesson_challenge','M5-2-u5-C3',3,'sa','auto','직육면체의 면의 수와 정육면체의 꼭짓점의 수의 합은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u5-C3","difficulty":3,"kind":"sa","stem":"직육면체의 면의 수와 정육면체의 꼭짓점의 수의 합은 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["직육면체와 정육면체는 면 6개, 모서리 12개, 꼭짓점 8개로 수가 같아요.","6 + 8 = 14예요.","그래서 14개예요."],"mis":"M5-2-u5-X05","variant_rule":{"alt":[{"stem":"정육면체의 모서리의 수와 직육면체의 꼭짓점의 수의 합은 몇 개인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["직육면체와 정육면체는 면 6개, 모서리 12개, 꼭짓점 8개로 수가 같아요.","12 + 8 = 20이에요.","그래서 20개예요."]},{"stem":"정육면체의 면, 모서리, 꼭짓점의 수의 합은 몇 개인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["직육면체와 정육면체는 면 6개, 모서리 12개, 꼭짓점 8개로 수가 같아요.","6 + 12 + 8 = 26이에요.","그래서 26개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L03_challenge#7','math',5,2,'u5','L03','tb_g5_2_math_u5_L03_challenge','lesson_challenge','M5-2-u5-C3',3,'sa','auto','벨기에 브뤼셀의 아토미움은 구 9개가 서로 연결되어 정육면체를 이루는 조각품이에요(지도서 읽기 자료). 정육면체의 꼭짓점에 놓인 구는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u5-C3","difficulty":3,"kind":"sa","stem":"벨기에 브뤼셀의 아토미움은 구 9개가 서로 연결되어 정육면체를 이루는 조각품이에요(지도서 읽기 자료). 정육면체의 꼭짓점에 놓인 구는 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["정육면체는 꼭짓점 8개, 모서리 12개예요.","정육면체의 꼭짓점은 8개니 꼭짓점마다 구가 하나씩 놓이면 8개예요.","그래서 8개예요."],"mis":"M5-2-u5-X04","asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"벨기에 브뤼셀의 아토미움은 구 9개가 서로 연결되어 정육면체를 이루는 조각품이에요(지도서 읽기 자료). 정육면체의 꼭짓점이 아닌 곳(가운데)에 놓인 구는 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["정육면체는 꼭짓점 8개, 모서리 12개예요.","구 9개 가운데 꼭짓점 8개에 놓인 구를 빼면 9 − 8 = 1(개)예요.","그래서 1개예요."],"asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"벨기에 브뤼셀의 아토미움은 구 9개가 서로 연결되어 정육면체를 이루는 조각품이에요(지도서 읽기 자료). 꼭짓점에 놓인 구끼리 정육면체의 모서리를 따라 이은 관는 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["정육면체는 꼭짓점 8개, 모서리 12개예요.","정육면체의 모서리는 12개니 모서리를 따라 이은 관도 12개예요.","그래서 12개예요."],"asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L03_challenge#8','math',5,2,'u5','L03','tb_g5_2_math_u5_L03_challenge','lesson_challenge','M5-2-u5-C3',4,'sa','auto','한 모서리가 3 cm인 정육면체와 교과서 119쪽에 나온 가로 3 cm, 세로 3 cm, 높이 4 cm인 직육면체가 있어요. 두 도형의 모든 모서리의 길이의 합의 차는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u5-C3","difficulty":4,"kind":"sa","stem":"한 모서리가 3 cm인 정육면체와 교과서 119쪽에 나온 가로 3 cm, 세로 3 cm, 높이 4 cm인 직육면체가 있어요. 두 도형의 모든 모서리의 길이의 합의 차는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["정육면체: 3 × 12 = 36이에요.","직육면체: 3 × 4 + 3 × 4 + 4 × 4 = 40이에요.","차는 40 − 36 = 4(cm)예요."],"mis":"M5-2-u5-X07","variant_rule":{"alt":[{"stem":"한 모서리가 5 cm인 정육면체와 문제로 마무리 8번에 나온 가로 5 cm, 세로 3 cm, 높이 4 cm인 직육면체가 있어요. 두 도형의 모든 모서리의 길이의 합의 차는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["정육면체: 5 × 12 = 60이에요.","직육면체: 5 × 4 + 3 × 4 + 4 × 4 = 48이에요.","차는 60 − 48 = 12(cm)예요."]},{"stem":"한 모서리가 8 cm인 정육면체와 수학익힘 77쪽에 나온 가로 8 cm, 세로 6 cm, 높이 5 cm인 직육면체가 있어요. 두 도형의 모든 모서리의 길이의 합의 차는 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["정육면체: 8 × 12 = 96이에요.","직육면체: 8 × 4 + 6 × 4 + 5 × 4 = 76이에요.","차는 96 − 76 = 20(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L03_challenge#9','math',5,2,'u5','L03','tb_g5_2_math_u5_L03_challenge','lesson_challenge','M5-2-u5-C3',4,'sa','auto','한 모서리가 16 cm인 정육면체 모양의 상자를 끈으로 묶었어요. 끈은 상자의 위·아래 면을 가로지르며 열십자로 두 바퀴 둘렀고, 매듭에 쓴 끈은 18 cm예요. 사용한 끈은 모두 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u5-C3","difficulty":4,"kind":"sa","stem":"한 모서리가 16 cm인 정육면체 모양의 상자를 끈으로 묶었어요. 끈은 상자의 위·아래 면을 가로지르며 열십자로 두 바퀴 둘렀고, 매듭에 쓴 끈은 18 cm예요. 사용한 끈은 모두 몇 cm인가요? 숫자로 쓰세요.","answer":["146"],"explanation":["끈이 한 바퀴 돌 때 한 모서리 길이만큼 4번 지나가요.","두 바퀴이니 16 × 8 = 128이고, 매듭 18 cm를 더해요.","128 + 18 = 146(cm)예요."],"mis":"M5-2-u5-X07","asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"한 모서리가 8 cm인 정육면체 모양의 상자를 끈으로 묶었어요. 끈은 상자의 위·아래 면을 가로지르며 열십자로 두 바퀴 둘렀고, 매듭에 쓴 끈은 18 cm예요. 사용한 끈은 모두 몇 cm인가요? 숫자로 쓰세요.","answer":["82"],"explanation":["끈이 한 바퀴 돌 때 한 모서리 길이만큼 4번 지나가요.","두 바퀴이니 8 × 8 = 64이고, 매듭 18 cm를 더해요.","64 + 18 = 82(cm)예요."],"asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"한 모서리가 5 cm인 정육면체 모양의 상자를 끈으로 묶었어요. 끈은 상자의 위·아래 면을 가로지르며 열십자로 두 바퀴 둘렀고, 매듭에 쓴 끈은 18 cm예요. 사용한 끈은 모두 몇 cm인가요? 숫자로 쓰세요.","answer":["58"],"explanation":["끈이 한 바퀴 돌 때 한 모서리 길이만큼 4번 지나가요.","두 바퀴이니 5 × 8 = 40이고, 매듭 18 cm를 더해요.","40 + 18 = 58(cm)예요."],"asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L03_challenge#10','math',5,2,'u5','L03','tb_g5_2_math_u5_L03_challenge','lesson_challenge','M5-2-u5-C3',4,'essay','teacher','「정육면체는 직육면체라고 할 수 있다.」와 「직육면체는 정육면체라고 할 수 있다.」 가운데 맞는 말을 고르고, 두 말이 맞는지 틀린지를 각각 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u5-C3","difficulty":4,"kind":"essay","stem":"「정육면체는 직육면체라고 할 수 있다.」와 「직육면체는 정육면체라고 할 수 있다.」 가운데 맞는 말을 고르고, 두 말이 맞는지 틀린지를 각각 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 「정육면체는 직육면체라고 할 수 있다.」가 맞다. 정사각형은 네 각이 직각이므로 직사각형이고, 정사각형 6개로 둘러싸인 정육면체는 직사각형 6개로 둘러싸인 직육면체이기도 하다. 그러나 직육면체는 모든 모서리의 길이가 같지 않을 수 있으므로 직육면체를 모두 정육면체라고 할 수는 없다.","scoring_points":["정육면체는 직육면체라고 할 수 있다고 썼는가","정사각형은 직사각형이라는 까닭을 썼는가","직육면체는 모서리의 길이가 모두 같지 않을 수 있어 거꾸로는 안 된다고 썼는가"]},"explanation":["정사각형은 직사각형이에요.","그래서 정육면체는 직육면체예요.","직육면체는 모서리의 길이가 모두 같지 않을 수 있어 정육면체라고 할 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L04_basic#1','math',5,2,'u5','L04','tb_g5_2_math_u5_L04_basic','lesson_basic','M5-2-u5-C4',1,'mc','auto','직육면체의 겨냥도에서 보이지 않는 모서리는 어떻게 그리나요?',ARRAY['M5-2-u5-X09','M5-2-u5-X10']::text[],true,'{"seq":1,"concept":"M5-2-u5-C4","difficulty":1,"kind":"mc","stem":"직육면체의 겨냥도에서 보이지 않는 모서리는 어떻게 그리나요?","options":[{"t":"점선으로 그린다","correct":true},{"t":"실선으로 그린다","mis":"M5-2-u5-X09"},{"t":"그리지 않는다","mis":"M5-2-u5-X09"},{"t":"보이는 모서리보다 굵게 그린다","mis":"M5-2-u5-X10"}],"explanation":["겨냥도는 보이는 모서리를 실선으로 그려요.","보이지 않는 모서리는 점선으로 그려요.","정답은 「점선으로 그린다」예요."],"variant_rule":{"alt":[{"stem":"직육면체의 겨냥도에서 보이는 모서리는 어떻게 그리나요?","options":[{"t":"실선으로 그린다","correct":true},{"t":"점선으로 그린다","mis":"M5-2-u5-X09"},{"t":"그리지 않는다","mis":"M5-2-u5-X09"},{"t":"색칠한다","mis":"M5-2-u5-X03"}],"explanation":["겨냥도는 보이는 모서리를 실선으로 그려요.","보이지 않는 모서리는 점선으로 그려요.","정답은 「실선으로 그린다」예요."]},{"stem":"보이는 모서리는 실선, 보이지 않는 모서리는 점선으로 나타낸 그림을 무엇이라고 하나요?","options":[{"t":"직육면체의 겨냥도","correct":true},{"t":"직육면체의 전개도","mis":"M5-2-u5-X16"},{"t":"평면도형","mis":"M5-2-u5-X01"},{"t":"직사각형","mis":"M5-2-u5-X02"}],"explanation":["겨냥도는 보이는 모서리를 실선으로 그려요.","보이지 않는 모서리는 점선으로 그려요.","정답은 「직육면체의 겨냥도」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L04_basic#2','math',5,2,'u5','L04','tb_g5_2_math_u5_L04_basic','lesson_basic','M5-2-u5-C4',1,'sa','auto','직육면체 모양 캠핑 상자의 겨냥도예요. 실선으로 그린 모서리는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u5-C4","difficulty":1,"kind":"sa","stem":"직육면체 모양 캠핑 상자의 겨냥도예요. 실선으로 그린 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["겨냥도에서 보이는 모서리는 실선, 보이지 않는 모서리는 점선이에요.","보이는 모서리 9개를 실선으로 그려요.","그래서 9개예요."],"mis":"M5-2-u5-X10","asset":{"type":"geo","items":[{"w":143.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[110,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[143.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[110,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체 모양 서랍의 겨냥도예요. 점선으로 그린 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["겨냥도에서 보이는 모서리는 실선, 보이지 않는 모서리는 점선이에요.","보이지 않는 모서리 3개를 점선으로 그려요.","그래서 3개예요."],"asset":{"type":"geo","items":[{"w":121.0,"h":77.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[121.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[88,33.0,"sw"],"ㅁ":[33.0,44,"ne"],"ㅇ":[121.0,44,"e"],"ㅂ":[0,77.0,"sw"],"ㅅ":[88,77.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체 모양 선물 상자의 겨냥도예요. 보이는 면은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["겨냥도에서 보이는 모서리는 실선, 보이지 않는 모서리는 점선이에요.","앞, 위, 옆의 면 3개가 보여요.","그래서 3개예요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],