INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L04_basic#3','math',5,2,'u5','L04','tb_g5_2_math_u5_L04_basic','lesson_basic','M5-2-u5-C4',1,'sa','auto','직육면체 모양 도시락통의 겨냥도예요. 보이지 않는 꼭짓점은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u5-C4","difficulty":1,"kind":"sa","stem":"직육면체 모양 도시락통의 겨냥도예요. 보이지 않는 꼭짓점은 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["겨냥도에서 보이는 모서리는 실선, 보이지 않는 모서리는 점선이에요.","뒤쪽 아래 꼭짓점 1개만 보이지 않아요.","그래서 1개예요."],"mis":"M5-2-u5-X10","asset":{"type":"geo","items":[{"w":88.0,"h":66.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[88.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[66,22.0,"sw"],"ㅁ":[22.0,44,"ne"],"ㅇ":[88.0,44,"e"],"ㅂ":[0,66.0,"sw"],"ㅅ":[66,66.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체 모양 과일 상자의 겨냥도예요. 보이는 꼭짓점은 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["겨냥도에서 보이는 모서리는 실선, 보이지 않는 모서리는 점선이에요.","꼭짓점 8개 가운데 7개가 보여요.","그래서 7개예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[110,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[132.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[110,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체 모양 사물함의 겨냥도예요. 보이지 않는 면은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["겨냥도에서 보이는 모서리는 실선, 보이지 않는 모서리는 점선이에요.","뒤, 아래, 다른 옆의 면 3개는 보이지 않아요.","그래서 3개예요."],"asset":{"type":"geo","items":[{"w":99.0,"h":121.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,88,"ne"],"ㅇ":[99.0,88,"e"],"ㅂ":[0,121.0,"sw"],"ㅅ":[66,121.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ