INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L04_basic#8','math',5,2,'u5','L04','tb_g5_2_math_u5_L04_basic','lesson_basic','M5-2-u5-C4',2,'ox','auto','직육면체의 겨냥도에서 실선은 9개, 점선은 3개예요.',ARRAY['M5-2-u5-X10']::text[],true,'{"seq":8,"concept":"M5-2-u5-C4","difficulty":2,"kind":"ox","stem":"직육면체의 겨냥도에서 실선은 9개, 점선은 3개예요.","answer":"O","reason_options":[{"t":"보이는 모서리 9개, 보이지 않는 모서리 3개이므로","correct":true},{"t":"보이는 모서리와 보이지 않는 모서리가 6개씩이므로","mis":"M5-2-u5-X10"}],"mis":"M5-2-u5-X10","explanation":["겨냥도는 보이는 모서리 실선 9개, 보이지 않는 모서리 점선 3개예요.","맞는 말이면 O, 틀린 말이면 X — 정답은 O예요.","까닭으로 「보이는 모서리 9개, 보이지 않는 모서리 3개이므로」를 골라요."],"asset":{"type":"geo","items":[{"w":110.0,"h":66.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,44,"ne"],"ㅇ":[110.0,44,"e"],"ㅂ":[0,66.0,"sw"],"ㅅ":[88,66.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"겨냥도에서 보이지 않는 모서리는 그리지 않아도 돼요.","answer":"X","reason_options":[{"t":"보이지 않는 모서리도 점선으로 그려야 모서리 12개가 드러나므로","correct":true},{"t":"보이지 않는 것은 그릴 필요가 없으므로","mis":"M5-2-u5-X09"}],"explanation":["겨냥도는 보이는 모서리 실선 9개, 보이지 않는 모서리 점선 3개예요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「보이지 않는 모서리도 점선으로 그려야 모서리 12개가 드러나므로」를 골라요."],"asset":{"type":"geo","items":[{"w":110.0,"h":66.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,44,"ne"],"ㅇ":[110.0,44,"e"],"ㅂ":[0,66.0,"sw"],"ㅅ":[88,66.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체의 겨냥도에서 보이지 않는 꼭짓점은 1개예요.","answer":"O","reason_options":[{"t":"뒤쪽 아래 꼭짓점 하나만 가려지므로","correct":true},{"t":"보이지 않는 꼭짓점은 3개이므로","mis"