INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L04_basic#9','math',5,2,'u5','L04','tb_g5_2_math_u5_L04_basic','lesson_basic','M5-2-u5-C4',2,'mc','auto','직육면체 모양의 상자를 보고 겨냥도를 그리고 있어요(교과서 111쪽). 실선 9개는 다 그렸어요. 빠진 부분을 어떻게 그려야 하나요?',ARRAY['M5-2-u5-X09','M5-2-u5-X10']::text[],true,'{"seq":9,"concept":"M5-2-u5-C4","difficulty":2,"kind":"mc","stem":"직육면체 모양의 상자를 보고 겨냥도를 그리고 있어요(교과서 111쪽). 실선 9개는 다 그렸어요. 빠진 부분을 어떻게 그려야 하나요?","options":[{"t":"보이지 않는 모서리 3개를 점선으로 그린다","correct":true},{"t":"보이지 않는 모서리 3개를 실선으로 그린다","mis":"M5-2-u5-X09"},{"t":"보이는 모서리 3개를 더 실선으로 그린다","mis":"M5-2-u5-X10"},{"t":"더 그릴 것이 없다","mis":"M5-2-u5-X09"}],"explanation":["겨냥도는 보이는 모서리 9개를 실선으로, 보이지 않는 모서리 3개를 점선으로 그려요.","보이지 않는 모서리 3개는 보이지 않는 꼭짓점 하나에서 만나요.","정답은 「보이지 않는 모서리 3개를 점선으로 그린다」예요."],"asset":{"type":"geo","items":[{"w":154.0,"h":110.0,"pts":{"ㄱ":[44.0,0,"nw"],"ㄹ":[154.0,0,"ne"],"ㄴ":[0,44.0,"w"],"ㄷ":[110,44.0,"sw"],"ㅁ":[44.0,66,"ne"],"ㅇ":[154.0,66,"e"],"ㅂ":[0,110.0,"sw"],"ㅅ":[110,110.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"정육면체의 겨냥도를 그리고 있어요(단원 평가). 보이는 모서리만 그렸어요. 겨냥도를 완성하려면 무엇을 더 그려야 하나요?","options":[{"t":"보이지 않는 모서리 3개를 점선으로","correct":true},{"t":"보이지 않는 모서리 3개를 실선으로","mis":"M5-2-u5-X09"},{"t":"보이지 않는 모서리 1개를 점선으로","mis":"M5-2-u5-X10"},{"t":"보이는 모서리 9개를 점선으로","mis":"M5-2-u5-X16"}],"explanation":["겨냥도는 보이는 모서리 9개를 실선으로, 보이지 않는 모서리 3개를 점선으로 그려요.","보이지 않는 모서리 3개는 보이지 않는 꼭짓점 하나에서 만나요.","정답은 「보이지 않는 모서리 3개를 점선으로」예요."],"asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]]}],"tag":false}},{"stem":"형성 평가의 겨냥도예요. 보이는 모서리는 실선으로 다 그렸어요. 빠진 부분을 그리면 겨냥도의 선은 모두 몇 개가 되나요?","options":[{"t":"실선 9개와 점선 3개, 모두 12개","correct":true},{"t":"실선 9개와 점선 1개, 모두 10개","mis":"M5-2-u5-X10"},{"t":"실선 12개","mis":"M5-2-u5-X09"},{"t":"실선 9개, 모두 9개","mis":"M5-2-u5-X09"}],"explanation":["겨냥도는 보이는 모서리 9개를 실선으로, 보이지 않는 모서리 3개를 점선으로 그려요.","보이지 않는 모서리 3개는 보이지 않는 꼭짓점 하나에서 만나요.","정답은 「실선 9개와 점선 3개, 모두 12개」예요."],"asset":{"type":"geo","items":[{"w":154.0,"h":110.0,"pts":{"ㄱ":[44.0,0,"nw"],"ㄹ":[154.0,0,"ne"],"ㄴ":[0,44.0,"w"],"ㄷ":[110,44.0,"sw"],"ㅁ":[44.0,66,"ne"],"ㅇ":[154.0,66,"e"],"ㅂ":[0,110.0,"sw"],"ㅅ":[110,110.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L04_basic#10','math',5,2,'u5','L04','tb_g5_2_math_u5_L04_basic','lesson_basic','M5-2-u5-C4',3,'mc','auto','겨냥도에서 보이지 않는 모서리를 점선으로 그리는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u5-X09','M5-2-u5-X10']::text[],true,'{"seq":10,"concept":"M5-2-u5-C4","difficulty":3,"kind":"mc","stem":"겨냥도에서 보이지 않는 모서리를 점선으로 그리는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"그림만 보고도 다른 사람이 입체의 모양을 알아맞힐 수 있게 하려고","correct":true},{"t":"그리기가 쉬워서","mis":"M5-2-u5-X09"},{"t":"선의 수를 줄이려고","mis":"M5-2-u5-X10"},{"t":"보이지 않는 면을 지우려고","mis":"M5-2-u5-X09"}],"explanation":["겨냥도는 내가 아는 것을 적는 그림이 아니라 남이 알아볼 수 있는 그림이에요.","숨은 모서리는 점선으로 드러내야 앞뒤도 알고 모서리 12개도 다 보여요.","정답은 「그림만 보고도 다른 사람이 입체의 모양을 알아맞힐 수 있게 하려고」예요."],"variant_rule":{"alt":[{"stem":"보이지 않는 모서리를 실선으로 그리면 어떤 점이 불편한가요?","options":[{"t":"어느 쪽이 앞이고 어느 쪽이 뒤인지 알 수 없다","correct":true},{"t":"모서리가 12개보다 많아진다","mis":"M5-2-u5-X10"},{"t":"면이 7개가 된다","mis":"M5-2-u5-X10"},{"t":"불편한 점이 없다","mis":"M5-2-u5-X09"}],"explanation":["겨냥도는 내가 아는 것을 적는 그림이 아니라 남이 알아볼 수 있는 그림이에요.","숨은 모서리는 점선으로 드러내야 앞뒤도 알고 모서리 12개도 다 보여요.","정답은 「어느 쪽이 앞이고 어느 쪽이 뒤인지 알 수 없다」예요."]},{"stem":"보이지 않는 모서리를 아예 그리지 않으면 어떤 점이 잘못되나요?","options":[{"t":"모서리가 12개가 되지 않아 직육면체를 다 나타내지 못한다","correct":true},{"t":"앞뒤가 바뀐다","mis":"M5-2-u5-X09"},{"t":"면이 정사각형이 된다","mis":"M5-2-u5-X02"},{"t":"잘못된 점이 없다","mis":"M5-2-u5-X09"}],"explanation":["겨냥도는 내가 아는 것을 적는 그림이 아니라 남이 알아볼 수 있는 그림이에요.","숨은 모서리는 점선으로 드러내야 앞뒤도 알고 모서리 12개도 다 보여요.","정답은 「모서리가 12개가 되지 않아 직육면체를 다 나타내지 못한다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L04_challenge#1','math',5,2,'u5','L04','tb_g5_2_math_u5_L04_challenge','lesson_challenge','M5-2-u5-C4',2,'sa','auto','직육면체 모양 캠핑 상자의 겨냥도예요. 보이지 않는 모서리는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u5-C4","difficulty":2,"kind":"sa","stem":"직육면체 모양 캠핑 상자의 겨냥도예요. 보이지 않는 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["겨냥도에서 보이는 모서리는 실선, 보이지 않는 모서리는 점선이에요.","점선으로 그린 모서리가 보이지 않는 모서리예요.","그래서 3개예요."],"mis":"M5-2-u5-X10","asset":{"type":"geo","items":[{"w":143.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[110,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[143.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[110,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체 모양 선물 상자의 겨냥도예요. 보이는 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["겨냥도에서 보이는 모서리는 실선, 보이지 않는 모서리는 점선이에요.","실선으로 그린 모서리가 보이는 모서리예요.","그래서 9개예요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체 모양 서랍의 겨냥도예요. 보이지 않는 면은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["겨냥도에서 보이는 모서리는 실선, 보이지 않는 모서리는 점선이에요.","뒤, 아래, 다른 옆의 면 3개는 보이지 않아요.","그래서 3개예요."],"asset":{"type":"geo","items":[{"w":121.0,"h":77.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[121.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[88,33.0,"sw"],"ㅁ":[33.0,44,"ne"],"ㅇ":[121.0,44,"e"],"ㅂ":[0,77.0,"sw"],"ㅅ":[88,77.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L04_challenge#2','math',5,2,'u5','L04','tb_g5_2_math_u5_L04_challenge','lesson_challenge','M5-2-u5-C4',2,'ox','auto','겨냥도에서 보이지 않는 모서리는 그리지 않아도 돼요.',ARRAY['M5-2-u5-X09']::text[],true,'{"seq":2,"concept":"M5-2-u5-C4","difficulty":2,"kind":"ox","stem":"겨냥도에서 보이지 않는 모서리는 그리지 않아도 돼요.","answer":"X","reason_options":[{"t":"보이지 않는 모서리도 점선으로 그려야 모서리 12개가 드러나므로","correct":true},{"t":"보이지 않는 것은 그릴 필요가 없으므로","mis":"M5-2-u5-X09"}],"mis":"M5-2-u5-X09","explanation":["겨냥도는 보이는 모서리 실선 9개, 보이지 않는 모서리 점선 3개예요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「보이지 않는 모서리도 점선으로 그려야 모서리 12개가 드러나므로」를 골라요."],"asset":{"type":"geo","items":[{"w":110.0,"h":66.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,44,"ne"],"ㅇ":[110.0,44,"e"],"ㅂ":[0,66.0,"sw"],"ㅅ":[88,66.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체의 겨냥도에서 보이지 않는 꼭짓점은 1개예요.","answer":"O","reason_options":[{"t":"뒤쪽 아래 꼭짓점 하나만 가려지므로","correct":true},{"t":"보이지 않는 꼭짓점은 3개이므로","mis":"M5-2-u5-X10"}],"explanation":["겨냥도는 보이는 모서리 실선 9개, 보이지 않는 모서리 점선 3개예요.","맞는 말이면 O, 틀린 말이면 X — 정답은 O예요.","까닭으로 「뒤쪽 아래 꼭짓점 하나만 가려지므로」를 골라요."],"asset":{"type":"geo","items":[{"w":110.0,"h":66.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,44,"ne"],"ㅇ":[110.0,44,"e"],"ㅂ":[0,66.0,"sw"],"ㅅ":[88,66.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체의 겨냥도에서 보이는 면은 4개예요.","answer":"X","reason_options":[{"t":"보이는 면은 앞, 위, 옆의 3개이므로","correct":true},{"t":"직사각형 모양이 4개 보이므로","mis":"M5-2-u5-X10"}],"explanation":["겨냥도는 보이는 모서리 실선 9개, 보이지 않는 모서리 점선 3개예요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「보이는 면은 앞, 위, 옆의 3개이므로」를 골라요."],"asset":{"type":"geo","items":[{"w":110.0,"h":66.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,44,"ne"],"ㅇ":[110.0,44,"e"],"ㅂ":[0,66.0,"sw"],"ㅅ":[88,66.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L04_challenge#3','math',5,2,'u5','L04','tb_g5_2_math_u5_L04_challenge','lesson_challenge','M5-2-u5-C4',3,'sa','auto','단원 평가에 나온 가로 4 cm, 세로 8 cm, 높이 6 cm인 직육면체의 겨냥도예요. 보이지 않는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u5-C4","difficulty":3,"kind":"sa","stem":"단원 평가에 나온 가로 4 cm, 세로 8 cm, 높이 6 cm인 직육면체의 겨냥도예요. 보이지 않는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["보이지 않는 모서리 3개는 가로, 세로, 높이 하나씩이에요.","4 + 8 + 6 = 18이에요.","그래서 18 cm예요."],"mis":"M5-2-u5-X10","asset":{"type":"geo","items":[{"w":144.0,"h":180.0,"pts":{"ㄱ":[72.0,0,"nw"],"ㄹ":[144.0,0,"ne"],"ㄴ":[0,72.0,"w"],"ㄷ":[72,72.0,"sw"],"ㅁ":[72.0,108,"ne"],"ㅇ":[144.0,108,"e"],"ㅂ":[0,180.0,"sw"],"ㅅ":[72,180.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[36.0,188.0],"4 cm"],[[124.0,148.0],"8 cm"],[[54,126.0],"6 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"교과서 118쪽에 나온 가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체의 겨냥도예요. 보이지 않는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["보이지 않는 모서리 3개는 가로, 세로, 높이 하나씩이에요.","3 + 2 + 5 = 10이에요.","그래서 10 cm예요."],"asset":{"type":"geo","items":[{"w":88.0,"h":132.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[88.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[66,22.0,"sw"],"ㅁ":[22.0,110,"ne"],"ㅇ":[88.0,110,"e"],"ㅂ":[0,132.0,"sw"],"ㅅ":[66,132.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33.0,140.0],"3 cm"],[[93.0,125.0],"2 cm"],[[48,77.0],"5 cm"]]}],"tag":false}},{"stem":"문제로 마무리 8번에 나온 가로 5 cm, 세로 3 cm, 높이 4 cm인 직육면체의 겨냥도예요. 보이지 않는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["보이지 않는 모서리 3개는 가로, 세로, 높이 하나씩이에요.","5 + 3 + 4 = 12예요.","그래서 12 cm예요."],"asset":{"type":"geo","items":[{"w":143.0,"h":121.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[110,33.0,"sw"],"ㅁ":[33.0,88,"ne"],"ㅇ":[143.0,88,"e"],"ㅂ":[0,121.0,"sw"],"ㅅ":[110,121.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[55.0,129.0],"5 cm"],[[142.5,108.5],"3 cm"],[[92,77.0],"4 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L04_challenge#4','math',5,2,'u5','L04','tb_g5_2_math_u5_L04_challenge','lesson_challenge','M5-2-u5-C4',3,'mc','auto','문제로 마무리 4번의 겨냥도예요. 잘못된 부분을 모두 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u5-X09','M5-2-u5-X10']::text[],true,'{"seq":4,"concept":"M5-2-u5-C4","difficulty":3,"kind":"mc","stem":"문제로 마무리 4번의 겨냥도예요. 잘못된 부분을 모두 바르게 말한 것은 어느 것인가요?","options":[{"t":"보이지 않는 모서리 하나를 실선으로, 보이는 모서리 하나를 점선으로 그렸다","correct":true},{"t":"보이지 않는 모서리 하나를 실선으로 그렸다","mis":"M5-2-u5-X09"},{"t":"보이는 모서리 하나를 점선으로 그렸다","mis":"M5-2-u5-X10"},{"t":"잘못된 곳이 없다","mis":"M5-2-u5-X09"}],"explanation":["겨냥도는 보이는 모서리를 실선, 보이지 않는 모서리를 점선으로 그려요.","그림에서 실선과 점선이 바뀐 곳을 하나씩 찾아봐요.","정답은 「보이지 않는 모서리 하나를 실선으로, 보이는 모서리 하나를 점선으로 그렸다」예요."],"asset":{"type":"geo","items":[{"w":154.0,"h":110.0,"pts":{"ㄱ":[44.0,0,"nw"],"ㄹ":[154.0,0,"ne"],"ㄴ":[0,44.0,"w"],"ㄷ":[110,44.0,"sw"],"ㅁ":[44.0,66,"ne"],"ㅇ":[154.0,66,"e"],"ㅂ":[0,110.0,"sw"],"ㅅ":[110,110.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅅ","ㅇ"],["ㅁ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅂ","ㅅ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체의 겨냥도를 잘못 그린 것이에요(단원 평가). 잘못 그린 까닭은 어느 것인가요?","options":[{"t":"보이지 않는 모서리 1개를 실선으로 그렸다","correct":true},{"t":"보이지 않는 모서리 3개를 모두 실선으로 그렸다","mis":"M5-2-u5-X10"},{"t":"보이는 모서리 1개를 점선으로 그렸다","mis":"M5-2-u5-X10"},{"t":"보이지 않는 모서리를 그리지 않았다","mis":"M5-2-u5-X09"}],"explanation":["겨냥도는 보이는 모서리를 실선, 보이지 않는 모서리를 점선으로 그려요.","그림에서 실선과 점선이 바뀐 곳을 하나씩 찾아봐요.","정답은 「보이지 않는 모서리 1개를 실선으로 그렸다」예요."],"asset":{"type":"geo","items":[{"w":154.0,"h":110.0,"pts":{"ㄱ":[44.0,0,"nw"],"ㄹ":[154.0,0,"ne"],"ㄴ":[0,44.0,"w"],"ㄷ":[110,44.0,"sw"],"ㅁ":[44.0,66,"ne"],"ㅇ":[154.0,66,"e"],"ㅂ":[0,110.0,"sw"],"ㅅ":[110,110.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"],["ㄱ","ㅁ"]],"dash":[["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"수학익힘 75쪽의 겨냥도예요. 잘못된 까닭은 어느 것인가요?","options":[{"t":"보이지 않는 모서리를 실선으로 그렸다","correct":true},{"t":"보이지 않는 모서리를 그리지 않았다","mis":"M5-2-u5-X09"},{"t":"보이는 모서리를 점선으로 그렸다","mis":"M5-2-u5-X10"},{"t":"모서리를 13개 그렸다","mis":"M5-2-u5-X10"}],"explanation":["겨냥도는 보이는 모서리를 실선, 보이지 않는 모서리를 점선으로 그려요.","그림에서 실선과 점선이 바뀐 곳을 하나씩 찾아봐요.","정답은 「보이지 않는 모서리를 실선으로 그렸다」예요."],"asset":{"type":"geo","items":[{"w":154.0,"h":110.0,"pts":{"ㄱ":[44.0,0,"nw"],"ㄹ":[154.0,0,"ne"],"ㄴ":[0,44.0,"w"],"ㄷ":[110,44.0,"sw"],"ㅁ":[44.0,66,"ne"],"ㅇ":[154.0,66,"e"],"ㅂ":[0,110.0,"sw"],"ㅅ":[110,110.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"],["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L04_challenge#5','math',5,2,'u5','L04','tb_g5_2_math_u5_L04_challenge','lesson_challenge','M5-2-u5-C4',3,'mc','auto','건축 설계사가 꿈인 친구가 짓고 싶은 건물 모양을 나타내려고 세 면이 모두 보이게 상자를 그렸어요. 이 그림에서 아직 나타나지 않은 것은 어느 것인가요?',ARRAY['M5-2-u5-X18','M5-2-u5-X10','M5-2-u5-X04']::text[],true,'{"seq":5,"concept":"M5-2-u5-C4","difficulty":3,"kind":"mc","stem":"건축 설계사가 꿈인 친구가 짓고 싶은 건물 모양을 나타내려고 세 면이 모두 보이게 상자를 그렸어요. 이 그림에서 아직 나타나지 않은 것은 어느 것인가요?","options":[{"t":"보이지 않는 면 3개, 모서리 3개, 꼭짓점 1개","correct":true},{"t":"보이는 면 3개, 모서리 9개, 꼭짓점 7개","mis":"M5-2-u5-X18"},{"t":"보이지 않는 면 1개, 모서리 1개, 꼭짓점 3개","mis":"M5-2-u5-X10"},{"t":"없다 — 다 보인다","mis":"M5-2-u5-X04"}],"explanation":["한쪽에서 보면 면 3개, 모서리 9개, 꼭짓점 7개만 보여요.","보이지 않는 모서리를 점선으로 더 그린 그림이 겨냥도예요.","정답은 「보이지 않는 면 3개, 모서리 3개, 꼭짓점 1개」예요."],"asset":{"type":"geo","items":[{"w":121.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[121.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[88,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[121.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[88,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"세 면이 모두 보이게 그린 상자 그림에 보이지 않는 모서리를 점선으로 더 그렸어요. 이렇게 그린 그림을 무엇이라고 하나요?","options":[{"t":"직육면체의 겨냥도","correct":true},{"t":"직육면체의 전개도","mis":"M5-2-u5-X16"},{"t":"평면도형","mis":"M5-2-u5-X01"},{"t":"정사각형","mis":"M5-2-u5-X02"}],"explanation":["한쪽에서 보면 면 3개, 모서리 9개, 꼭짓점 7개만 보여요.","보이지 않는 모서리를 점선으로 더 그린 그림이 겨냥도예요.","정답은 「직육면체의 겨냥도」예요."],"asset":{"type":"geo","items":[{"w":121.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[121.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[88,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[121.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[88,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]]}],"tag":false}},{"stem":"건축 설계사가 그림만 보고도 다른 사람이 건물 모양을 알 수 있게 하려면 보이지 않는 모서리를 어떻게 그려야 하나요?","options":[{"t":"점선으로 그린다","correct":true},{"t":"실선으로 그린다","mis":"M5-2-u5-X09"},{"t":"그리지 않는다","mis":"M5-2-u5-X09"},{"t":"보이는 모서리보다 굵게 그린다","mis":"M5-2-u5-X10"}],"explanation":["한쪽에서 보면 면 3개, 모서리 9개, 꼭짓점 7개만 보여요.","보이지 않는 모서리를 점선으로 더 그린 그림이 겨냥도예요.","정답은 「점선으로 그린다」예요."],"asset":{"type":"geo","items":[{"w":121.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[121.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[88,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[121.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[88,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L04_challenge#6','math',5,2,'u5','L04','tb_g5_2_math_u5_L04_challenge','lesson_challenge','M5-2-u5-C4',3,'sa','auto','정육면체의 모든 모서리의 길이의 합이 120 cm예요. 이 정육면체의 겨냥도에서 보이지 않는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u5-C4","difficulty":3,"kind":"sa","stem":"정육면체의 모든 모서리의 길이의 합이 120 cm예요. 이 정육면체의 겨냥도에서 보이지 않는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["한 모서리는 120 ÷ 12 = 10(cm)예요.","보이지 않는 모서리는 3개예요.","10 × 3 = 30(cm)예요."],"mis":"M5-2-u5-X10","variant_rule":{"alt":[{"stem":"정육면체의 모든 모서리의 길이의 합이 96 cm예요. 이 정육면체의 겨냥도에서 보이지 않는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["한 모서리는 96 ÷ 12 = 8(cm)예요.","보이지 않는 모서리는 3개예요.","8 × 3 = 24(cm)예요."]},{"stem":"정육면체의 모든 모서리의 길이의 합이 60 cm예요. 이 정육면체의 겨냥도에서 보이지 않는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["한 모서리는 60 ÷ 12 = 5(cm)예요.","보이지 않는 모서리는 3개예요.","5 × 3 = 15(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L04_challenge#7','math',5,2,'u5','L04','tb_g5_2_math_u5_L04_challenge','lesson_challenge','M5-2-u5-C4',3,'sa','auto','직육면체의 겨냥도에서 보이는 모서리와 보이지 않는 꼭짓점의 수의 차는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u5-C4","difficulty":3,"kind":"sa","stem":"직육면체의 겨냥도에서 보이는 모서리와 보이지 않는 꼭짓점의 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["보이는 것은 면 3, 모서리 9, 꼭짓점 7 — 보이지 않는 것은 면 3, 모서리 3, 꼭짓점 1이에요.","9 − 1 = 8이에요.","그래서 8개예요."],"mis":"M5-2-u5-X10","asset":{"type":"geo","items":[{"w":121.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[121.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[88,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[121.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[88,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체의 겨냥도에서 보이는 꼭짓점과 보이지 않는 모서리의 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["보이는 것은 면 3, 모서리 9, 꼭짓점 7 — 보이지 않는 것은 면 3, 모서리 3, 꼭짓점 1이에요.","7 − 3 = 4예요.","그래서 4개예요."],"asset":{"type":"geo","items":[{"w":121.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[121.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[88,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[121.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[88,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체의 겨냥도에서 실선으로 그린 모서리와 보이는 면의 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["보이는 것은 면 3, 모서리 9, 꼭짓점 7 — 보이지 않는 것은 면 3, 모서리 3, 꼭짓점 1이에요.","9 − 3 = 6이에요.","그래서 6개예요."],"asset":{"type":"geo","items":[{"w":121.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[121.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[88,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[121.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[88,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L04_challenge#8','math',5,2,'u5','L04','tb_g5_2_math_u5_L04_challenge','lesson_challenge','M5-2-u5-C4',4,'sa','auto','단원 평가에 나온 가로 6 cm, 세로 9 cm, 높이 5 cm인 직육면체의 겨냥도예요. 보이는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u5-C4","difficulty":4,"kind":"sa","stem":"단원 평가에 나온 가로 6 cm, 세로 9 cm, 높이 5 cm인 직육면체의 겨냥도예요. 보이는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["보이는 모서리 9개는 가로, 세로, 높이가 3개씩이에요.","6 × 3 + 9 × 3 + 5 × 3 = 60이에요.","그래서 60 cm예요."],"mis":"M5-2-u5-X10","asset":{"type":"geo","items":[{"w":147.0,"h":133.0,"pts":{"ㄱ":[63.0,0,"nw"],"ㄹ":[147.0,0,"ne"],"ㄴ":[0,63.0,"w"],"ㄷ":[84,63.0,"sw"],"ㅁ":[63.0,70,"ne"],"ㅇ":[147.0,70,"e"],"ㅂ":[0,133.0,"sw"],"ㅅ":[84,133.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[42.0,141.0],"6 cm"],[[131.5,105.5],"9 cm"],[[66,98.0],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가에 나온 가로 4 cm, 세로 8 cm, 높이 6 cm인 직육면체의 겨냥도예요. 보이는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["54"],"explanation":["보이는 모서리 9개는 가로, 세로, 높이가 3개씩이에요.","4 × 3 + 8 × 3 + 6 × 3 = 54예요.","그래서 54 cm예요."],"asset":{"type":"geo","items":[{"w":144.0,"h":180.0,"pts":{"ㄱ":[72.0,0,"nw"],"ㄹ":[144.0,0,"ne"],"ㄴ":[0,72.0,"w"],"ㄷ":[72,72.0,"sw"],"ㅁ":[72.0,108,"ne"],"ㅇ":[144.0,108,"e"],"ㅂ":[0,180.0,"sw"],"ㅅ":[72,180.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[36.0,188.0],"4 cm"],[[124.0,148.0],"8 cm"],[[54,126.0],"6 cm"]]}],"tag":false}},{"stem":"교과서 118쪽에 나온 가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체의 겨냥도예요. 보이는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["보이는 모서리 9개는 가로, 세로, 높이가 3개씩이에요.",