INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L04_challenge#10','math',5,2,'u5','L04','tb_g5_2_math_u5_L04_challenge','lesson_challenge','M5-2-u5-C4',4,'essay','teacher','단원 평가의 그림이에요. 이 직육면체의 겨냥도를 잘못 그린 이유를 쓰고, 어떻게 고쳐야 하는지와 겨냥도를 그렇게 그리는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u5-C4","difficulty":4,"kind":"essay","stem":"단원 평가의 그림이에요. 이 직육면체의 겨냥도를 잘못 그린 이유를 쓰고, 어떻게 고쳐야 하는지와 겨냥도를 그렇게 그리는 까닭을 쓰세요.","answer_guide":{"answer":"예: 보이지 않는 모서리는 점선으로 그려야 하는데 보이지 않는 모서리 1개를 실선으로 그렸다. 그 모서리를 점선으로 고쳐 그려야 한다. 겨냥도는 그림만 보고도 다른 사람이 입체의 모양을 알아맞힐 수 있게 그리는 그림이기 때문이다.","scoring_points":["보이지 않는 모서리 1개를 실선으로 그렸다고 썼는가","그 모서리를 점선으로 고친다고 썼는가","다른 사람이 입체를 알아볼 수 있게 하려는 까닭을 썼는가"]},"explanation":["보이는 모서리 9개는 실선이에요.","보이지 않는 모서리 3개는 점선이어야 하는데 1개가 실선이에요.","그래야 그림만 보고도 앞뒤를 알 수 있어요."],"asset":{"type":"geo","items":[{"w":154.0,"h":110.0,"pts":{"ㄱ":[44.0,0,"nw"],"ㄹ":[154.0,0,"ne"],"ㄴ":[0,44.0,"w"],"ㄷ":[110,44.0,"sw"],"ㅁ":[44.0,66,"ne"],"ㅇ":[154.0,66,"e"],"ㅂ":[0,110.0,"sw"],"ㅅ":[110,110.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"],["ㄱ","ㅁ"]],"dash":[["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L05_basic#1','math',5,2,'u5','L05','tb_g5_2_math_u5_L05_basic','lesson_basic','M5-2-u5-C5',1,'sa','auto','직육면체에서 서로 평행한 면은 모두 몇 쌍인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u5-C5","difficulty":1,"kind":"sa","stem":"직육면체에서 서로 평행한 면은 모두 몇 쌍인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["계속 늘여도 만나지 않는 두 면은 평행, 만나는 두 면은 수직이에요.","앞·뒤, 위·아래, 왼쪽·오른쪽 — 평행한 면이 3쌍이에요.","그래서 3이에요."],"mis":"M5-2-u5-X13","asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체에서 한 밑면과 수직인 면은 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["계속 늘여도 만나지 않는 두 면은 평행, 만나는 두 면은 수직이에요.","밑면과 평행한 다른 밑면을 뺀 나머지 6 − 2 = 4(개)가 수직이에요.","그래서 4예요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체에서 한 면과 평행한 면은 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["계속 늘여도 만나지 않는 두 면은 평행, 만나는 두 면은 수직이에요.","마주 보는 면 하나만 평행해요.","그래서 1이에요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ