INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L05_basic#8','math',5,2,'u5','L05','tb_g5_2_math_u5_L05_basic','lesson_basic','M5-2-u5-C5',2,'ox','auto','직육면체에서 옆면끼리는 모두 평행해요.',ARRAY['M5-2-u5-X12']::text[],true,'{"seq":8,"concept":"M5-2-u5-C5","difficulty":2,"kind":"ox","stem":"직육면체에서 옆면끼리는 모두 평행해요.","answer":"X","reason_options":[{"t":"이웃한 옆면끼리는 수직으로 만나므로","correct":true},{"t":"옆면은 모두 같은 쪽에 있으므로","mis":"M5-2-u5-X12"}],"mis":"M5-2-u5-X12","explanation":["만나는 두 면은 수직, 만나지 않는 두 면은 평행해요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「이웃한 옆면끼리는 수직으로 만나므로」를 골라요."],"variant_rule":{"alt":[{"stem":"직육면체에서 평행한 면은 3쌍이에요.","answer":"O","reason_options":[{"t":"마주 보는 면이 앞·뒤, 위·아래, 왼쪽·오른쪽 3쌍이므로","correct":true},{"t":"평행한 면은 6쌍이므로","mis":"M5-2-u5-X13"}],"explanation":["만나는 두 면은 수직, 만나지 않는 두 면은 평행해요.","맞는 말이면 O, 틀린 말이면 X — 정답은 O예요.","까닭으로 「마주 보는 면이 앞·뒤, 위·아래, 왼쪽·오른쪽 3쌍이므로」를 골라요."]},{"stem":"바닥에 닿은 면만 밑면이 될 수 있어요.","answer":"X","reason_options":[{"t":"밑면은 위치가 아니라 평행한 관계로 정하므로","correct":true},{"t":"밑면은 밑에 있어야 하므로","mis":"M5-2-u5-X11"}],"explanation":["만나는 두 면은 수직, 만나지 않는 두 면은 평행해요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「밑면은 위치가 아니라 평행한 관계로 정하므로」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
