INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L05_challenge#4','math',5,2,'u5','L05','tb_g5_2_math_u5_L05_challenge','lesson_challenge','M5-2-u5-C5',3,'sa','auto','교과서 118쪽에 나온 가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체예요. 면 ㄴㅂㅅㄷ이 밑면일 때 다른 밑면의 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u5-C5","difficulty":3,"kind":"sa","stem":"교과서 118쪽에 나온 가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체예요. 면 ㄴㅂㅅㄷ이 밑면일 때 다른 밑면의 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["다른 밑면은 면 ㄱㅁㅇㄹ이에요.","이 면은 3 cm, 5 cm인 직사각형이에요.","(3 + 5) × 2 = 16이에요."],"mis":"M5-2-u5-X12","asset":{"type":"geo","items":[{"w":88.0,"h":132.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[88.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[66,22.0,"sw"],"ㅁ":[22.0,110,"ne"],"ㅇ":[88.0,110,"e"],"ㅂ":[0,132.0,"sw"],"ㅅ":[66,132.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"poly":[["ㄴ","ㅂ","ㅅ","ㄷ"]],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33.0,140.0],"3 cm"],[[93.0,125.0],"2 cm"],[[48,77.0],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가에 나온 가로 4 cm, 세로 8 cm, 높이 6 cm인 직육면체예요. 면 ㄷㅅㅇㄹ이 밑면일 때 다른 밑면의 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["다른 밑면은 면 ㄴㅂㅁㄱ이에요.","이 면은 8 cm, 6 cm인 직사각형이에요.","(8 + 6) × 2 = 28이에요."],"asset":{"type":"geo","items":[{"w":144.0,"h":180.0,"pts":{"ㄱ":[72.0,0,"nw"],"ㄹ":[144.0,0,"ne"],"ㄴ":[0,72.0,"w"],"ㄷ":[72,72.0,"sw"],"ㅁ":[72.0,108,"ne"],"ㅇ":[144.0,108,"e"],"ㅂ":[0,180.0,"sw"],"ㅅ":[72,180.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"poly":[["ㄷ","ㅅ","ㅇ","ㄹ"]],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[36.0,188.0],"4 cm"],[[124.0,148.0],"8 cm"],[[54,126.0],"6 cm"]]}],"tag":false}},{"stem":"단원 평가에 나온 가로 9 cm,