INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L05_challenge#6','math',5,2,'u5','L05','tb_g5_2_math_u5_L05_challenge','lesson_challenge','M5-2-u5-C5',3,'mc','auto','직육면체에서 옆면끼리의 관계를 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u5-X12']::text[],true,'{"seq":6,"concept":"M5-2-u5-C5","difficulty":3,"kind":"mc","stem":"직육면체에서 옆면끼리의 관계를 바르게 말한 것은 어느 것인가요?","options":[{"t":"이웃한 옆면끼리는 수직이고 마주 보는 옆면끼리는 평행하다","correct":true},{"t":"옆면끼리는 모두 평행하다","mis":"M5-2-u5-X12"},{"t":"옆면끼리는 모두 수직이다","mis":"M5-2-u5-X12"},{"t":"옆면끼리는 만나지 않는다","mis":"M5-2-u5-X12"}],"explanation":["직육면체에서 만나는 두 면은 직각으로 만나요 — 수직.","마주 보아 만나지 않는 두 면은 평행해요.","정답은 「이웃한 옆면끼리는 수직이고 마주 보는 옆면끼리는 평행하다」예요."],"variant_rule":{"alt":[{"stem":"직육면체에서 만나는 두 면은 어떻게 만나나요?","options":[{"t":"수직으로 만난다","correct":true},{"t":"평행하게 만난다","mis":"M5-2-u5-X12"},{"t":"만나지 않는다","mis":"M5-2-u5-X12"},{"t":"비스듬히 만난다","mis":"M5-2-u5-X12"}],"explanation":["직육면체에서 만나는 두 면은 직각으로 만나요 — 수직.","마주 보아 만나지 않는 두 면은 평행해요.","정답은 「수직으로 만난다」예요."]},{"stem":"직육면체의 한 면에 삼각자의 직각을 대었더니 이웃한 면과 딱 맞았어요. 두 면의 관계는 무엇인가요?","options":[{"t":"수직이다","correct":true},{"t":"평행하다","mis":"M5-2-u5-X12"},{"t":"합동이다","mis":"M5-2-u5-X03"},{"t":"같은 면이다","mis":"M5-2-u5-X03"}],"explanation":["직육면체에서 만나는 두 면은 직각으로 만나요 — 수직.","마주 보아 만나지 않는 두 면은 평행해요.","정답은 「수직이다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
