INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L05_challenge#8','math',5,2,'u5','L05','tb_g5_2_math_u5_L05_challenge','lesson_challenge','M5-2-u5-C5',4,'mc','auto','직육면체에 대해 잘못 설명한 것을 찾고 바르게 고친 것은 어느 것인가요? ㉠ 면 ㄱㅁㅇㄹ이 한 밑면일 때, 다른 밑면은 면 ㄴㅂㅅㄷ입니다. ㉡ 직육면체는 평행한 면이 모두 2쌍입니다. ㉢ 면 ㅁㅂㅅㅇ과 수직인 면은 모두 4개입니다.',ARRAY['M5-2-u5-X12','M5-2-u5-X13']::text[],true,'{"seq":8,"concept":"M5-2-u5-C5","difficulty":4,"kind":"mc","stem":"직육면체에 대해 잘못 설명한 것을 찾고 바르게 고친 것은 어느 것인가요? ㉠ 면 ㄱㅁㅇㄹ이 한 밑면일 때, 다른 밑면은 면 ㄴㅂㅅㄷ입니다. ㉡ 직육면체는 평행한 면이 모두 2쌍입니다. ㉢ 면 ㅁㅂㅅㅇ과 수직인 면은 모두 4개입니다.","options":[{"t":"㉡ — 평행한 면은 모두 3쌍이다","correct":true},{"t":"㉠ — 다른 밑면은 면 ㄱㄴㄷㄹ이다","mis":"M5-2-u5-X12"},{"t":"㉢ — 수직인 면은 5개이다","mis":"M5-2-u5-X13"},{"t":"잘못된 것이 없다","mis":"M5-2-u5-X13"}],"explanation":["직육면체에는 평행한 면이 3쌍 있고, 평행한 두 면은 어느 쌍이든 밑면이 될 수 있어요.","만나는 두 면은 수직이라 한 밑면과 수직인 면은 4개예요.","정답은 「㉡ — 평행한 면은 모두 3쌍이다」예요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체에 대해 잘못 설명한 것을 찾고 바르게 고친 것은 어느 것인가요? ㉠ 면 ㄱㄴㄷㄹ과 평행한 면은 면 ㅁㅂㅅㅇ입니다. ㉡ 면 ㄴㅂㅅㄷ은 밑면이 될 수 없습니다. ㉢ 면 ㄷㅅㅇㄹ을 밑면이라고 하면 옆면은 4개입니다.","options":[{"t":"㉡ — 면 ㄴㅂㅅㄷ도 밑면이 될 수 있다","correct":true},{"t":"㉠ — 면 ㄱㄴㄷㄹ과 평행한 면은 면 ㄴㅂㅅㄷ이다","mis":"M5-2-u5-X12"},{"t":"㉢ — 옆면은 2개이다","mis":"M5-2-u5-X13"},{"t":"잘못된 것이 없다","mis":"M5-2-u5-X11"}],"explanation":["직육면체에는 평행한 면이 3쌍 있고, 평행한 두 면은 어느 쌍이든 밑면이 될 수 있어요.","만나는 두 면은 수직이라 한 밑면과 수직인 면은 4개예요.","정답은 「㉡ — 면 ㄴㅂㅅㄷ도 밑면이 될 수 있다」예요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체에 대해 잘못 설명한 것을 찾고 바르게 고친 것은 어느 것인가요? ㉠ 직육면체에서 만나는 두 면은 수직입니다. ㉡ 한 면과 평행한 면은 1개입니다. ㉢ 밑면은 바닥에 닿아 있는 면만 될 수 있습니다.","options":[{"t":"㉢ — 밑면은 서로 평행한 두 면이면 어느 것이든 될 수 있다","correct":true},{"t":"㉠ — 만나는 두 면은 평행하다","mis":"M5-2-u5-X12"},{"t":"㉡ — 한 면과 평행한 면은 2개이다","mis":"M5-2-u5-X13"},{"t":"잘못된 것이 없다","mis":"M5-2-u5-X11"}],"explanation":["직육면체에는 평행한 면이 3쌍 있고, 평행한 두 면은 어느 쌍이든 밑면이 될 수 있어요.","만나는 두 면은 수직이라 한 밑면과 수직인 면은 4개예요.","정답은 「㉢ — 밑면은 서로 평행한 두 면이면 어느 것이든 될 수 있다」예요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L05_challenge#9','math',5,2,'u5','L05','tb_g5_2_math_u5_L05_challenge','lesson_challenge','M5-2-u5-C5',4,'mc','auto','패키지 디자이너가 꿈인 진호는 직육면체 상자에서 색칠한 면 ㄴㅂㅅㄷ과 평행한 면에 ♡ 무늬를 그리려고 해요(수학익힘 77쪽). ♡를 그려야 하는 면은 어느 것인가요?',ARRAY['M5-2-u5-X12']::text[],true,'{"seq":9,"concept":"M5-2-u5-C5","difficulty":4,"kind":"mc","stem":"패키지 디자이너가 꿈인 진호는 직육면체 상자에서 색칠한 면 ㄴㅂㅅㄷ과 평행한 면에 ♡ 무늬를 그리려고 해요(수학익힘 77쪽). ♡를 그려야 하는 면은 어느 것인가요?","options":[{"t":"면 ㄱㅁㅇㄹ","correct":true},{"t":"면 ㄱㄴㄷㄹ","mis":"M5-2-u5-X12"},{"t":"면 ㄷㅅㅇㄹ","mis":"M5-2-u5-X12"},{"t":"면 ㅁㅂㅅㅇ","mis":"M5-2-u5-X12"}],"explanation":["마주 보아 계속 늘여도 만나지 않는 면이 평행한 면이에요.","평행한 면 하나를 뺀 나머지 4개의 면은 모두 수직이에요.","정답은 「면 ㄱㅁㅇㄹ」예요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"poly":[["ㄴ","ㅂ","ㅅ","ㄷ"]],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체에서 색칠한 면 ㄱㅁㅇㄹ과 수직인 면을 모두 고른 것은 어느 것인가요?(단원 평가)","options":[{"t":"면 ㄱㄴㄷㄹ, 면 ㄴㅂㅁㄱ, 면 ㅁㅂㅅㅇ, 면 ㄷㅅㅇㄹ","correct":true},{"t":"면 ㄱㄴㄷㄹ, 면 ㄴㅂㅅㄷ, 면 ㅁㅂㅅㅇ, 면 ㄷㅅㅇㄹ","mis":"M5-2-u5-X12"},{"t":"면 ㄱㄴㄷㄹ, 면 ㅁㅂㅅㅇ","mis":"M5-2-u5-X13"},{"t":"면 ㄴㅂㅅㄷ","mis":"M5-2-u5-X12"}],"explanation":["마주 보아 계속 늘여도 만나지 않는 면이 평행한 면이에요.","평행한 면 하나를 뺀 나머지 4개의 면은 모두 수직이에요.","정답은 「면 ㄱㄴㄷㄹ, 면 ㄴㅂㅁㄱ, 면 ㅁㅂㅅㅇ, 면 ㄷㅅㅇㄹ」예요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"poly":[["ㄱ","ㅁ","ㅇ","ㄹ"]],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"진호가 색칠한 면 ㄷㅅㅇㄹ과 평행한 면에 ♡ 무늬를 그리려고 해요. ♡를 그려야 하는 면은 어느 것인가요?","options":[{"t":"면 ㄴㅂㅁㄱ","correct":true},{"t":"면 ㄴㅂㅅㄷ","mis":"M5-2-u5-X12"},{"t":"면 ㄱㄴㄷㄹ","mis":"M5-2-u5-X12"},{"t":"면 ㄱㅁㅇㄹ","mis":"M5-2-u5-X12"}],"explanation":["마주 보아 계속 늘여도 만나지 않는 면이 평행한 면이에요.","평행한 면 하나를 뺀 나머지 4개의 면은 모두 수직이에요.","정답은 「면 ㄴㅂㅁㄱ」예요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"poly":[["ㄷ","ㅅ","ㅇ","ㄹ"]],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L05_challenge#10','math',5,2,'u5','L05','tb_g5_2_math_u5_L05_challenge','lesson_challenge','M5-2-u5-C5',4,'essay','teacher','삼촌네 과일 가게에서 상자를 눕혀 놓은 것을 보고 순달이가 「바닥에 닿은 면이 아니니까 옆에 선 두 면은 밑면이 될 수 없어.」라고 했어요. 이 말이 맞는지 판단하고, 밑면과 옆면의 뜻을 넣어 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u5-C5","difficulty":4,"kind":"essay","stem":"삼촌네 과일 가게에서 상자를 눕혀 놓은 것을 보고 순달이가 「바닥에 닿은 면이 아니니까 옆에 선 두 면은 밑면이 될 수 없어.」라고 했어요. 이 말이 맞는지 판단하고, 밑면과 옆면의 뜻을 넣어 까닭을 쓰세요.","answer_guide":{"answer":"예: 이 말은 틀렸다. 밑면은 놓인 위치가 아니라 계속 늘여도 만나지 않는 서로 평행한 두 면을 말한다. 옆에 선 두 면도 서로 평행하므로 밑면이 될 수 있다. 그때 이 두 면과 수직으로 만나는 나머지 4개의 면이 옆면이 된다.","scoring_points":["틀렸다고 판단했는가","밑면은 서로 평행한 두 면이라고 썼는가","옆면은 밑면과 수직인 면 4개라고 썼는가"]},"explanation":["밑면은 위치가 아니라 평행한 관계로 정해요.","옆에 선 두 면도 평행하면 밑면이에요.","밑면과 수직인 4개의 면이 옆면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L06_basic#1','math',5,2,'u5','L06','tb_g5_2_math_u5_L06_basic','lesson_basic','M5-2-u5-C6',1,'mc','auto','직육면체의 모든 면이 이어지도록 모서리를 잘라서 평면 위에 펼친 그림을 무엇이라고 하나요?',ARRAY['M5-2-u5-X16','M5-2-u5-X02','M5-2-u5-X01']::text[],true,'{"seq":1,"concept":"M5-2-u5-C6","difficulty":1,"kind":"mc","stem":"직육면체의 모든 면이 이어지도록 모서리를 잘라서 평면 위에 펼친 그림을 무엇이라고 하나요?","options":[{"t":"직육면체의 전개도","correct":true},{"t":"직육면체의 겨냥도","mis":"M5-2-u5-X16"},{"t":"직사각형","mis":"M5-2-u5-X02"},{"t":"평면도형","mis":"M5-2-u5-X01"}],"explanation":["전개도는 모든 면이 이어지게 모서리를 잘라 펼친 그림이에요.","잘린 모서리는 실선, 잘리지 않은(접는) 모서리는 점선이에요.","정답은 「직육면체의 전개도」예요."],"asset":{"type":"geo","items":[{"w":200,"h":100,"seg":[[[0,0],[0,100]],[[0,0],[60,0]],[[0,100],[60,100]],[[60,0],[60,40]],[[60,40],[200,40]],[[60,60],[60,100]],[[60,60],[200,60]],[[200,40],[200,60]]],"dash":[[[0,40],[60,40]],[[0,60],[60,60]],[[60,40],[60,60]],[[100,40],[100,60]],[[160,40],[160,60]]],"lab":[[[30.0,15.0],"가"],[[30.0,45.0],"나"],[[80.0,45.0],"다"],[[130.0,45.0],"라"],[[180.0,45.0],"마"],[[30.0,75.0],"바"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체의 전개도에서 잘린 모서리는 어떻게 나타내나요?","options":[{"t":"실선으로 나타낸다","correct":true},{"t":"점선으로 나타낸다","mis":"M5-2-u5-X16"},{"t":"나타내지 않는다","mis":"M5-2-u5-X16"},{"t":"색칠해 나타낸다","mis":"M5-2-u5-X03"}],"explanation":["전개도는 모든 면이 이어지게 모서리를 잘라 펼친 그림이에요.","잘린 모서리는 실선, 잘리지 않은(접는) 모서리는 점선이에요.","정답은 「실선으로 나타낸다」예요."],"asset":{"type":"geo","items":[{"w":200,"h":100,"seg":[[[0,0],[0,100]],[[0,0],[60,0]],[[0,100],[60,100]],[[60,0],[60,40]],[[60,40],[200,40]],[[60,60],[60,100]],[[60,60],[200,60]],[[200,40],[200,60]]],"dash":[[[0,40],[60,40]],[[0,60],[60,60]],[[60,40],[60,60]],[[100,40],[100,60]],[[160,40],[160,60]]],"lab":[[[30.0,15.0],"가"],[[30.0,45.0],"나"],[[80.0,45.0],"다"],[[130.0,45.0],"라"],[[180.0,45.0],"마"],[[30.0,75.0],"바"]]}],"tag":false}},{"stem":"직육면체의 전개도에서 잘리지 않은 모서리는 어떻게 나타내나요?","options":[{"t":"점선으로 나타낸다","correct":true},{"t":"실선으로 나타낸다","mis":"M5-2-u5-X16"},{"t":"나타내지 않는다","mis":"M5-2-u5-X16"},{"t":"굵은 선으로 나타낸다","mis":"M5-2-u5-X16"}],"explanation":["전개도는 모든 면이 이어지게 모서리를 잘라 펼친 그림이에요.","잘린 모서리는 실선, 잘리지 않은(접는) 모서리는 점선이에요.","정답은 「점선으로 나타낸다」예요."],"asset":{"type":"geo","items":[{"w":200,"h":100,"seg":[[[0,0],[0,100]],[[0,0],[60,0]],[[0,100],[60,100]],[[60,0],[60,40]],[[60,40],[200,40]],[[60,60],[60,100]],[[60,60],[200,60]],[[200,40],[200,60]]],"dash":[[[0,40],[60,40]],[[0,60],[60,60]],[[60,40],[60,60]],[[100,40],[100,60]],[[160,40],[160,60]]],"lab":[[[30.0,15.0],"가"],[[30.0,45.0],"나"],[[80.0,45.0],"다"],[[130.0,45.0],"라"],[[180.0,45.0],"마"],[[30.0,75.0],"바"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L06_basic#2','math',5,2,'u5','L06','tb_g5_2_math_u5_L06_basic','lesson_basic','M5-2-u5-C6',1,'mc','auto','교과서 116쪽 정육면체의 전개도를 접었을 때 면 가와 평행한 면은 어느 것인가요?',ARRAY['M5-2-u5-X12']::text[],true,'{"seq":2,"concept":"M5-2-u5-C6","difficulty":1,"kind":"mc","stem":"교과서 116쪽 정육면체의 전개도를 접었을 때 면 가와 평행한 면은 어느 것인가요?","options":[{"t":"면 바","correct":true},{"t":"면 나","mis":"M5-2-u5-X12"},{"t":"면 다","mis":"M5-2-u5-X12"},{"t":"면 라","mis":"M5-2-u5-X12"}],"explanation":["접었을 때 마주 보는 면이 평행한 면이에요.","한 줄로 이어진 네 면에서는 하나 건너 있는 면끼리 평행해요.","면 가와 평행한 면은 면 바예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[30,60]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,90],[60,90]],[[60,60],[60,90]],[[60,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[30,60],[60,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"가"],[[15.0,40.0],"나"],[[45.0,40.0],"다"],[[75.0,40.0],"라"],[[105.0,40.0],"마"],[[45.0,70.0],"바"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"교과서 116쪽 ④의 전개도를 접었을 때 면 나와 평행한 면은 어느 것인가요?","options":[{"t":"면 라","correct":true},{"t":"면 가","mis":"M5-2-u5-X12"},{"t":"면 다","mis":"M5-2-u5-X12"},{"t":"면 마","mis":"M5-2-u5-X12"}],"explanation":["접었을 때 마주 보는 면이 평행한 면이에요.","한 줄로 이어진 네 면에서는 하나 건너 있는 면끼리 평행해요.","면 나와 평행한 면은 면 라예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,30],[0,60]],[[0,30],[30,30]],[[0,60],[90,60]],[[30,0],[30,30]],[[30,0],[60,0]],[[60,0],[60,30]],[[60,30],[120,30]],[[90,60],[90,90]],[[90,90],[120,90]],[[120,30],[120,90]]],"dash":[[[30,30],[30,60]],[[30,30],[60,30]],[[60,30],[60,60]],[[90,30],[90,60]],[[90,60],[120,60]]],"lab":[[[45.0,10.0],"가"],[[15.0,40.0],"나"],[[45.0,40.0],"다"],[[75.0,40.0],"라"],[[105.0,40.0],"마"],[[105.0,70.0],"바"]]}],"tag":false}},{"stem":"단원 평가의 전개도를 접었을 때 면 다와 평행한 면은 어느 것인가요?","options":[{"t":"면 마","correct":true},{"t":"면 가","mis":"M5-2-u5-X12"},{"t":"면 나","mis":"M5-2-u5-X12"},{"t":"면 라","mis":"M5-2-u5-X12"}],"explanation":["접었을 때 마주 보는 면이 평행한 면이에요.","한 줄로 이어진 네 면에서는 하나 건너 있는 면끼리 평행해요.","면 다와 평행한 면은 면 마예요."],"asset":{"type":"geo","items":[{"w":192,"h":128,"seg":[[[0,0],[0,32]],[[0,0],[112,0]],[[0,32],[64,32]],[[64,32],[64,128]],[[64,128],[112,128]],[[112,0],[112,32]],[[112,32],[192,32]],[[112,96],[112,128]],[[112,96],[192,96]],[[192,32],[192,96]]],"dash":[[[64,0],[64,32]],[[64,32],[112,32]],[[64,96],[112,96]],[[112,32],[112,96]],[[144,32],[144,96]]],"lab":[[[32.0,11.0],"가"],[[88.0,11.0],"나"],[[88.0,59.0],"다"],[[128.0,59.0],"라"],[[168.0,59.0],"마"],[[88.0,107.0],"바"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L06_basic#3','math',5,2,'u5','L06','tb_g5_2_math_u5_L06_basic','lesson_basic','M5-2-u5-C6',1,'sa','auto','교과서 116쪽 정육면체의 전개도예요. 전개도를 접었을 때 서로 평행한 면은 모두 몇 쌍인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u5-C6","difficulty":1,"kind":"sa","stem":"교과서 116쪽 정육면체의 전개도예요. 전개도를 접었을 때 서로 평행한 면은 모두 몇 쌍인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["전개도를 접으면 마주 보는 면은 평행하고, 만나는 면은 수직이에요.","마주 보는 면끼리 평행해요 — 가와 바, 나와 라, 다와 마.","그래서 3이에요."],"mis":"M5-2-u5-X13","asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[30,60]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,90],[60,90]],[[60,60],[60,90]],[[60,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[30,60],[60,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"가"],[[15.0,40.0],"나"],[[45.0,40.0],"다"],[[75.0,40.0],"라"],[[105.0,40.0],"마"],[[45.0,70.0],"바"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"교과서 116쪽 정육면체의 전개도예요. 전개도를 접었을 때 면 가와 수직인 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["전개도를 접으면 마주 보는 면은 평행하고, 만나는 면은 수직이에요.","평행한 면 바를 뺀 나머지 6 − 2 = 4(개)예요.","그래서 4예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[30,60]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,90],[60,90]],[[60,60],[60,90]],[[60,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[30,60],[60,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"가"],[[15.0,40.0],"나"],[[45.0,40.0],"다"],[[75.0,40.0],"라"],[[105.0,40.0],"마"],[[45.0,70.0],"바"]]}],"tag":false}},{"stem":"교과서 116쪽 정육면체의 전개도예요. 이 전개도에서 잘리지 않은 모서리(점선)는 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["전개도를 접으면 마주 보는 면은 평행하고, 만나는 면은 수직이에요.","면 6개를 이어 붙인 점선이 5개 있어요.","그래서 5예요."],"asset":{"typ