INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L06_basic#8','math',5,2,'u5','L06','tb_g5_2_math_u5_L06_basic','lesson_basic','M5-2-u5-C6',2,'mc','auto','교과서 117쪽 ⑤의 나 — 이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?',ARRAY['M5-2-u5-X14','M5-2-u5-X02']::text[],true,'{"seq":8,"concept":"M5-2-u5-C6","difficulty":2,"kind":"mc","stem":"교과서 117쪽 ⑤의 나 — 이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?","options":[{"t":"접었을 때 겹치는 면이 있다","correct":true},{"t":"접었을 때 만나는 선분의 길이가 다르다","mis":"M5-2-u5-X14"},{"t":"면이 5개뿐이다","mis":"M5-2-u5-X14"},{"t":"직사각형이 아닌 면이 있다","mis":"M5-2-u5-X02"}],"explanation":["전개도는 면 6개가 겹치지 않게 접혀 직육면체를 둘러싸야 해요.","접은 모양을 떠올려 겹치는 면, 만나는 선분의 길이, 면의 수를 살펴봐요.","까닭은 「접었을 때 겹치는 면이 있다」예요."],"asset":{"type":"geo","items":[{"w":120,"h":60,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[120,60]],[[30,0],[30,30]],[[30,30],[90,30]],[[90,0],[90,30]],[[90,0],[120,0]],[[120,0],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]],[[90,30],[120,30]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"교과서 117쪽 ⑤의 라 — 이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?","options":[{"t":"접었을 때 만나는 선분의 길이가 다르다","correct":true},{"t":"접었을 때 겹치는 면이 있다","mis":"M5-2-u5-X14"},{"t":"면이 5개뿐이다","mis":"M5-2-u5-X14"},{"t":"직사각형이 아닌 면이 있다","mis":"M5-2-u5-X02"}],"explanation":["전개도는 면 6개가 겹치지 않게 접혀 직육면체를 둘러싸야 해요.","접은 모양을 떠올려 겹치는 면, 만나는 선분의 길이, 면의 수를 살펴봐요.","까닭은 「접었을 때 만나는 선분의 길이가 다르다」예요."],"asset":{"type":"geo","items":[{"w":192,"h":108,"seg":[[[0,36],[0,72]],[[0,36],[60,36]],[[0,72],[156,72]],[[60,0],[60,36]],[[60,0],[96,0]],[[96,0],[96,36]],[[96,36],[192,36]],[[156,72],[156,108]],[[156,108],[192,108]],[[192,36],[192,108]]],"dash":[[[60,36],[60,72]],[[60,36],[96,36]],[[96,36],[96,72]],[[156,36],[156,72]],[[156,72],[192,72]]]}],"tag":false}},{"stem":"교과서 117쪽 ⑤의 마 — 이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?","options":[{"t":"면이 5개뿐이다","correct":true},{"t":"접었을 때 겹치는 면이 있다","mis":"M5-2-u5-X14"},{"t":"접었을 때 만나는 선분의 길이가 다르다","mis":"M5-2-u5-X14"},{"t":"직사각형이 아닌 면이 있다","mis":"M5-2-u5-X02"}],"explanation":["전개도는 면 6개가 겹치지 않게 접혀 직육면체를 둘러싸야 해요.","접은 모양을 떠올려 겹치는 면, 만나는 선분의 길이, 면의 수를 살펴봐요.","까닭은 「면이 5개뿐이다」예요."],"asset":{"type":"geo","items":[{"w":120,"h":60,"seg":[[[0,0],[0,60]],[[0,0],[120,0]],[[0,60],[30,60]],[[30,30],[30,60]],[[30,30],[120,30]],[[120,0],[120,30]]],"dash":[[[0,30],[30,30]],[[30,0],[30,30]],[[60,0],[60,30]],[[90,0],[90,30]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L06_basic#9','math',5,2,'u5','L06','tb_g5_2_math_u5_L06_basic','lesson_basic','M5-2-u5-C6',2,'ox','auto','면이 6개인 그림은 모두 직육면체의 전개도예요.',ARRAY['M5-2-u5-X14']::text[],true,'{"seq":9,"concept":"M5-2-u5-C6","difficulty":2,"kind":"ox","stem":"면이 6개인 그림은 모두 직육면체의 전개도예요.","answer":"X","reason_options":[{"t":"면이 6개여도 접었을 때 겹치는 면이 있거나 맞붙는 선분의 길이가 다르면 전개도가 아니므로","correct":true},{"t":"면의 수만 맞으면 되므로","mis":"M5-2-u5-X14"}],"mis":"M5-2-u5-X14","explanation":["전개도를 접은 모양을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「면이 6개여도 접었을 때 겹치는 면이 있거나 맞붙는 선분의 길이가 다르면 전개도가 아니므로」를 골라요."],"variant_rule":{"alt":[{"stem":"전개도를 접었을 때 만나는 두 선분은 길이가 같아요.","answer":"O","reason_options":[{"t":"두 선분이 한 모서리가 되므로","correct":true},{"t":"접으면 길이가 늘어나므로","mis":"M5-2-u5-X14"}],"explanation":["전개도를 접은 모양을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 O예요.","까닭으로 「두 선분이 한 모서리가 되므로」를 골라요."]},{"stem":"전개도에서 잘린 모서리는 점선으로 나타내요.","answer":"X","reason_options":[{"t":"잘린 모서리는 실선, 잘리지 않은 모서리가 점선이므로","correct":true},{"t":"잘린 곳은 끊어졌으니 점선이므로","mis":"M5-2-u5-X16"}],"explanation":["전개도를 접은 모양을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「잘린 모서리는 실선, 잘리지 않은 모서리가 점선이므로」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
