INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L06_challenge#1','math',5,2,'u5','L06','tb_g5_2_math_u5_L06_challenge','lesson_challenge','M5-2-u5-C6',2,'mc','auto','교과서 115쪽 상자의 전개도를 접었을 때 색칠한 면 가와 수직인 면을 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u5-X12','M5-2-u5-X13']::text[],true,'{"seq":1,"concept":"M5-2-u5-C6","difficulty":2,"kind":"mc","stem":"교과서 115쪽 상자의 전개도를 접었을 때 색칠한 면 가와 수직인 면을 모두 고른 것은 어느 것인가요?","options":[{"t":"면 나, 면 다, 면 라, 면 마","correct":true},{"t":"면 나, 면 다, 면 라, 면 바","mis":"M5-2-u5-X12"},{"t":"면 다, 면 라, 면 마, 면 바","mis":"M5-2-u5-X12"},{"t":"면 나, 면 다, 면 바","mis":"M5-2-u5-X13"}],"explanation":["접었을 때 색칠한 면과 마주 보는 면 바 하나만 평행해요.","나머지 4개의 면은 색칠한 면과 수직으로 만나요 — 밑면이면 이 4개가 옆면이에요.","정답은 면 나, 면 다, 면 라, 면 마예요."],"asset":{"type":"geo","items":[{"w":180,"h":135,"poly":[[[120,0],[180,0],[180,30],[120,30]]],"seg":[[[0,30],[0,105]],[[0,30],[120,30]],[[0,105],[120,105]],[[120,0],[120,30]],[[120,0],[180,0]],[[120,105],[120,135]],[[120,135],[180,135]],[[180,0],[180,135]]],"dash":[[[30,30],[30,105]],[[90,30],[90,105]],[[120,30],[120,105]],[[120,30],[180,30]],[[120,105],[180,105]]],"lab":[[[150.0,10.0],"가"],[[15.0,62.5],"나"],[[60.0,62.5],"다"],[[105.0,62.5],"라"],[[150.0,62.5],"마"],[[150.0,115.0],"바"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"형성 평가의 전개도를 접었을 때 색칠한 면 가와 수직인 면을 모두 고른 것은 어느 것인가요?","options":[{"t":"면 나, 면 다, 면 라, 면 마","correct":true},{"t":"면 나, 면 다, 면 라, 면 바","mis":"M5-2-u5-X12"},{"t":"면 다, 면 라, 면 마, 면 바","mis":"M5-2-u5-X12"},{"t":"면 나, 면 다, 면 바","mis":"M5-2-u5-X13"}],"explanation":["접었을 때 색칠한 면과 마주 보는 면 바 하나만 평행해요.","나머지 4개의 면은 색칠한 면과 수직으로 만나요 — 밑면이면 이 4개가 옆면이에요.","정답은 면 나, 면 다, 면 라, 면 마예요."],"asset":{"type":"geo","items":[{"w":196,"h":140,"poly":[[[126,0],[196,0],[196,28],[126,28]]],"seg":[[[0,28],[0,70]],[[0,28],[126,28]],[[0,70],[98,70]],[[98,70],[98,140]],[[98,140],[126,140]],[[126,0],[126,28]],[[126,0],[196,0]],[[126,70],[126,140]],[[126,70],[196,70]],[[196,0],[196,70]]],"dash":[[[28,28],[28,70]],[[98,28],[98,70]],[[98,70],[126,70]],[[126,28],[126,70]],[[126,28],[196,28]]],"lab":[[[161.0,9.0],"가"],[[14.0,44.0],"나"],[[63.0,44.0],"다"],[[112.0,44.0],"라"],[[161.0,44.0],"마"],[[112.0,100.0],"바"]]}],"tag":false}},{"stem":"문제로 마무리의 전개도를 접었을 때 색칠한 면 바가 밑면이면 옆면을 모두 고른 것은 어느 것인가요?","options":[{"t":"면 나, 면 다, 면 라, 면 마","correct":true},{"t":"면 가, 면 나, 면 다, 면 라","mis":"M5-2-u5-X12"},{"t":"면 가, 면 다, 면 라, 면 마","mis":"M5-2-u5-X12"},{"t":"면 가, 면 나, 면 다","mis":"M5-2-u5-X13"}],"explanation":["접었을 때 색칠한 면과 마주 보는 면 가 하나만 평행해요.","나머지 4개의 면은 색칠한 면과 수직으로 만나요 — 밑면이면 이 4개가 옆면이에요.","정답은 면 나, 면 다, 면 라, 면 마예요."],"asset":{"type":"geo","items":[{"w":180,"h":135,"poly":[[[60,75],[90,75],[90,135],[60,135]]],"seg":[[[0,30],[0,75]],[[0,30],[90,30]],[[0,75],[60,75]],[[60,75],[60,135]],[[60,135],[90,135]],[[90,0],[90,30]],[[90,0],[150,0]],[[90,75],[90,135]],[[90,75],[180,75]],[[150,0],[150,30]],[[150,30],[180,30]],[[180,30],[180,75]]],"dash":[[[60,30],[60,75]],[[60,75],[90,75]],[[90,30],[90,75]],[[90,30],[150,30]],[[150,30],[150,75]]],"lab":[[[120.0,10.0],"가"],[[30.0,47.5],"나"],[[75.0,47.5],"다"],[[120.0,47.5],"라"],[[165.0,47.5],"마"],[[75.0,100.0],"바"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L06_challenge#2','math',5,2,'u5','L06','tb_g5_2_math_u5_L06_challenge','lesson_challenge','M5-2-u5-C6',2,'ox','auto','전개도를 접었을 때 만나는 두 선분은 길이가 같아요.',ARRAY['M5-2-u5-X14']::text[],true,'{"seq":2,"concept":"M5-2-u5-C6","difficulty":2,"kind":"ox","stem":"전개도를 접었을 때 만나는 두 선분은 길이가 같아요.","answer":"O","reason_options":[{"t":"두 선분이 한 모서리가 되므로","correct":true},{"t":"접으면 길이가 늘어나므로","mis":"M5-2-u5-X14"}],"mis":"M5-2-u5-X14","explanation":["전개도를 접은 모양을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 O예요.","까닭으로 「두 선분이 한 모서리가 되므로」를 골라요."],"variant_rule":{"alt":[{"stem":"전개도에서 잘린 모서리는 점선으로 나타내요.","answer":"X","reason_options":[{"t":"잘린 모서리는 실선, 잘리지 않은 모서리가 점선이므로","correct":true},{"t":"잘린 곳은 끊어졌으니 점선이므로","mis":"M5-2-u5-X16"}],"explanation":["전개도를 접은 모양을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「잘린 모서리는 실선, 잘리지 않은 모서리가 점선이므로」를 골라요."]},{"stem":"직육면체의 전개도에서 한 줄로 이어진 네 면은 하나 건너 있는 면끼리 평행해요.","answer":"O","reason_options":[{"t":"접으면 하나 건너 있는 면끼리 마주 보므로","correct":true},{"t":"바로 옆에 있는 면끼리 마주 보므로","mis":"M5-2-u5-X12"}],"explanation":["전개도를 접은 모양을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 O예요.","까닭으로 「접으면 하나 건너 있는 면끼리 마주 보므로」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
