INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L06_challenge#5','math',5,2,'u5','L06','tb_g5_2_math_u5_L06_challenge','lesson_challenge','M5-2-u5-C6',3,'mc','auto','문제로 마무리 10번의 가 — 이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?',ARRAY['M5-2-u5-X14','M5-2-u5-X02']::text[],true,'{"seq":5,"concept":"M5-2-u5-C6","difficulty":3,"kind":"mc","stem":"문제로 마무리 10번의 가 — 이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?","options":[{"t":"접었을 때 겹치는 면이 있다","correct":true},{"t":"접었을 때 만나는 선분의 길이가 다르다","mis":"M5-2-u5-X14"},{"t":"면이 5개뿐이다","mis":"M5-2-u5-X14"},{"t":"직사각형이 아닌 면이 있다","mis":"M5-2-u5-X02"}],"explanation":["전개도는 면 6개가 겹치지 않게 접혀 직육면체를 둘러싸야 해요.","접은 모양을 떠올려 겹치는 면, 만나는 선분의 길이, 면의 수를 살펴봐요.","까닭은 「접었을 때 겹치는 면이 있다」예요."],"asset":{"type":"geo","items":[{"w":150,"h":60,"seg":[[[0,0],[0,30]],[[0,0],[120,0]],[[0,30],[90,30]],[[90,30],[90,60]],[[90,60],[150,60]],[[120,0],[120,30]],[[120,30],[150,30]],[[150,30],[150,60]]],"dash":[[[30,0],[30,30]],[[60,0],[60,30]],[[90,0],[90,30]],[[90,30],[120,30]],[[120,30],[120,60]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가의 다 — 이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?","options":[{"t":"접었을 때 겹치는 면이 있다","correct":true},{"t":"접었을 때 만나는 선분의 길이가 다르다","mis":"M5-2-u5-X14"},{"t":"면이 5개뿐이다","mis":"M5-2-u5-X14"},{"t":"직사각형이 아닌 면이 있다","mis":"M5-2-u5-X02"}],"explanation":["전개도는 면 6개가 겹치지 않게 접혀 직육면체를 둘러싸야 해요.","접은 모양을 떠올려 겹치는 면, 만나는 선분의 길이, 면의 수를 살펴봐요.","까닭은 「접었을 때 겹치는 면이 있다」예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,60],[0,90]],[[0,60],[30,60]],[[0,90],[120,90]],[[30,0],[30,60]],[[30,0],[60,0]],[[60,0],[60,60]],[[60,60],[120,60]],[[120,60],[120,90]]],"dash":[[[30,30],[60,30]],[[30,60],[30,90]],[[30,60],[60,60]],[[60,60],[60,90]],[[90,60],[90,90]]]}],"tag":false}},{"stem":"형성 평가의 셋째 그림 — 이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?","options":[{"t":"접었을 때 겹치는 면이 있다","correct":true},{"t":"접었을 때 만나는 선분의 길이가 다르다","mis":"M5-2-u5-X14"},{"t":"면이 5개뿐이다","mis":"M5-2-u5-X14"},{"t":"직사각형이 아닌 면이 있다","mis":"M5-2-u5-X02"}],"explanation":["전개도는 면 6개가 겹치지 않게 접혀 직육면체를 둘러싸야 해요.","접은 모양을 떠올려 겹치는 면, 만나는 선분의 길이, 면의 수를 살펴봐요.","까닭은 「접었을 때 겹치는 면이 있다」예요."],"asset":{"type":"geo","items":[{"w":120,"h":60,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[120,60]],[[30,0],[30,30]],[[30,30],[90,30]],[[90,0],[90,30]],[[90,0],[120,0]],[[120,0],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]],[[90,30],[120,30]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L06_challenge#6','math',5,2,'u5','L06','tb_g5_2_math_u5_L06_challenge','lesson_challenge','M5-2-u5-C6',3,'mc','auto','교과서 117쪽 ⑤의 가 전개도를 접었을 때 면 다와 수직인 면을 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u5-X12','M5-2-u5-X13']::text[],true,'{"seq":6,"concept":"M5-2-u5-C6","difficulty":3,"kind":"mc","stem":"교과서 117쪽 ⑤의 가 전개도를 접었을 때 면 다와 수직인 면을 모두 고른 것은 어느 것인가요?","options":[{"t":"면 가, 면 나, 면 라, 면 바","correct":true},{"t":"면 가, 면 나, 면 라, 면 마","mis":"M5-2-u5-X12"},{"t":"면 나, 면 라, 면 마, 면 바","mis":"M5-2-u5-X12"},{"t":"면 가, 면 나, 면 마","mis":"M5-2-u5-X13"}],"explanation":["면 다와 평행한 면은 면 마 하나뿐이에요.","나머지 4개의 면은 모두 면 다와 수직이에요.","정답은 면 가, 면 나, 면 라, 면 바예요."],"asset":{"type":"geo","items":[{"w":144,"h":132,"seg":[[[0,48],[0,84]],[[0,48],[72,48]],[[0,84],[72,84]],[[72,0],[72,48]],[[72,0],[96,0]],[[72,84],[72,132]],[[72,132],[96,132]],[[96,0],[96,48]],[[96,48],[144,48]],[[96,84],[96,132]],[[96,84],[144,84]],[[144,48],[144,84]]],"dash":[[[24,48],[24,84]],[[72,48],[72,84]],[[72,48],[96,48]],[[72,84],[96,84]],[[96,48],[96,84]]],"lab":[[[84.0,19.0],"가"],[[12.0,61.0],"나"],[[48.0,61.0],"다"],[[84.0,61.0],"라"],[[120.0,61.0],"마"],[[84.0,103.0],"바"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가의 전개도를 접었을 때 면 가와 수직인 면을 모두 고른 것은 어느 것인가요?","options":[{"t":"면 나, 면 다, 면 마, 면 바","correct":true},{"t":"면 나, 면 다, 면 라, 면 마","mis":"M5-2-u5-X12"},{"t":"면 다, 면 라, 면 마, 면 바","mis":"M5-2-u5-X12"},{"t":"면 나, 면 다, 면 라","mis":"M5-2-u5-X13"}],"explanation":["면 가와 평행한 면은 면 라 하나뿐이에요.","나머지 4개의 면은 모두 면 가와 수직이에요.","정답은 면 나, 면 다, 면 마, 면 바예요."],"asset":{"type":"geo","items":[{"w":192,"h":128,"seg":[[[0,0],[0,32]],[[0,0],[112,0]],[[0,32],[64,32]],[[64,32],[64,128]],[[64,128],[112,128]],[[112,0],[112,32]],[[112,32],[192,32]],[[112,96],[112,128]],[[112,96],[192,96]],[[192,32],[192,96]]],"dash":[[[64,0],[64,32]],[[64,32],[112,