INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L06_challenge#7','math',5,2,'u5','L06','tb_g5_2_math_u5_L06_challenge','lesson_challenge','M5-2-u5-C6',3,'mc','auto','교과서 117쪽 ⑤의 바는 크기가 같은 정사각형 6개로 된 정육면체의 전개도예요. 바를 「직육면체의 전개도」라고 할 수 있나요?',ARRAY['M5-2-u5-X06','M5-2-u5-X14']::text[],true,'{"seq":7,"concept":"M5-2-u5-C6","difficulty":3,"kind":"mc","stem":"교과서 117쪽 ⑤의 바는 크기가 같은 정사각형 6개로 된 정육면체의 전개도예요. 바를 「직육면체의 전개도」라고 할 수 있나요?","options":[{"t":"있다 — 정육면체는 직육면체라고 할 수 있으므로","correct":true},{"t":"없다 — 면이 정사각형이므로","mis":"M5-2-u5-X06"},{"t":"없다 — 면의 크기가 모두 같으므로","mis":"M5-2-u5-X06"},{"t":"있다 — 면이 5개이므로","mis":"M5-2-u5-X14"}],"explanation":["정사각형은 네 각이 직각이므로 직사각형이에요.","그래서 정육면체는 직육면체이고, 정육면체의 전개도도 직육면체의 전개도예요.","정답은 「있다 — 정육면체는 직육면체라고 할 수 있으므로」예요."],"asset":{"type":"geo","items":[{"w":150,"h":60,"seg":[[[0,0],[0,30]],[[0,0],[90,0]],[[0,30],[60,30]],[[60,30],[60,60]],[[60,60],[150,60]],[[90,0],[90,30]],[[90,30],[150,30]],[[150,30],[150,60]]],"dash":[[[30,0],[30,30]],[[60,0],[60,30]],[[60,30],[90,30]],[[90,30],[90,60]],[[120,30],[120,60]]],"lab":[[[15.0,10.0],"가"],[[45.0,10.0],"나"],[[75.0,10.0],"다"],[[75.0,40.0],"라"],[[105.0,40.0],"마"],[[135.0,40.0],"바"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"정육면체의 전개도를 보고 「직육면체의 전개도가 아니야.」라고 말한 친구에게 해 줄 말로 알맞은 것은 어느 것인가요?","options":[{"t":"정사각형은 직사각형이므로 정육면체의 전개도도 직육면체의 전개도이다","correct":true},{"t":"맞다 — 정사각형은 직사각형이 아니다","mis":"M5-2-u5-X06"},{"t":"맞다 — 정육면체는 전개도가 없다","mis":"M5-2-u5-X14"},{"t":"접어 보지 않으면 알 수 없다","mis":"M5-2-u5-X14"}],"explanation":["정사각형은 네 각이 직각이므로 직사각형이에요.","그래서 정육면체는 직육면체이고, 정육면체의 전개도도 직육면체의 전개도예요.","정답은 「정사각형은 직사각형이므로 정육면체의 전개도도 직육면체의 전개도이다」예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[30,60]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,90],[60,90]],[[60,60],[60,90]],[[60,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[30,60],[60,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"가"],[[15.0,40.0],"나"],[[45.0,40.0],"다"],[[75.0,40.0],"라"],[[105.0,40.0],"마"],[[45.0,70.0],"바"]]}],"tag":false}},{"stem":"교과서 116쪽 정육면체의 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"정육면체 — 직육면체라고도 할 수 있다","correct":true},{"t":"정육면체 — 직육면체라고는 할 수 없다","mis":"M5-2-u5-X06"},{"t":"직사각형","mis":"M5-2-u5-X01"},{"t":"면이 6개인 평면도형","mis":"M5-2-u5-X01"}],"explanation":["정사각형은 네 각이 직각이므로 직사각형이에요.","그래서 정육면체는 직육면체이고, 정육면체의 전개도도 직육면체의 전개도예요.","정답은 「정육면체 — 직육면체라고도 할 수 있다」예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[30,60]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,90],[60,90]],[[60,60],[60,90]],[[60,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[30,60],[60,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"가"],[[15.0,40.0],"나"],[[45.0,40.0],"다"],[[75.0,40.0],"라"],[[105.0,40.0],"마"],[[45.0,70.0],"바"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L06_challenge#8','math',5,2,'u5','L06','tb_g5_2_math_u5_L06_challenge','lesson_challenge','M5-2-u5-C6',4,'mc','auto','문제로 마무리 10번의 그림 가~다예요. 직육면체의 전개도가 될 수 없는 것을 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u5-X14']::text[],true,'{"seq":8,"concept":"M5-2-u5-C6","difficulty":4,"kind":"mc","stem":"문제로 마무리 10번의 그림 가~다예요. 직육면체의 전개도가 될 수 없는 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"가","correct":true},{"t":"나","mis":"M5-2-u5-X14"},{"t":"다","mis":"M5-2-u5-X14"},{"t":"가, 다","mis":"M5-2-u5-X14"}],"explanation":["그림마다 접은 모양을 떠올려요.","겹치는 면이 있거나 만나는 선분의 길이가 다르거나 면이 모자라면 전개도가 아니에요.","정답은 가예요."],"asset":{"type":"geo","items":[{"w":80,"h":32,"seg":[[[0,0],[0,16]],[[0,0],[64,0]],[[0,16],[48,16]],[[48,16],[48,32]],[[48,32],[80,32]],[[64,0],[64,16]],[[64,16],[80,16]],[[80,16],[80,32]]],"dash":[[[16,0],[16,16]],[[32,0],[32,16]],[[48,0],[48,16]],[[48,16],[64,16]],[[64,16],[64,32]]]},{"w":64,"h":48,"seg":[[[0,32],[0,48]],[[0,32],[16,32]],[[0,48],[32,48]],[[16,16],[16,32]],[[16,16],[32,16]],[[32,0],[32,16]],[[32,0],[64,0]],[[32,32],[32,48]],[[32,32],[48,32]],[[48,16],[48,32]],[[48,16],[64,16]],[[64,0],[64,16]]],"dash":[[[16,32],[16,48]],[[16,32],[32,32]],[[32,16],[32,32]],[[32,16],[48,16]],[[48,0],[48,16]]]},{"w":64,"h":48,"seg":[[[0,16],[0,32]],[[0,16],[16,16]],[[0,32],[32,32]],[[16,0],[16,16]],[[16,0],[32,0]],[[32,0],[32,16]],[[32,16],[64,16]],[[32,32],[32,48]],[[32,48],[48,48]],[[48,32],[48,48]],[[48,32],[64,32]],[[64,16],[64,32]]],"dash":[[[16,16],[16,32]],[[16,16],[32,16]],[[32,16],[32,32]],[[32,32],[48,32]],[[48,16],[48,32]]]}],"tag":true},"variant_rule":{"alt":[{"stem":"단원 평가의 그림 가~라예요. 정육면체의 전개도가 될 수 있는 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 나, 라","correct":true},{"t":"가, 다, 라","mis":"M5-2-u5-X14"},{"t":"나, 다, 라","mis":"M5-2-u5-X14"},{"t":"가, 나, 다","mis":"M5-2-u5-X14"}],"explanation":["그림마다 접은 모양을 떠올려요.","겹치는 면이 있거나 만나는 선분의 길이가 다르거나 면이 모자라면 전개도가 아니에요.","정답은 가, 나, 라예요."],"asset":{"type":"geo","items":[{"w":64,"h":48,"seg":[[[0,0],[0,32]],[[0,0],[16,0]],[[0,32],[48,32]],[[16,0],[16,16]],[[16,16],[64,16]],[[48,32],[48,48]],[[48,48],[64,48]],[[64,16],[64,48]]],"dash":[[[0,16],[16,16]],[[16,16],[16,32]],[[32,16],[32,32]],[[48,16],[48,32]],[[48,32],[64,32]]]},{"w":64,"h":48,"seg":[[[0,16],[0,32]],[[0,16],[16,16]],[[0,32],[16,32]],[[16,0],[16,16]],[[16,0],[32,0]],[[16,32],[16,48]],[[16,48],[32,48]],[[32,0],[32,16]],[[32,16],[64,16]],[[32,32],[32,48]],[[32,32],[64,32]],[[64,16],[64,32]]],"dash":[[[16,16],[16,32]],[[16,16],[32,16]],[[16,32],[32,32]],[[32,16],[32,32]],[[48,16],[48,32]]]},{"w":64,"h":48,"seg":[[[0,32],[0,48]],[[0,32],[16,32]],[[0,48],[64,48]],[[16,0],[16,32]],[[16,0],[32,0]],[[32,0],[32,32]],[[32,32],[64,32]],[[64,32],[64,48]]],"dash":[[[16,16],[32,16]],[[16,32],[16,48]],[[16,32],[32,32]],[[32,32],[32,48]],[[48,32],[48,48]]]},{"w":64,"h":48,"seg":[[[0,32],[0,48]],[[0,32],[16,32]],[[0,48],[32,48]],[[16,16],[16,32]],[[16,16],[32,16]],[[32,0],[32,16]],[[32,0],[64,0]],[[32,32],[32,48]],[[32,32],[48,32]],[[48,16],[48,32]],[[48,16],[64,16]],[[64,0],[64,16]]],"dash":[[[16,32],[16,48]],[[16,32],[32,32]],[[32,16],[32,32]],[[32,16],[48,16]],[[48,0],[48,16]]]}],"tag":true}},{"stem":"교과서 117쪽 ⑤의 라·바·나·다를 가~라로 다시 늘어놓았어요. 직육면체의 전개도가 될 수 있는 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"나, 라","correct":true},{"t":"나, 다","mis":"M5-2-u5-X14"},{"t":"다, 라","mis":"M5-2-u5-X14"},{"t":"가, 다","mis":"M5-2-u5-X14"}],"explanation":["그림마다 접은 모양을 떠올려요.","겹치는 면이 있거나 만나는 선분의 길이가 다르거나 면이 모자라면 전개도가 아니에요.","정답은 나, 라예요."],"asset":{"type":"geo","items":[{"w":128,"h":72,"seg":[[[0,24],[0,48]],[[0,24],[40,24]],[[0,48],[104,48]],[[40,0],[40,24]],[[40,0],[64,0]],[[64,0],[64,24]],[[64,24],[128,24]],[[104,48],[104,72]],[[104,72],[128,72]],[[128,24],[128,72]]],"dash":[[[40,24],[40,48]],[[40,24],[64,24]],[[64,24],[64,48]],[[104,24],[104,48]],[[104,48],[128,48]]]},{"w":80,"h":32,"seg":[[[0,0],