INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L06_challenge#10','math',5,2,'u5','L06','tb_g5_2_math_u5_L06_challenge','lesson_challenge','M5-2-u5-C6',4,'essay','teacher','교과서 117쪽 ⑤의 나예요. 친구가 「면이 6개니까 직육면체의 전개도야.」라고 했어요. 친구의 말이 맞는지 판단하고, 전개도가 되려면 무엇을 따져 보아야 하는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u5-C6","difficulty":4,"kind":"essay","stem":"교과서 117쪽 ⑤의 나예요. 친구가 「면이 6개니까 직육면체의 전개도야.」라고 했어요. 친구의 말이 맞는지 판단하고, 전개도가 되려면 무엇을 따져 보아야 하는지 쓰세요.","answer_guide":{"answer":"예: 친구의 말은 틀렸다. 이 그림은 접었을 때 양쪽 위의 두 면이 같은 자리에서 겹치고 한쪽은 비므로 전개도가 아니다. 전개도가 되려면 면의 수뿐 아니라 접었을 때 겹치는 면이 없는지, 만나는 두 선분의 길이가 같은지를 따져 보아야 한다.","scoring_points":["틀렸다고 판단했는가","접었을 때 겹치는 면이 있다고 썼는가","겹치는 면·만나는 선분의 길이를 따져야 한다고 썼는가"]},"explanation":["접은 모양을 떠올려요.","위쪽에 붙은 두 면이 같은 자리에서 겹쳐요.","면의 수뿐 아니라 겹침과 만나는 선분의 길이를 따져요."],"asset":{"type":"geo","items":[{"w":120,"h":60,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[120,60]],[[30,0],[30,30]],[[30,30],[90,30]],[[90,0],[90,30]],[[90,0],[120,0]],[[120,0],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]],[[90,30],[120,30]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L07_basic#1','math',5,2,'u5','L07','tb_g5_2_math_u5_L07_basic','lesson_basic','M5-2-u5-C7',1,'mc','auto','직육면체의 전개도를 그리려면 면을 몇 개 그려야 하나요?',ARRAY['M5-2-u5-X04','M5-2-u5-X14','M5-2-u5-X05']::text[],true,'{"seq":1,"concept":"M5-2-u5-C7","difficulty":1,"kind":"mc","stem":"직육면체의 전개도를 그리려면 면을 몇 개 그려야 하나요?","options":[{"t":"6개","correct":true},{"t":"4개","mis":"M5-2-u5-X04"},{"t":"5개","mis":"M5-2-u5-X14"},{"t":"12개","mis":"M5-2-u5-X05"}],"explanation":["전개도에는 면 6개를 겹치지 않게 이어 그려요.","맞붙는 모서리는 길이가 같게, 마주 보는 면은 모양과 크기가 같게 그려요.","정답은 「6개」예요."],"variant_rule":{"alt":[{"stem":"직육면체의 전개도를 그릴 때 접었을 때 맞붙는 두 모서리는 어떻게 그리나요?","options":[{"t":"길이가 같게 그린다","correct":true},{"t":"한쪽을 더 길게 그린다","mis":"M5-2-u5-X14"},{"t":"둘 다 점선으로 그린다","mis":"M5-2-u5-X16"},{"t":"하나만 그린다","mis":"M5-2-u5-X14"}],"explanation":["전개도에는 면 6개를 겹치지 않게 이어 그려요.","맞붙는 모서리는 길이가 같게, 마주 보는 면은 모양과 크기가 같게 그려요.","정답은 「길이가 같게 그린다」예요."]},{"stem":"직육면체의 전개도를 그릴 때 접었을 때 마주 보는 두 면은 어떻게 그리나요?","options":[{"t":"모양과 크기가 같게 그린다","correct":true},{"t":"크기를 다르게 그린다","mis":"M5-2-u5-X14"},{"t":"하나는 정사각형으로 그린다","mis":"M5-2-u5-X02"},{"t":"바로 붙여서 그린다","mis":"M5-2-u5-X12"}],"explanation":["전개도에는 면 6개를 겹치지 않게 이어 그려요.","맞붙는 모서리는 길이가 같게, 마주 보는 면은 모양과 크기가 같게 그려요.","정답은 「모양과 크기가 같게 그린다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L07_basic#2','math',5,2,'u5','L07','tb_g5_2_math_u5_L07_basic','lesson_basic','M5-2-u5-C7',1,'mc','auto','교과서 119쪽 — 한 모서리가 3 cm인 정육면체의 전개도를 그리려고 해요. 그려야 하는 면은 어느 것인가요?',ARRAY['M5-2-u5-X19','M5-2-u5-X04','M5-2-u5-X14']::text[],true,'{"seq":2,"concept":"M5-2-u5-C7","difficulty":1,"kind":"mc","stem":"교과서 119쪽 — 한 모서리가 3 cm인 정육면체의 전개도를 그리려고 해요. 그려야 하는 면은 어느 것인가요?","options":[{"t":"한 변이 3 cm인 정사각형 6개","correct":true},{"t":"가로 3 cm, 세로 6 cm인 직사각형 6개","mis":"M5-2-u5-X19"},{"t":"한 변이 3 cm인 정사각형 4개","mis":"M5-2-u5-X04"},{"t":"한 변이 3 cm인 정사각형 5개","mis":"M5-2-u5-X14"}],"explanation":["정육면체의 면은 모두 크기가 같은 정사각형이에요.","한 모서리가 3 cm이니 한 변이 3 cm인 정사각형이에요.","면이 6개니 6개를 그려요."],"variant_rule":{"alt":[{"stem":"단원 평가 — 한 모서리가 8 cm인 정육면체의 전개도를 그리려고 해요. 그려야 하는 면은 어느 것인가요?","options":[{"t":"한 변이 8 cm인 정사각형 6개","correct":true},{"t":"가로 8 cm, 세로 16 cm인 직사각형 6개","mis":"M5-2-u5-X19"},{"t":"한 변이 8 cm인 정사각형 4개","mis":"M5-2-u5-X04"},{"t":"한 변이 8 cm인 정사각형 5개","mis":"M5-2-u5-X14"}],"explanation":["정육면체의 면은 모두 크기가 같은 정사각형이에요.","한 모서리가 8 cm이니 한 변이 8 cm인 정사각형이에요.","면이 6개니 6개를 그려요."]},{"stem":"단원 평가의 과자 상자 — 한 모서리가 5 cm인 정육면체의 전개도를 그리려고 해요. 그려야 하는 면은 어느 것인가요?","options":[{"t":"한 변이 5 cm인 정사각형 6개","correct":true},{"t":"가로 5 cm, 세로 10 cm인 직사각형 6개","mis":"M5-2-u5-X19"},{"t":"한 변이 5 cm인 정사각형 4개","mis":"M5-2-u5-X04"},{"t":"한 변이 5 cm인 정사각형 5개","mis":"M5-2-u5-X14"}],"explanation":["정육면체의 면은 모두 크기가 같은 정사각형이에요.","한 모서리가 5 cm이니 한 변이 5 cm인 정사각형이에요.","면이 6개니 6개를 그려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L07_basic#3','math',5,2,'u5','L07','tb_g5_2_math_u5_L07_basic','lesson_basic','M5-2-u5-C7',1,'mc','auto','한 직육면체의 전개도에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u5-X14']::text[],true,'{"seq":3,"concept":"M5-2-u5-C7","difficulty":1,"kind":"mc","stem":"한 직육면체의 전개도에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"자르는 모서리에 따라 여러 가지로 그릴 수 있다","correct":true},{"t":"전개도는 한 가지뿐이다","mis":"M5-2-u5-X14"},{"t":"전개도마다 접은 직육면체의 크기가 다르다","mis":"M5-2-u5-X14"},{"t":"면을 7개 그려도 된다","mis":"M5-2-u5-X14"}],"explanation":["어느 모서리를 자르는지에 따라 펼친 모양이 달라져요.","모양은 달라도 접으면 같은 직육면체가 돼요.","정답은 「자르는 모서리에 따라 여러 가지로 그릴 수 있다」예요."],"variant_rule":{"alt":[{"stem":"같은 상자를 두 친구가 다르게 펼쳤어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"모양은 달라도 접으면 모두 같은 직육면체가 된다","correct":true},{"t":"한 친구는 틀리게 펼쳤다","mis":"M5-2-u5-X14"},{"t":"접으면 서로 다른 직육면체가 된다","mis":"M5-2-u5-X14"},{"t":"면의 수가 서로 다르다","mis":"M5-2-u5-X04"}],"explanation":["어느 모서리를 자르는지에 따라 펼친 모양이 달라져요.","모양은 달라도 접으면 같은 직육면체가 돼요.","정답은 「모양은 달라도 접으면 모두 같은 직육면체가 된다」예요."]},{"stem":"전개도가 여러 가지인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"어느 모서리를 자르는지에 따라 펼친 모양이 달라지기 때문이다","correct":true},{"t":"면의 크기가 바뀌기 때문이다","mis":"M5-2-u5-X14"},{"t":"모서리의 수가 바뀌기 때문이다","mis":"M5-2-u5-X05"},{"t":"잘못 그린 것이 많기 때문이다","mis":"M5-2-u5-X14"}],"explanation":["어느 모서리를 자르는지에 따라 펼친 모양이 달라져요.","모양은 달라도 접으면 같은 직육면체가 돼요.","정답은 「어느 모서리를 자르는지에 따라 펼친 모양이 달라지기 때문이다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L07_basic#4','math',5,2,'u5','L07','tb_g5_2_math_u5_L07_basic','lesson_basic','M5-2-u5-C7',1,'ox','auto','직육면체의 전개도에는 면을 6개 그려요.',ARRAY['M5-2-u5-X04']::text[],true,'{"seq":4,"concept":"M5-2-u5-C7","difficulty":1,"kind":"ox","stem":"직육면체의 전개도에는 면을 6개 그려요.","answer":"O","reason_options":[{"t":"직육면체의 면이 6개이므로","correct":true},{"t":"보이는 면 3개만 그리면 되므로","mis":"M5-2-u5-X04"}],"mis":"M5-2-u5-X04","explanation":["전개도를 그리는 약속을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 O예요.","까닭으로 「직육면체의 면이 6개이므로」를 골라요."],"variant_rule":{"alt":[{"stem":"정육면체의 전개도는 크기가 같은 정사각형 6개로 이루어져요.","answer":"O","reason_options":[{"t":"정육면체의 면은 모두 크기가 같은 정사각형이므로","correct":true},{"t":"정육면체는 면이 4개이므로","mis":"M5-2-u5-X07"}],"explanation":["전개도를 그리는 약속을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 O예요.","까닭으로 「정육면체의 면은 모두 크기가 같은 정사각형이므로」를 골라요."]},{"stem":"전개도에서 접었을 때 맞붙는 두 모서리는 길이가 달라도 돼요.","answer":"X","reason_options":[{"t":"맞붙는 두 모서리는 한 모서리가 되므로 길이가 같아야 하므로","correct":true},{"t":"접으면 길이가 맞춰지므로","mis":"M5-2-u5-X14"}],"explanation":["전개도를 그리는 약속을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「맞붙는 두 모서리는 한 모서리가 되므로 길이가 같아야 하므로」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L07_basic#5','math',5,2,'u5','L07','tb_g5_2_math_u5_L07_basic','lesson_basic','M5-2-u5-C7',2,'mc','auto','가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체(교과서 118쪽)의 전개도에서 옆면 4개만 그렸어요. 빠진 부분은 무엇인가요? 모눈 한 칸은 1 cm예요.',ARRAY['M5-2-u5-X20','M5-2-u5-X14']::text[],true,'{"seq":5,"concept":"M5-2-u5-C7","difficulty":2,"kind":"mc","stem":"가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체(교과서 118쪽)의 전개도에서 옆면 4개만 그렸어요. 빠진 부분은 무엇인가요? 모눈 한 칸은 1 cm예요.","options":[{"t":"가로 3 cm, 세로 2 cm인 직사각형 2개","correct":true},{"t":"가로 3 cm, 세로 5 cm인 직사각형 2개","mis":"M5-2-u5-X20"},{"t":"가로 2 cm, 세로 5 cm인 직사각형 1개","mis":"M5-2-u5-X20"},{"t":"가로 3 cm, 세로 2 cm인 직사각형 1개","mis":"M5-2-u5-X14"}],"explanation":["직육면체의 전개도에는 면 6개가 있어요 — 마주 보는 면은 모양과 크기가 같아요.","이미 그린 면이 직육면체의 어느 면인지 가로·세로·높이로 짝 지어 봐요.","빠진 부분은 「가로 3 cm, 세로 2 cm인 직사각형 2개」예요."],"asset":{"type":"geo","items":[{"w":140,"h":98,"seg":[[[0,0],[0,98]],[[0,0],[140,0]],[[0,98],[42,98]],[[42,70],[42,98]],[[42,70],[140,70]],[[140,0],[140,70]]],"dash":[[[0,70],[42,70]],[[42,0],[42,70]],[[70,0],[70,70]],[[112,0],[112,70]]],"grid":14}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 3 cm, 세로 3 cm, 높이 4 cm인 직육면체(교과서 119쪽)의 전개도에서 정사각형 면 1개와 옆면 1개만 그렸어요. 빠진 부분은 무엇인가요? 모눈 한 칸은 1 cm예요.","options":[{"t":"가로 3 cm, 세로 4 cm인 직사각형 3개와 한 변이 3 cm인 정사각형 1개","correct":true},{"t":"가로 3 cm, 세로 4 cm인 직사각형 4개","mis":"M5-2-u5-X20"},{"t":"한 변이 3 cm인 정사각형 4개","mis":"M5-2-u5-X20"},{"t":"가로 3 cm, 세로 4 cm인 직사각형 3개","mis":"M5-2-u5-X14"}],"explanation":["직육면체의 전개도에는 면 6개가 있어요 — 마주 보는 면은 모양과 크기가 같아요.","이미 그린 면이 직육면체의 어느 면인지 가로·세로·높이로 짝 지어 봐요.","빠진 부분은 「가로 3 cm, 세로 4 cm인 직사각형 3개와 한 변이 3 cm인 정사각형 1개」예요."],"asset":null},{"stem":"가로 4 cm, 세로 1 cm, 높이 3 cm인 직육면체(형성 평가)의 전개도에서 가로 4 cm인 면 3개(4 cm × 1 cm, 4 cm × 3 cm, 4 cm × 1 cm)만 이어 그렸어요. 빠진 부분은 무엇인가요? 모눈 한 칸은 1 cm예요.","options":[{"t":"가로 4 cm, 세로 3 cm인 직사각형 1개와 가로 1 cm, 세로 3 cm인 직사각형 2개","correct":true},{"t":"가로 4 cm, 세로 3 cm인 직사각형 3개","mis":"M5-2-u5-X20"},{"t":"가로 1 cm, 세로 3 cm인 직사각형 2개","mis":"M5-2-u5-X14"},{"t":"가로 4 cm, 세로 1 cm인 직사각형 3개","mis":"M5-2-u5-X20"}],"explanation":["직육면체의 전개도에는 면 6개가 있어요 — 마주 보는 면은 모양과 크기가 같아요.","이미 그린 면이 직육면체의 어느 면인지 가로·세로·높이로 짝 지어 봐요.","빠진 부분은 「가로 4 cm, 세로 3 cm인 직사각형 1개와 가로 1 cm, 세로 3 cm인 직사각형 2개」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L07_basic#6','math',5,2,'u5','L07','tb_g5_2_math_u5_L07_basic','lesson_basic','M5-2-u5-C7',2,'sa','auto','한 모서리가 3 cm인 정육면체의 전개도를 그렸어요. 전개도의 둘레(실선)의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u5-C7","difficulty":2,"kind":"sa","stem":"한 모서리가 3 cm인 정육면체의 전개도를 그렸어요. 전개도의 둘레(실선)의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["전개도의 둘레에는 한 변이 3 cm인 선분이 14개 있어요.","3 × 14 = 42예요.","그래서 42 cm예요."],"mis":"M5-2-u5-X16","asset":{"type":"geo","items":[{"w":64,"h":48,"seg":[[[0,0],[0,48]],[[0,0],[16,0]],[[0,48],[16,48]],[[16,0],[16,16]],[[16,16],[64,16]],[[16,32],[16,48]],[[16,32],[64,32]],[[64,16],[64,32]]],"dash":[[[0,16],[16,16]],[[0,32],[16,32]],[[16,16],[16,32]],[[32,16],[32,32]],[[48,16],[48,32]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"한 모서리가 8 cm인 정육면체의 전개도를 그렸어요. 전개도의 둘레(실선)의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["112"],"explanation":["전개도의 둘레에는 한 변이 8 cm인 선분이 14개 있어요.","8 × 14 = 112예요.","그래서 112 cm예요."],"asset":{"type":"geo","items":[{"w":64,"h":48,"seg":[[[0,0],[0,48]],[[0,0],[16,0]],[[0,48],[16,48]],[[16,0],[16,16]],[[16,16],[64,16]],[[16,32],[16,48]],[[16,32],[64,32]],[[64,16],[64,32]]],"dash":[[[0,16],[16,16]],[[0,32],[16,32]],[[16,16],[16,32]],[[32,16],[32,32]],[[48,16],[48,32]]]}],"tag":false}},{"stem":"한 모서리가 5 cm인 정육면체의 전개도를 그렸어요. 전개도의 둘레(실선)의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["전개도의 둘레에는 한 변이 5 cm인 선분이 14개 있어요.","5 × 14 = 70이에요.","그래서 70 cm예요."],"asset":{"type":"geo","items":[{"w":64,"h":48,"seg":[[[0,0],[0,48]],[[0,0],[16,0]],[[0,48],[16,48]],[[16,0],[16,16]],[[16,16],[64,16]],[[16,32],[16,48]],[[16,32],[64,32]],[[64,16],[64,32]]],"dash":[[[0,16],[16,16]],[[0,32],[16,32]],[[16,16],[16,32]],[[32,16],[32,32]],[[48,16],[48,32]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L07_basic#7','math',5,2,'u5','L07','tb_g5_2_math_u5_L07_basic','lesson_basic','M5-2-u5-C7',2,'mc','auto','잘못 그린 전개도예요. 어떻게 고치면 직육면체의 전개도가 되나요?',ARRAY['M5-2-u5-X14','M5-2-u5-X16']::text[],true,'{"seq":7,"concept":"M5-2-u5-C7","difficulty":2,"kind":"mc","stem":"잘못 그린 전개도예요. 어떻게 고치면 직육면체의 전개도가 되나요?","options":[{"t":"겹치는 두 면 가운데 한 면을 반대쪽으로 옮긴다","correct":true},{"t":"면을 하나 더 그린다","mis":"M5-2-u5-X14"},{"t":"모든 점선을 실선으로 바꾼다","mis":"M5-2-u5-X16"},{"t":"한 줄의 면을 모두 지운다","mis":"M5-2-u5-X14"}],"explanation":["같은 쪽에 붙은 두 면은 접으면 같은 자리에서 겹쳐요.","한 면을 반대쪽으로 옮기면 비어 있던 자리를 채워요.","그러면 면 6개가 직육면체를 둘러싸요."],"asset":{"type":"geo","items":[{"w":192,"h":80,"seg":[[[0,0],[0,80]],[[0,0],[192,0]],[[0,80],[48,80]],[[48,32],[48,80]],[[48,32],[96,32]],[[96,32],[96,80]],[[96,80],[144,80]],[[144,32],[144,80]],[[144,32],[192,32]],[[192,0],[192,32]]],"dash":[[[0,32],[48,32]],[[48,0],[48,32]],[[96,0],[96,32]],[[96,32],[144,32]],[[144,0],[144,32]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 잘못 그린 전개도예요. 어떻게 고치면 직육면체의 전개도가 되나요?","options":[{"t":"겹치는 두 면 가운데 한 면을 반대쪽으로 옮긴다","correct":true},{"t":"면을 하나 더 그린다","mis":"M5-2-u5-X14"},{"t":"모든 점선을 실선으로 바꾼다","mis":"M5-2-u5-X16"},{"t":"한 줄의 면을 모두 지운다","mis":"M5-2-u5-X14"}],"explanation":["같은 쪽에 붙은 두 면은 접으면 같은 자리에서 겹쳐요.","한 면을 반대쪽으로 옮기면 비어 있던 자리를 채워요.","그러면 면 6개가 직육면체를 둘러싸요."],"asset":{"type":"geo","items":[{"w":170,"h":136,"seg":[[[0,0],[0,85]],[[0,0],[170,0]],[[0,85],[51,85]],[[51,85],[51,136]],[[51,136],[85,136]],[[85,85],[85,136]],[[85,85],[136,85]],[[136,85],[136,136]],[[136,136],[170,136]],[[170,0],[170,136]]],"dash":[[[51,0],[51,85]],[[51,85],[85,85]],[[85,0],[85,85]],[[136,0],[136,85]],[[136,85],[170,85]]]}],"tag":false}},{"stem":"이번에는 다른 보기예요. 잘못 그린 전개도예요. 어떻게 고치면 직육면체의 전개도가 되나요?","options":[{"t":"겹치는 두 면 가운데 한 면을 반대쪽으로 옮긴다","correct":true},{"t":"면을 하나 더 그린다","mis":"M5-2-u5-X14"},{"t":"모든 점선을 실선으로 바꾼다","mis":"M5-2-u5-X16"},{"t":"한 줄의 면을 모두 지운다","mis":"M5-2-u5-X14"}],"explanation":["같은 쪽에 붙은 두 면은 접으면 같은 자리에서 겹쳐요.","한 면을 반대쪽으로 옮기면 비어 있던 자리를 채워요.","그러면 면 6개가 직육면체를 둘러싸요."],"asset":{"type":"geo","items":[{"w":192,"h":84,"seg":[[[0,0],[0,84]],[[0,0],[60,0]],[[0,84],[192,84]],[[60,0],[60,36]],[[60,36],[96,36]],[[96,0],[96,36]],[[96,0],[156,0]],[[156,0],[156,36]],[[156,36],[192,36]],[[192,36],[192,84]]],"dash":[[[0,36],[60,36]],[[60,36],[60,84]],[[96,36],[96,84]],[[96,36],[156,36]],[[156,36],[156,84]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L07_basic#8','math',5,2,'u5','L07','tb_g5_2_math_u5_L07_basic','lesson_basic','M5-2-u5-C7',2,'error','auto','친구들이 직육면체의 전개도를 그리며 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-2-u5-X14','M5-2-u5-X16']::text[],true,'{"seq":8,"concept":"M5-2-u5-C7","difficulty":2,"kind":"error","stem":"친구들이 직육면체의 전개도를 그리며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"달곰 — 「전개도에서 마주 보는 두 면은 크기가 달라도 돼.」","correct":true,"mis_target":"M5-2-u5-X14"},{"t":"여울 — 「접었을 때 맞붙는 모서리는 길이가 같게 그려.」","mis":"M5-2-u5-X14"},{"t":"순달 — 「잘리지 않은 모서리는 점선으로 그려.」","mis":"M5-2-u5-X16"}],"explanation":["면 6개를 겹치지 않게, 맞붙는 모서리는 같은 길이로, 마주 보는 면은 같은 모양과 크기로 그려요.","잘린 모서리는 실선, 잘리지 않은 모서리는 점선이에요.","달곰의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 직육면체의 전개도를 그리며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지우 — 「잘린 모서리는 점선으로 그려.」","correct":true,"mis_target":"M5-2-u5-X16"},{"t":"윤수 — 「면 6개를 겹치지 않게 이어 그려.」","mis":"M5-2-u5-X14"},{"t":"서연 — 「자르는 모서리에 따라 전개도는 여러 가지야.」","mis":"M5-2-u5-X14"}],"explanation":["면 6개를 겹치지 않게, 맞붙는 모서리는 같은 길이로, 마주 보는 면은 같은 모양과 크기로 그려요.","잘린 모서리는 실선, 잘리지 않은 모서리는 점선이에요.","지우의 말이 틀렸어요."]},{"stem":"이번에는 다른 보기예요. 친구들이 직육면체의 전개도를 그리며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 「한 직육면체의 전개도는 한 가지뿐이야.」","correct":true,"mis_target":"M5-2-u5-X14"},{"t":"지우 — 「정육면체의 전개도는 크기가 같은 정사각형 6개야.」","mis":"M5-2-u5-X07"},{"t":"윤수 — 「마주 보는 면은 모양과 크기가 같게 그려.」","mis":"M5-2-u5-X14"}],"explanation":["면 6개를 겹치지 않게, 맞붙는 모서리는 같은 길이로, 마주 보는 면은 같은 모양과 크기로 그려요.","잘린 모서리는 실선, 잘리지 않은 모서리는 점선이에요.","태민의 말이 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L07_basic#9','math',5,2,'u5','L07','tb_g5_2_math_u5_L07_basic','lesson_basic','M5-2-u5-C7',2,'sa','auto','교과서 120~121쪽 「짜잔! 나만의 전개도」예요. 「똑똑! 수학 탐험대」에서 전개도의 한 면에 ★를 표시했어요. 전개도를 접었을 때 ★로 표시한 면과 수직인 면에 모두 표시하면 몇 개의 면에 표시하게 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u5-C7","difficulty":2,"kind":"sa","stem":"교과서 120~121쪽 「짜잔! 나만의 전개도」예요. 「똑똑! 수학 탐험대」에서 전개도의 한 면에 ★를 표시했어요. 전개도를 접었을 때 ★로 표시한 면과 수직인 면에 모두 표시하면 몇 개의 면에 표시하게 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["직육면체의 전개도를 접으면 면 6개·모서리 12개가 돼요.","★ 면과 평행한 면 하나를 빼면 6 − 2 = 4(개)예요.","그래서 4예요."],"mis":"M5-2-u5-X13","asset":{"type":"geo","items":[{"w":144,"h":132,"poly":[[[0,48],[24,48],[24,84],[0,84]]],"seg":[[[0,48],[0,84]],[[0,48],[72,48]],[[0,84],[72,84]],[[72,0],[72,48]],[[72,0],[96,0]],[[72,84],[72,132]],[[72,132],[96,132]],[[96,0],[96,48]],[[96,48],[144,48]],[[96,84],[96,132]],[[96,84],[144,84]],[[144,48],[144,84]]],"dash":[[[24,48],[24,84]],[[72,48],[72,84]],[[72,48],[96,48]],[[72,84],[96,84]],[[96,48],[96,84]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"교과서 120~121쪽 「짜잔! 나만의 전개도」예요. 「꾸미기 모드」에서 전개도를 접었을 때 서로 평행한 면을 같은 색으로 칠하려고 해요. 색은 모두 몇 가지가 필요한가요? 숫자로 쓰세요.","answer":["3"],"explanation":["직육면체의 전개도를 접으면 면 6개·모서리 12개가 돼요.","평행한 면이 3쌍이니 한 쌍에 한 가지씩 3가지예요.","그래서 3이에요."],"asset":{"type":"geo","items":[{"w":144,"h":132,"poly":[[[0,48],[24,48],[24,84],[0,84]]],"seg":[[[0,48],[0,84]],[[0,48],[72,48]],[[0,84],[72,84]],[[72,0],[72,48]],[[72,0],[96,0]],[[72,84],[72,132]],[[72,132],[96,132]],[[96,0],[96,48]],[[96,48],[144,48]],[[96,84],[96,132]],[[96,84],[144,84]],[[144,48],[144,84]]],"dash":[[[24,48],[24,84]],[[72,48],[72,84]],[[72,48],[96,48]],[[72,84],[96,84]],[[96,48],[96,84]]]}],"tag":false}},{"stem":"교과서 120~121쪽 「짜잔! 나만의 전개도」예요. 전개도를 접었을 때 서로 만나는 선분(잘린 모서리)을 같은 색으로 칠하려고 해요. 같은 색으로 칠할 선분 쌍은 모두 몇 쌍인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["직육면체의 전개도를 접으면 면 6개·모서리 12개가 돼요.","모서리 12개 가운데 점선(잘리지 않은 모서리) 5개를 빼면 12 − 5 = 7(쌍)이에요.","그래서 7이에요."],"asset":{"type":"geo","items":[{"w":144,"h":132,"poly":[[[0,48],[24,48],[24,84],[0,84]]],"seg":[[[0,48],[0,84]],[[0,48],[72,48]],[[0,84],[72,84]],[[72,0],[72,48]],[[72,0],[96,0]],[[72,84],[72,132]],[[72,132],[96,132]],[[96,0],[96,48]],[[96,48],[144,48]],[[96,84],[96,132]],[[96,84],[144,84]],[[144,48],[144,84]]],"dash":[[[24,48],[24,84]],[[72,48],[72,84]],[[72,48],[96,48]],[[72,84],[96,84]],[[96,48],[96,84]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L07_basic#10','math',5,2,'u5','L07','tb_g5_2_math_u5_L07_basic','lesson_basic','M5-2-u5-C7',3,'mc','auto','밑면이 한 변 3 cm인 정사각형이고 높이가 2 cm인 직육면체의 전개도를 바르게 그린 것은 어느 것인가요? 모눈 한 칸은 1 cm예요.',ARRAY['M5-2-u5-X14']::text[],true,'{"seq":10,"concept":"M5-2-u5-C7","difficulty":3,"kind":"mc","stem":"밑면이 한 변 3 cm인 정사각형이고 높이가 2 cm인 직육면체의 전개도를 바르게 그린 것은 어느 것인가요? 모눈 한 칸은 1 cm예요.","options":[{"t":"나","correct":true},{"t":"가","mis":"M5-2-u5-X14"},{"t":"다","mis":"M5-2-u5-X14"},{"t":"라","mis":"M5-2-u5-X14"}],"explanation":["정사각형 밑면 2개와 가로 3 cm, 세로 2 cm인 옆면 4개가 있어야 해요.","겹치는 면이 없고 맞붙는 선분의 길이가 같아야 해요.","그래서 나예요."],"asset":{"type":"geo","items":[{"w":120,"h":50,"seg":[[[0,0],[0,50]],[[0,0],[30,0]],[[0,50],[120,50]],[[30,0],[30,30]],[[30,30],[60,30]],[[60,0],[60,30]],[[60,0],[90,0]],[[90,0],[90,30]],[[90,30],[120,30]],[[120,30],[120,50]]],"dash":[[[0,30],[30,30]],[[30,30],[30,50]],[[60,30],[60,50]],[[60,30],[90,30]],[[90,30],[90,50]]],"grid":10},{"w":120,"h":80,"seg":[[[0,0],[0,50]],[[0,0],[30,0]],[[0,50],[60,50]],[[30,0],[30,30]],[[30,30],[120,30]],[[60,50],[60,80]],[[60,80],[90,80]],[[90,50],[90,80]],[[90,50],[120,50]],[[120,30],[120,50]]],"dash":[[[0,30],[30,30]],[[30,30],[30,50]],[[60,30],[60,50]],[[60,50],[90,50]],[[90,30],[90,50]]],"grid":10},{"w":120,"h":70,"seg":[[[0,0],[0,40]],[[0,0],[30,0]],[[0,40],[60,40]],[[30,0],[30,20]],[[30,20],[120,20]],[[60,40],[60,70]],[[60,70],[90,70]],[[90,40],[90,70]],[[90,40],[120,40]],[[120,20],[120,40]]],"dash":[[[0,20],[30,20]],[[30,20],[30,40]],[[60,20],[60,40]],[[60,40],[90,40]],[[90,20],[90,40]]],"grid":10},{"w":120,"h":50,"seg":[[[0,0],[0,20]],[[0,0],[120,0]],[[0,20],[90,20]],[[90,20],[90,50]],[[90,50],[120,50]],[[120,0],[120,50]]],"dash":[[[30,0],[30,20]],[[60,0],[60,20]],[[90,0],[90,20]],[[90,20],[120,20]]],"grid":10}],"tag":true},"variant_rule":{"alt":[{"stem":"밑면이 한 변 3 cm인 정사각형이고 높이가 4 cm인 직육면체의 전개도를 바르게 그린 것은 어느 것인가요? 모눈 한 칸은 1 cm예요.","options":[{"t":"라","correct":true},{"t":"가","mis":"M5-2-u5-X14"},{"t":"나","mis":"M5-2-u5-X14"},{"t":"다","mis":"M5-2-u5-X14"}],"explanation":["정사각형 밑면 2개와 가로 3 cm, 세로 4 cm인 옆면 4개가 있어야 해요.","겹치는 면이 없고 맞붙는 선분의 길이가 같아야 해요.","그래서 라예요."],"asset":{"type":"geo","items":[{"w":120,"h":70,"seg":[[[0,0],[0,70]],[[0,0],[30,0]],[[0,70],[120,70]],[[30,0],[30,30]],[[30,30],[60,30]],[[60,0],[60,30]],[[60,0],[90,0]],[[90,0],[90,30]],[[90,30],[120,30]],[[120,30],[120,70]]],"dash":[[[0,30],[30,30]],[[30,30],[30,70]],[[60,30],[60,70]],[[60,30],[90,30]],[[90,30],[90,70]]],"grid":10},{"w":120,"h":110,"seg":[[[0,0],[0,80]],[[0,0],[30,0]],[[0,80],[60,80]],[[30,0],[30,40]],[[30,40],[120,40]],[[60,80],[60,110]],[[60,110],[90,110]],[[90,80],[90,110]],[[90,80],[120,80]],[[120,40],[120,80]]],"dash":[[[0,40],[30,40]],[[30,40],[30,80]],[[60,40],[60,80]],[[60,80],[90,80]],[[90,40],[90,80]]],"grid":10},{"w":120,"h":70,"seg":[[[0,0],[0,40]],[[0,0],[120,0]],[[0,40],[90,40]],[[90,40],[90,70]],[[90,70],[120,70]],[[120,0],[120,70]]],"dash":[[[30,0],[30,40]],[[60,0],[60,40]],[[90,0],[90,40]],[[90,40],[120,40]]],"grid":10},{"w":120,"h":100,"seg":[[[0,0],[0,70]],[[0,0],[30,0]],[[0,70],[30,70]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,70],[30,100]],[[30,100],[60,100]],[[60,70],[60,100]],[[60,70],[120,70]],[[120,30],[120,70]]],"dash":[[[0,30],[30,30]],[[30,30],[30,70]],[[30,70],[60,70]],[[60,30],[60,70]],[[90,30],[90,70]]],"grid":10}],"tag":true}},{"stem":"밑면이 한 변 3 cm인 정사각형이고 높이가 3 cm인 직육면체의 전개도를 바르게 그린 것은 어느 것인가요? 모눈 한 칸은 1 cm예요.","options":[{"t":"가","correct":true},{"t":"나","mis":"M5-2-u5-X14"},{"t":"다","mis":"M5-2-u5-X14"},{"t":"라","mis":"M5-2-u5-X14"}],"explanation":["정사각형 밑면 2개와 가로 3 cm, 세로 3 cm인 옆면 4개가 있어야 해요.","겹치는 면이 없고 맞붙는 선분의 길이가 같아야 해요.","그래서 가예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[90,60]],[[30,0],[30,30]],[[30,30],[120,30]],[[90,60],[