INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L07_challenge#1','math',5,2,'u5','L07','tb_g5_2_math_u5_L07_challenge','lesson_challenge','M5-2-u5-C7',2,'ox','auto','한 직육면체의 전개도는 한 가지로만 그릴 수 있어요.',ARRAY['M5-2-u5-X14']::text[],true,'{"seq":1,"concept":"M5-2-u5-C7","difficulty":2,"kind":"ox","stem":"한 직육면체의 전개도는 한 가지로만 그릴 수 있어요.","answer":"X","reason_options":[{"t":"자르는 모서리에 따라 여러 가지로 그릴 수 있으므로","correct":true},{"t":"직육면체 모양이 하나이므로","mis":"M5-2-u5-X14"}],"mis":"M5-2-u5-X14","explanation":["전개도를 그리는 약속을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「자르는 모서리에 따라 여러 가지로 그릴 수 있으므로」를 골라요."],"variant_rule":{"alt":[{"stem":"전개도에서 접었을 때 맞붙는 두 모서리는 길이가 달라도 돼요.","answer":"X","reason_options":[{"t":"맞붙는 두 모서리는 한 모서리가 되므로 길이가 같아야 하므로","correct":true},{"t":"접으면 길이가 맞춰지므로","mis":"M5-2-u5-X14"}],"explanation":["전개도를 그리는 약속을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「맞붙는 두 모서리는 한 모서리가 되므로 길이가 같아야 하므로」를 골라요."]},{"stem":"직육면체의 전개도에는 면을 6개 그려요.","answer":"O","reason_options":[{"t":"직육면체의 면이 6개이므로","correct":true},{"t":"보이는 면 3개만 그리면 되므로","mis":"M5-2-u5-X04"}],"explanation":["전개도를 그리는 약속을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 O예요.","까닭으로 「직육면체의 면이 6개이므로」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
