INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L07_challenge#3','math',5,2,'u5','L07','tb_g5_2_math_u5_L07_challenge','lesson_challenge','M5-2-u5-C7',3,'sa','auto','모눈 한 칸이 1 cm인 모눈종이에 그린 직육면체의 전개도예요(단원 평가에 나온 직육면체). 이 전개도를 접어 만든 직육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u5-C7","difficulty":3,"kind":"sa","stem":"모눈 한 칸이 1 cm인 모눈종이에 그린 직육면체의 전개도예요(단원 평가에 나온 직육면체). 이 전개도를 접어 만든 직육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["모눈을 세면 가로 2 cm, 세로 3 cm, 높이 3 cm인 직육면체예요.","2 × 4 + 3 × 4 + 3 × 4 = 32예요.","그래서 32 cm예요."],"mis":"M5-2-u5-X20","asset":{"type":"geo","items":[{"w":120,"h":108,"seg":[[[0,0],[0,72]],[[0,0],[24,0]],[[0,72],[60,72]],[[24,0],[24,36]],[[24,36],[120,36]],[[60,72],[60,108]],[[60,108],[84,108]],[[84,72],[84,108]],[[84,72],[120,72]],[[120,36],[120,72]]],"dash":[[[0,36],[24,36]],[[24,36],[24,72]],[[60,36],[60,72]],[[60,72],[84,72]],[[84,36],[84,72]]],"grid":12}],"tag":false},"variant_rule":{"alt":[{"stem":"모눈 한 칸이 1 cm인 모눈종이에 그린 직육면체의 전개도예요(형성 평가에 나온 직육면체). 이 전개도를 접어 만든 직육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["모눈을 세면 가로 2 cm, 세로 3 cm, 높이 4 cm인 직육면체예요.","2 × 4 + 3 × 4 + 4 × 4 = 36이에요.","그래서 36 cm예요."],"asset":{"type":"geo","items":[{"w":120,"h":120,"seg":[[[0,0],[0,84]],[[0,0],[24,0]],[[0,84],[60,84]],[[24,0],[24,36]],[[24,36],[120,36]],[[60,84],[60,120]],[[60,120],[84,120]],[[84,84],[84,120]],[[84,84],[120,84]],[[120,36],[120,84]]],"dash":[[[0,36],[24,36]],[[24,36],[24,84]],[[60,36],[60,84]],[[60,84],[84,84]],[[84,36],[84,84]]],"grid":12}],"tag":false}},{"stem":"모눈 한 칸이 1 cm인 모눈종이에 그린 직육면체의 전개도예요(문제로 마무리 8번에 나온 직육면체). 이 전개도를 접어 만든 직육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["모눈을 세면 가로 5 cm, 세로 3 cm, 높이 4 cm인 직육면체예요.","5 × 4 + 3 × 4 + 4 × 4 = 48이에요.","그래서 48 cm예요."],"asset":{"