INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L07_challenge#4','math',5,2,'u5','L07','tb_g5_2_math_u5_L07_challenge','lesson_challenge','M5-2-u5-C7',3,'mc','auto','밑면이 한 변 3 cm인 정사각형이고 높이가 2 cm인 직육면체의 전개도를 바르게 그린 것은 어느 것인가요? 모눈 한 칸은 1 cm예요.',ARRAY['M5-2-u5-X14']::text[],true,'{"seq":4,"concept":"M5-2-u5-C7","difficulty":3,"kind":"mc","stem":"밑면이 한 변 3 cm인 정사각형이고 높이가 2 cm인 직육면체의 전개도를 바르게 그린 것은 어느 것인가요? 모눈 한 칸은 1 cm예요.","options":[{"t":"다","correct":true},{"t":"가","mis":"M5-2-u5-X14"},{"t":"나","mis":"M5-2-u5-X14"},{"t":"라","mis":"M5-2-u5-X14"}],"explanation":["정사각형 밑면 2개와 가로 3 cm, 세로 2 cm인 옆면 4개가 있어야 해요.","겹치는 면이 없고 맞붙는 선분의 길이가 같아야 해요.","그래서 다예요."],"asset":{"type":"geo","items":[{"w":120,"h":50,"seg":[[[0,0],[0,50]],[[0,0],[30,0]],[[0,50],[120,50]],[[30,0],[30,30]],[[30,30],[60,30]],[[60,0],[60,30]],[[60,0],[90,0]],[[90,0],[90,30]],[[90,30],[120,30]],[[120,30],[120,50]]],"dash":[[[0,30],[30,30]],[[30,30],[30,50]],[[60,30],[60,50]],[[60,30],[90,30]],[[90,30],[90,50]]],"grid":10},{"w":120,"h":70,"seg":[[[0,0],[0,40]],[[0,0],[30,0]],[[0,40],[60,40]],[[30,0],[30,20]],[[30,20],[120,20]],[[60,40],[60,70]],[[60,70],[90,70]],[[90,40],[90,70]],[[90,40],[120,40]],[[120,20],[120,40]]],"dash":[[[0,20],[30,20]],[[30,20],[30,40]],[[60,20],[60,40]],[[60,40],[90,40]],[[90,20],[90,40]]],"grid":10},{"w":120,"h":80,"seg":[[[0,0],[0,50]],[[0,0],[30,0]],[[0,50],[30,50]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,50],[30,80]],[[30,80],[60,80]],[[60,50],[60,80]],[[60,50],[120,50]],[[120,30],[120,50]]],"dash":[[[0,30],[30,30]],[[30,30],[30,50]],[[30,50],[60,50]],[[60,30],[60,50]],[[90,30],[90,50]]],"grid":10},{"w":120,"h":50,"seg":[[[0,0],[0,20]],[[0,0],[120,0]],[[0,20],[90,20]],[[90,20],[90,50]],[[90,50],[120,50]],[[120,0],[120,50]]],"dash":[[[30,0],[30,20]],[[60,0],[60,20]],[[90,0],[90,20]],[[90,20],[120,20]]],"grid":10}],"tag":true},"variant_rule":{"alt":[{"stem":"밑면이 한 변 3 cm인 정사각형이고 높이가 4 cm인 직육면체의 전개도를 바르게 그린 것은 어느 것인가요? 모눈 한 칸은 1 cm예요.","options":[{"t":"가","correct":true},{"t":"나","mis":"M5-2-u5-X14"},{"t":"다","mis":"M5-2-u5-X14"},{"t":"라","mis":"M5-2-u5-X14"}],"explanation":["정사각형 밑면 2개와 가로 3 cm, 세로 4 cm인 옆면 4개가 있어야 해요.","겹치는 면이 없고 맞붙는 선분의 길이가 같아야 해요.","그래서 가예요."],"asset":{"type":"geo","items":[{"w":120,"h":100,"seg":[[[0,0],[0,70]],[[0,0],[30,0]],[[0,70],[90,70]],[[30,0],[30,30]],[[30,30],[120,30]],[[90,70],[90,100]],[[90,100],[120,100]],[[120,30],[120,100]]],"dash":[[[0,30],[30,30]],[[30,30],[30,70]],[[60,30],[60,70]],[[90,30],[90,70]],[[90,70],[120,70]]],"grid":10},{"w":120,"h":70,"seg":[[[0,0],[0,70]],[[0,0],[30,0]],[[0,70],[120,70]],[[30,0],[30,30]],[[30,30],[60,30]],[[60,0],[60,30]],[[60,0],[90,0]],[[90,0],[90,30]],[[90,30],[120,30]],[[120,30],[120,70]]],"dash":[[[0,30],[30,30]],[[30,30],[30,70]],[[60,30],[60,70]],[[60,30],[90,30]],[[90,30],[90,70]]],"grid":10},{"w":120,"h":110,"seg":[[[0,0],[0,80]],[[0,0],[30,0]],[[0,80],[60,80]],[[30,0],[30,40]],[[30,40],[120,40]],[[60,80],[60,110]],[[60,110],[90,110]],[[90,80],[90,110]],[[90,80],[120,80]],[[120,40],[120,80]]],"dash":[[[0,40],[30,40]],[[30,40],[30,80]],[[60,40],[60,80]],[[60,80],[90,80]],[[90,40],[90,80]]],"grid":10},{"w":120,"h":70,"seg":[[[0,0],[0,40]],[[0,0],[120,0]],[[0,40],[90,40]],[[90,40],[90,70]],[[90,70],[120,70]],[[120,0],[120,70]]],"dash":[[[30,0],[30,40]],[[60,0],[60,40]],[[90,0],[90,40]],[[90,40],[120,40]]],"grid":10}],"tag":true}},{"stem":"밑면이 한 변 3 cm인 정사각형이고 높이가 3 cm인 직육면체의 전개도를 바르게 그린 것은 어느 것인가요? 모눈 한 칸은 1 cm예요.","options":[{"t":"라","correct":true},{"t":"가","mis":"M5-2-u5-X14"},{"t":"나","mis":"M5-2-u5-X14"},{"t":"다","mis":"M5-2-u5-X14"}],"explanation":["정사각형 밑면 2개와 가로 3 cm, 세로 3 cm인 옆면 4개가 있어야 해요.","겹치는 면이 없고 맞붙는 선분의 길이가 같아야 해요.","그래서 라예요."],"asset":{"type":"geo","items":[{"w":120,"h":60,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[120,60]],[[30,0],[30,30]],[[30,30],[60,30]],[[60,0],[60,30]],[[60,0],[90,0]],[[90,0],[90,30]],[[90,30],[120,30]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[60,30],[60,60]],[[60,30],[90,30]],[[90,30],[90,60]]],"grid":10},{"w":120,"h":100,"seg":[[[0,0],[0,70]],[[0,0],[30,0]],[[0,70],[60,70]],[[30,0],[30,40]],[[30,40],[120,40]],[[60,70],[60,100]],[[60,100],[90,100]],[[90,70],[90,100]],[[90,70],[120,70]],[[120,40],[120,70]]],"dash":[[[0,40],[30,40]],[[30,40],[30,70]],[[60,40],[60,70]],[[60,70],[90,70]],[[90,40],[90,70]]],"grid":10},{"w":120,"h":60,"seg":[[[0,0],[0,30]],[[0,0],[120,0]],[[0,30],[90,30]],[[90,30],[90,60]],[[90,60],[120,60]],[[120,0],[120,60]]],"dash":[[[30,0],[30,30]],[[60,0],[60,30]],[[90,0],[90,30]],[[90,30],[120,30]]],"grid":10},{"w":120,"h":90,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[60,60]],[[30,0],[30,30]],[[30,30],[120,30]],[[60,60],[60,90]],[[60,90],[90,90]],[[90,60],[90,90]],[[90,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,30],[90,60]]],"grid":10}],"tag":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L07_challenge#5','math',5,2,'u5','L07','tb_g5_2_math_u5_L07_challenge','lesson_challenge','M5-2-u5-C7',3,'sa','auto','가로 5 cm, 세로 7 cm, 높이 8 cm인 직육면체를 보고 전개도를 그렸어요(단원 평가). 옆면 4개를 한 줄로 이었을 때, 그 줄의 긴 쪽 길이 ㉠은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u5-C7","difficulty":3,"kind":"sa","stem":"가로 5 cm, 세로 7 cm, 높이 8 cm인 직육면체를 보고 전개도를 그렸어요(단원 평가). 옆면 4개를 한 줄로 이었을 때, 그 줄의 긴 쪽 길이 ㉠은 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["옆면 4개의 가로는 5, 7, 5, 7 cm예요.","5 + 7 + 5 + 7 = 24예요.","그래서 24 cm예요."],"mis":"M5-2-u5-X20","asset":{"type":"geo","items":[{"w":144.5,"h":195.5,"pts":{"ㄱ":[59.5,0,"nw"],"ㄹ":[144.5,0,"ne"],"ㄴ":[0,59.5,"w"],"ㄷ":[85,59.5,"sw"],"ㅁ":[59.5,136,"ne"],"ㅇ":[144.5,136,"e"],"ㅂ":[0,195.5,"sw"],"ㅅ":[85,195.5,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[42.5,203.5],"5 cm"],[[130.75,169.75],"7 cm"],[[67,127.5],"8 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 5 cm, 세로 7 cm, 높이 8 cm인 직육면체를 보고 전개도를 그렸어요(단원 평가). 옆면의 세로 ㉡은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["옆면의 세로는 직육면체의 높이예요.","높이가 8 cm이니 ㉡ = 8이에요.","그래서 8 cm예요."],"asset":{"type":"geo","items":[{"w":144.5,"h":195.5,"pts":{"ㄱ":[59.5,0,"nw"],"ㄹ":[144.5,0,"ne"],"ㄴ":[0,59.5,"w"],"ㄷ":[85,59.5,"sw"],"ㅁ":[59.5,136,"ne"],"ㅇ":[144.5,136,"e"],"ㅂ":[0,195.5,"sw"],"ㅅ":[85,195.5,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[42.5,203.5],"5 cm"],[[130.75,169.75],"7 cm"],[[67,127.5],"8 cm"]]}],"tag":false}},{"stem":"가로 3 cm, 세로 6 cm, 높이 5 cm인 직육면체의 모서리를 잘라 전개도를 만들었어요(단원 평가). 옆면 4개를 한 줄로 이었을 때, 그 줄의 긴 쪽 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["옆면 4개의 가로는 3, 6, 3, 6 cm예요.","3 + 6 + 3 + 6 = 18이에요.","그래서 18 cm예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":176.0,"pts":{"ㄱ":[66.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,66.0,"w"],"ㄷ":[66,66.0,"sw"],"ㅁ":[66.0,110,"ne"],"ㅇ":[132.0,110,"e"],"ㅂ":[0,176.0,"sw"],"ㅅ":[66,176.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33.0,184.0],"3 cm"],[[115.0,147.0],"6 cm"],[[48,121.0],"5 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L07_challenge#6','math',5,2,'u5','L07','tb_g5_2_math_u5_L07_challenge','lesson_challenge','M5-2-u5-C7',3,'error','auto','친구들이 직육면체의 전개도를 그리며 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-2-u5-X16','M5-2-u5-X14']::text[],true,'{"seq":6,"concept":"M5-2-u5-C7","difficulty":3,"kind":"error","stem":"친구들이 직육면체의 전개도를 그리며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"연희 — 「잘린 모서리는 점선으로 그려.」","correct":true,"mis_target":"M5-2-u5-X16"},{"t":"세영 — 「면 6개를 겹치지 않게 이어 그려.」","mis":"M5-2-u5-X14"},{"t":"민지 — 「자르는 모서리에 따라 전개도는 여러 가지야.」","mis":"M5-2-u5-X14"}],"explanation":["면 6개를 겹치지 않게, 맞붙는 모서리는 같은 길이로, 마주 보는 면은 같은 모양과 크기로 그려요.","잘린 모서리는 실선, 잘리지 않은 모서리는 점선이에요.","연희의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 직육면체의 전개도를 그리며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"달곰 — 「한 직육면체의 전개도는 한 가지뿐이야.」","correct":true,"mis_target":"M5-2-u5-X14"},{"t":"여울 — 「정육면체의 전개도는 크기가 같은 정사각형 6개야.」","mis":"M5-2-u5-X07"},{"t":"순달 — 「마주 보는 면은 모양과 크기가 같게 그려.」","mis":"M5-2-u5-X14"}],"explanation":["면 6개를 겹치지 않게, 맞붙는 모서리는 같은 길이로, 마주 보는 면은 같은 모양과 크기로 그려요.","잘린 모서리는 실선, 잘리지 않은 모서리는 점선이에요.","달곰의 말이 틀렸어요."]},{"stem":"이번에는 다른 보기예요. 친구들이 직육면체의 전개도를 그리며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지우 — 「전개도에서 마주 보는 두 면은 크기가 달라도 돼.」","correct":true,"mis_target":"M5-2-u5-X14"},{"t":"윤수 — 「접었을 때 맞붙는 모서리는 길이가 같게 그려.」","mis":"M5-2-u5-X14"},{"t":"서연 — 「잘리지 않은 모서리는 점선으로 그려.」","mis":"M5-2-u5-X16"}],"explanation":["면 6개를 겹치지 않게, 맞붙는 모서리는 같은 길이로, 마주 보는 면은 같은 모양과 크기로 그려요.","잘린 모서리는 실선, 잘리지 않은 모서리는 점선이에요.","지우의 말이 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L07_challenge#7','math',5,2,'u5','L07','tb_g5_2_math_u5_L07_challenge','lesson_challenge','M5-2-u5-C7',3,'sa','auto','한 모서리가 3 cm인 정육면체의 전개도를 그렸어요. 잘리지 않은 모서리(점선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u5-C7","difficulty":3,"kind":"sa","stem":"한 모서리가 3 cm인 정육면체의 전개도를 그렸어요. 잘리지 않은 모서리(점선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["면 6개를 잇는 점선은 5개예요.","3 × 5 = 15예요.","그래서 15 cm예요."],"mis":"M5-2-u5-X16","asset":{"type":"geo","items":[{"w":64,"h":48,"seg":[[[0,0],[0,48]],[[0,0],[16,0]],[[0,48],[16,48]],[[16,0],[16,16]],[[16,16],[64,16]],[[16,32],[16,48]],[[16,32],[64,32]],[[64,16],[64,32]]],"dash":[[[0,16],[16,16]],[[0,32],[16,32]],[[16,16],[16,32]],[[32,16],[32,32]],[[48,16],[48,32]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"한 모서리가 16 cm인 정육면체의 전개도를 그렸어요. 잘리지 않은 모서리(점선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["면 6개를 잇는 점선은 5개예요.","16 × 5 = 80이에요.","그래서 80 cm예요."],"asset":{"type":"geo","items":[{"w":64,"h":48,"seg":[[[0,0],[0,48]],[[0,0],[16,0]],[[0,48],[16,48]],[[16,0],[16,16]],[[16,16],[64,16]],[[16,32],[16,48]],[[16,32],[64,32]],[[64,16],[64,32]]],"dash":[[[0,16],[16,16]],[[0,32],[16,32]],[[16,16],[16,32]],[[32,16],[32,32]],[[48,16],[48,32]]]}],"tag":false}},{"stem":"한 모서리가 8 cm인 정육면체의 전개도를 그렸어요. 잘리지 않은 모서리(점선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["면 6개를 잇는 점선은 5개예요.","8 × 5 = 40이에요.","그래서 40 cm예요."],"asset":{"type":"geo","items":[{"w":64,"h":48,"seg":[[[0,0],[0,48]],[[0,0],[16,0]],[[0,48],[16,48]],[[16,0],[16,16]],[[16,16],[64,16]],[[16,32],[16,48]],[[16,32],[64,32]],[[64,16],[64,32]]],"dash":[[[0,16],[16,16]],[[0,32],[16,32]],[[16,16],[16,32]],[[32,16],[32,32]],[[48,16],[48,32]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L07_challenge#8','math',5,2,'u5','L07','tb_g5_2_math_u5_L07_challenge','lesson_challenge','M5-2-u5-C7',4,'sa','auto','모눈 한 칸이 1 cm인 모눈종이에 그린 직육면체의 전개도예요(교과서 118쪽에 나온 직육면체). 잘린 모서리(실선)를 따라 둘레를 한 바퀴 재면 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u5-C7","difficulty":4,"kind":"sa","stem":"모눈 한 칸이 1 cm인 모눈종이에 그린 직육면체의 전개도예요(교과서 118쪽에 나온 직육면체). 잘린 모서리(실선)를 따라 둘레를 한 바퀴 재면 몇 cm인가요? 숫자로 쓰세요.","answer":["38"],"explanation":["둘레를 따라 실선의 길이를 차례로 세어요.","3 + 2 + 2 + 3 + 2 + 5 + 2 + 2 + 3 + 2 + 2 + 3 + 5 + 2 = 38이에요.","그래서 38 cm예요 — 잘린 모서리 하나가 둘레에 두 번씩 나와요."],"mis":"M5-2-u5-X16","asset":{"type":"geo","items":[{"w":120,"h":108,"seg":[[[0,0],[0,84]],[[0,0],[36,0]],[[0,84],[60,84]],[[36,0],[36,24]],[[36,24],[120,24]],[[60,84],[60,108]],[[60,108],[96,108]],[[96,84],[96,108]],[[96,84],[120,84]],[[120,24],[120,84]]],"dash":[[[0,24],[36,24]],[[36,24],[36,84]],[[60,24],[60,84]],[[60,84],[96,84]],[[96,24],[96,84]]],"grid":12}],"tag":false},"variant_rule":{"alt":[{"stem":"모눈 한 칸이 1 cm인 모눈종이에 그린 직육면체의 전개도예요(문제로 마무리 8번에 나온 직육면체). 잘린 모서리(실선)를 따라 둘레를 한 바퀴 재면 몇 cm인가요? 숫자로 쓰세요.","answer":["52"],"explanation":["둘레를 따라 실선의 길이를 차례로 세어요.","5 + 3 + 3 + 5 + 3 + 4 + 3 + 3 + 5 + 3 + 3 + 5 + 4 + 3 = 52예요.","그래서 52 cm예요 — 잘린 모서리 하나가 둘레에 두 번씩 나와요."],"asset":{"type":"geo","items":[{"w":192,"h":120,"seg":[[[0,0],[0,84]],[[0,0],[60,0]],[[0,84],[96,84]],[[60,0],[60,36]],[[60,36],[192,36]],[[96,84],[96,120]],[[96,120],[156,120]],[[156,84],[156,120]],[[156,84],[192,84]],[[192,36],[192,84]]],"dash":[[[0,36],[60,36]],[[60,36],[60,84]],[[96,36],[96,84]],[[96,84],[156,84]],[[156,36],[156,84]]],"grid":12}],"tag":false}},{"stem":"모눈 한 칸이 1 cm인 모눈종이에 그린 직육면체의 전개도예요(단원 평가에 나온 직육면체). 잘린 모서리(실선)를 따라 둘레를 한 바퀴 재면 몇 cm인가요? 숫자로 쓰세요.","answer":["38"],"explanation":["둘레를 따라 실선의 길이를 차례로 세어요.","4 + 2 + 2 + 4 + 2 + 3 + 2 + 2 + 4 + 2 + 2 + 4 + 3 + 2 = 38이에요.","그래서 38 cm예요 — 잘린 모서리 하나가 둘레에 두 번씩 나와요."],"asset":{"type":"geo","items":[{"w":144,"h":84,"seg":[[[0,0],[0,60]],[[0,0],[48,0]],[[0,60],[72,60]],[[48,0],[48,24]],[[48,24],[144,24]],[[72,60],[72,84]],[[72,84],[120,84]],[[120,60],[120,84]],[[120,60],[144,60]],[[144,24],[144,60]]],"dash":[[[0,24],[48,24]],[[48,24],[48,60]],[[72,24],[72,60]],[[72,60],[120,60]],[[120,24],[120,60]]],"grid":12}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L07_challenge#9','math',5,2,'u5','L07','tb_g5_2_math_u5_L07_challenge','lesson_challenge','M5-2-u5-C7',4,'sa','auto','모눈 한 칸이 1 cm인 모눈종이에 그린 직육면체의 전개도예요(단원 평가에 나온 직육면체). 이 전개도를 접어 만든 직육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u5-C7","difficulty":4,"kind":"sa","stem":"모눈 한 칸이 1 cm인 모눈종이에 그린 직육면체의 전개도예요(단원 평가에 나온 직육면체). 이 전개도를 접어 만든 직육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["56"],"explanation":["모눈을 세면 가로 3 cm, 세로 6 cm, 높이 5 cm인 직육면체예요.","3 × 4 + 6 × 4 + 5 × 4 = 56이에요.","그래서 56 cm예요."],"mis":"M5-2-u5-X20","asset":{"type":"geo","items":[{"w":216,"h":204,"seg":[[[0,0],[0,132]],[[0,0],[36,0]],[[0,132],[108,132]],[[36,0],[36,72]],[[36,72],[216,72]],[[108,132],[108,204]],[[108,204],[144,204]],[[144,132],[144,204]],[[144,132],[216,132]],[[216,72],[216,132]]],"dash":[[[0,72],[36,72]],[[36,72],[36,132]],[[108,72],[108,132]],[[108,132],[144,132]],[[144,72],[144,132]]],"grid":12}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈 한 칸이 1 cm인 모눈종이에 그린 직육면체의 전개도예요(단원 평가에 나온 직육면체). 이 전개도를 접어 만든 직육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["모눈을 세면 가로 5 cm, 세로 7 cm, 높이 8 cm인 직육면체예요.","5 × 4 + 7 × 4 + 8 × 4 = 80이에요.","그래서 80 cm예요."],"asset":{"type":"geo","items":[{"w":288,"h":264,"seg":[[[0,0],[0,180]],[[0,0],[60,0]],[[0,180],[144,180]],[[60,0],[60,84]],[[60,84],[288,84]],[[144,180],[144,264]],[[144,264],[204,264]],[[204,180],[204,264]],[[204,180],[288,180]],[[288,84],[288,180]]],"dash":[[[0,84],[60,84]],[[60,84],[60,180]],[[144,84],[144,180]],[[144,180],[204,180]],[[204,84],[204,180]]],"grid":12}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈 한 칸이 1 cm인 모눈종이에 그린 직육면체의 전개도예요(단원 평가에 나온 직육면체). 이 전개도를 접어 만든 직육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["모눈을 세면 가로 4 cm, 세로 8 cm, 높이 6 cm인 직육면체예요.","4 × 4 + 8 × 4 + 6 × 4 = 72예요.","그래서 72 cm예요."],"asset":{"type":"geo","items":[{"w":288,"h":264,"seg":[[[0,0],[0,168]],[[0,0],[48,0]],[[0,168],[144,168]],[[48,0],[48,96]],[[48,96],[288,96]],[[144,168],[144,264]],[[144,264],[192,264]],[[192,168],[192,264]],[[192,168],[288,168]],[[288,96],[288,168]]],"dash":[[[0,96],[48,96]],[[48,96],[48,168]],[[144,96],[144,168]],[[144,168],[192,168]],[[192,96],[192,168]]],"grid":12}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L07_challenge#10','math',5,2,'u5','L07','tb_g5_2_math_u5_L07_challenge','lesson_challenge','M5-2-u5-C7',4,'essay','teacher','가로 4 cm, 세로 2 cm, 높이 3 cm인 직육면체(단원 평가)의 전개도를 그리려고 해요. 어떤 직사각형을 몇 개씩 그려야 하는지 쓰고, 전개도를 그릴 때 지켜야 할 약속 두 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u5-C7","difficulty":4,"kind":"essay","stem":"가로 4 cm, 세로 2 cm, 높이 3 cm인 직육면체(단원 평가)의 전개도를 그리려고 해요. 어떤 직사각형을 몇 개씩 그려야 하는지 쓰고, 전개도를 그릴 때 지켜야 할 약속 두 가지를 쓰세요.","answer_guide":{"answer":"예: 가로 4 cm, 세로 2 cm인 직사각형 2개, 가로 4 cm, 세로 3 cm인 직사각형 2개, 가로 2 cm, 세로 3 cm인 직사각형 2개를 그린다. 면 6개를 겹치지 않게 이어 그리고, 접었을 때 만나는 모서리는 길이가 같게, 마주 보는 면은 모양과 크기가 같게 그린다. 잘린 모서리는 실선, 잘리지 않은 모서리는 점선으로 그린다.","scoring_points":["세 가지 직사각형을 2개씩 썼는가","만나는 모서리 길이를 같게 그린다고 썼는가","실선·점선 또는 마주 보는 면 약속을 썼는가"]},"explanation":["마주 보는 면은 모양과 크기가 같아 세 가지 직사각형이 2개씩이에요.","만나는 모서리는 길이가 같게 그려요.","잘린 모서리는 실선, 잘리지 않은 모서리는 점선이에요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[44.0,96.0],"4 cm"],[[115.0,81.0],"2 cm"],[[70,55.0],"3 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L08_basic#1','math',5,2,'u5','L08','tb_g5_2_math_u5_L08_basic','lesson_basic','M5-2-u5-C8',1,'match','auto','알쏭달쏭 프로그램의 주사위 전개도를 접었을 때 평행한 면끼리 알맞게 이어 보세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u5-C8","difficulty":1,"kind":"match","stem":"알쏭달쏭 프로그램의 주사위 전개도를 접었을 때 평행한 면끼리 알맞게 이어 보세요.","pairs":[{"l":"1과 평행한 면","r":"6"},{"l":"2와 평행한 면","r":"5"},{"l":"3과 평행한 면","r":"4"}],"mis":"M5-2-u5-X12","explanation":["전개도를 접으면 마주 보는 면끼리 평행해요.","이 주사위는 1과 6, 2와 5, 3과 4가 평행해요.","평행한 두 면의 눈의 수를 더하면 7이에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알쏭달쏭 프로그램의 주사위 전개도를 접었을 때 평행한 면끼리 알맞게 이어 보세요.","pairs":[{"l":"4와 평행한 면","r":"3"},{"l":"5와 평행한 면","r":"2"},{"l":"6과 평행한 면","r":"1"}],"explanation":["전개도를 접으면 마주 보는 면끼리 평행해요.","이 주사위는 1과 6, 2와 5, 3과 4가 평행해요.","평행한 두 면의 눈의 수를 더하면 7이에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}},{"stem":"이번에는 다른 보기예요. 알쏭달쏭 프로그램의 주사위 전개도를 접었을 때 평행한 면끼리 알맞게 이어 보세요.","pairs":[{"l":"1과 평행한 면","r":"6"},{"l":"3과 평행한 면","r":"4"},{"l":"5와 평행한 면","r":"2"}],"expl