INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L08_basic#5','math',5,2,'u5','L08','tb_g5_2_math_u5_L08_basic','lesson_basic','M5-2-u5-C8',2,'sa','auto','알쏭달쏭 프로그램에서 쓰는 주사위의 전개도예요. 3이 보일 때, 3과 수직인 면 가운데 눈의 수가 가장 큰 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u5-C8","difficulty":2,"kind":"sa","stem":"알쏭달쏭 프로그램에서 쓰는 주사위의 전개도예요. 3이 보일 때, 3과 수직인 면 가운데 눈의 수가 가장 큰 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["3과 평행한 면은 4예요.","3과 수직인 면은 나머지 1, 2, 5, 6이에요.","가장 큰 수는 6이에요."],"mis":"M5-2-u5-X13","asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"알쏭달쏭 프로그램에서 쓰는 주사위의 전개도예요. 6이 보일 때, 6과 수직인 면 가운데 눈의 수가 가장 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["6과 평행한 면은 1이에요.","6과 수직인 면은 나머지 2, 3, 4, 5예요.","가장 작은 수는 2예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}},{"stem":"알쏭달쏭 프로그램에서 쓰는 주사위의 전개도예요. 1이 보일 때, 1과 수직인 면 가운데 눈의 수가 가장 큰 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["1과 평행한 면은 6이에요.","1과 수직인 면은 나머지 2, 3, 4, 5예요.","가장 큰 수는 5예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L08_basic#6','math',5,2,'u5','L08','tb_g5_2_math_u5_L08_basic','lesson_basic','M5-2-u5-C8',2,'sa','auto','프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 큰 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 4가 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u5-C8","difficulty":2,"kind":"sa","stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 큰 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 4가 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["① 4와 평행한 면 3이 보이게 굴려요.","② 3과 수직인 면 1, 2, 5, 6 가운데 가장 큰 수는 6이에요.","그래서 6이 보여요."],"mis":"M5-2-u5-X17","asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 작은 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 1이 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["① 1과 평행한 면 6이 보이게 굴려요.","② 6과 수직인 면 2, 3, 4, 5 가운데 가장 작은 수는 2예요.","그래서 2가 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}},{"stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 큰 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 6이 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["① 6과 평행한 면 1이 보이게 굴려요.","② 1과 수직인 면 2, 3, 4, 5 가운데 가장 큰 수는 5예요.","그래서 5가 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L08_basic#7','math',5,2,'u5','L08','tb_g5_2_math_u5_L08_basic','lesson_basic','M5-2-u5-C8',2,'mc','auto','알쏭달쏭 프로그램 문제에서 구하려는 것은 무엇인가요?',ARRAY['M5-2-u5-X17','M5-2-u5-X18']::text[],true,'{"seq":7,"concept":"M5-2-u5-C8","difficulty":2,"kind":"mc","stem":"알쏭달쏭 프로그램 문제에서 구하려는 것은 무엇인가요?","options":[{"t":"프로그램을 실행했을 때 보이는 주사위 눈의 수","correct":true},{"t":"주사위 눈의 수의 합","mis":"M5-2-u5-X17"},{"t":"주사위를 굴린 횟수","mis":"M5-2-u5-X18"},{"t":"주사위 전개도의 면의 수","mis":"M5-2-u5-X18"}],"explanation":["구하려는 것은 프로그램을 실행했을 때 보이는 눈의 수예요.","횟수가 많으면 적은 횟수로 해 보며 눈의 수가 되풀이되는 것을 찾아요(단순화하기).","정답은 「프로그램을 실행했을 때 보이는 주사위 눈의 수」예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"명령을 6번 반복해야 할 때, 6번을 모두 해 보지 않고 해결하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"몇 번 실행해 보며 보이는 눈의 수가 되풀이되는 것을 찾는다","correct":true},{"t":"반복 횟수만큼 모두 굴려 본다","mis":"M5-2-u5-X17"},{"t":"눈의 수를 모두 더한다","mis":"M5-2-u5-X17"},{"t":"시작하는 수를 바꾼다","mis":"M5-2-u5-X17"}],"explanation":["구하려는 것은 프로그램을 실행했을 때 보이는 눈의 수예요.","횟수가 많으면 적은 횟수로 해 보며 눈의 수가 되풀이되는 것을 찾아요(단순화하기).","정답은 「몇 번 실행해 보며 보이는 눈의 수가 되풀이되는 것을 찾는다」예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}},{"stem":"교과서 122~123쪽에서 쓴 문제 해결 방법(전략)은 어느 것인가요?","options":[{"t":"단순화하기 — 적은 횟수로 해 보고 되풀이를 찾기","correct":true},{"t":"표 만들기 — 눈의 수를 모두 적기","mis":"M5-2-u5-X17"},{"t":"거꾸로 풀기 — 마지막 수부터 거꾸로","mis":"M5-2-u5-X17"},{"t":"식 세우기 — 눈의 수를 모두 곱하기","mis":"M5-2-u5-X17"}],"explanation":["구하려는 것은 프로그램을 실행했을 때 보이는 눈의 수예요.","횟수가 많으면 적은 횟수로 해 보며 눈의 수가 되풀이되는 것을 찾아요(단순화하기).","정답은 「단순화하기 — 적은 횟수로 해 보고 되풀이를 찾기」예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L08_basic#8','math',5,2,'u5','L08','tb_g5_2_math_u5_L08_basic','lesson_basic','M5-2-u5-C8',2,'sa','auto','프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 작은 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 2가 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u5-C8","difficulty":2,"kind":"sa","stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 작은 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 2가 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["① 2와 평행한 면 5가 보이게 굴려요.","② 5와 수직인 면 1, 3, 4, 6 가운데 가장 작은 수는 1이에요.","그래서 1이 보여요."],"mis":"M5-2-u5-X17","asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 큰 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 5가 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["① 5와 평행한 면 2가 보이게 굴려요.","② 2와 수직인 면 1, 3, 4, 6 가운데 가장 큰 수는 6이에요.","그래서 6이 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}},{"stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 큰 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 3이 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["① 3과 평행한 면 4가 보이게 굴려요.","② 4와 수직인 면 1, 2, 5, 6 가운데 가장 큰 수는 6이에요.","그래서 6이 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L08_basic#9','math',5,2,'u5','L08','tb_g5_2_math_u5_L08_basic','lesson_basic','M5-2-u5-C8',2,'error','auto','알쏭달쏭 프로그램을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-2-u5-X12','M5-2-u5-X13']::text[],true,'{"seq":9,"concept":"M5-2-u5-C8","difficulty":2,"kind":"error","stem":"알쏭달쏭 프로그램을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"달곰 — 「1과 평행한 면은 바로 옆에 붙은 5야.」","correct":true,"mis_target":"M5-2-u5-X12"},{"t":"여울 — 「1과 평행한 면은 6이야.」","mis":"M5-2-u5-X12"},{"t":"순달 — 「1과 수직인 면은 2, 3, 4, 5야.」","mis":"M5-2-u5-X13"}],"explanation":["이 주사위는 1과 6, 2와 5, 3과 4가 평행해요.","명령은 평행한 면으로 굴린 뒤 그 면과 수직인 면 가운데에서 골라요.","달곰의 말이 틀렸어요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알쏭달쏭 프로그램을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지우 — 「4에서 시작해 가장 큰 수를 고르는 명령으로 1번 하면 5가 보여.」","correct":true,"mis_target":"M5-2-u5-X17"},{"t":"윤수 — 「4와 평행한 면은 3이야.」","mis":"M5-2-u5-X12"},{"t":"서연 — 「3과 수직인 면 가운데 가장 큰 수는 6이야.」","mis":"M5-2-u5-X13"}],"explanation":["이 주사위는 1과 6, 2와 5, 3과 4가 평행해요.","명령은 평행한 면으로 굴린 뒤 그 면과 수직인 면 가운데에서 골라요.","지우의 말이 틀렸어요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}},{"stem":"이번에는 다른 보기예요. 알쏭달쏭 프로그램을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 「반복 횟수가 많으면 끝까지 다 굴려야만 알 수 있어.」","correct":true,"mis_target":"M5-2-u5-X17"},{"t":"지우 — 「몇 번 굴려 보고 되풀이되는 것을 찾으면 돼.」","mis":"M5-2-u5-X17"},{"t":"윤수 — 「평행한 두 면의 수를 더하면 7이야.」","mis":"M5-2-u5-X12"}],"explanation":["이 주사위는 1과 6, 2와 5, 3과 4가 평행해요.","명령은 평행한 면으로 굴린 뒤 그 면과 수직인 면 가운데에서 골라요.","태민의 말이 틀렸어요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L08_basic#10','math',5,2,'u5','L08','tb_g5_2_math_u5_L08_basic','lesson_basic','M5-2-u5-C8',3,'sa','auto','프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 작은 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 1이 보이게 놓고 시작해 6번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M5-2-u5-C8","difficulty":3,"kind":"sa","stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 작은 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 1이 보이게 놓고 시작해 6번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["몇 번만 실행해 보면 1 → 2 → 1 → 2 → 1이에요.","2번마다 처음 수로 되풀이돼요.","그래서 6번 실행하면 1이 보여요."],"mis":"M5-2-u5-X17","asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 큰 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 6이 보이게 놓고 시작해 9번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["몇 번만 실행해 보면 6 → 5 → 6 → 5 → 6이에요.","2번마다 처음 수로 되풀이돼요.","그래서 9번 실행하면 5가 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}},{"stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 큰 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 4가 보이게 놓고 시작해 6번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["몇 번만 실행해 보면 4 → 6 → 5 → 6 → 5예요.","2번째부터 2번마다 되풀이돼요.","그래서 6번 실행하면 5가 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L08_challenge#1','math',5,2,'u5','L08','tb_g5_2_math_u5_L08_challenge','lesson_challenge','M5-2-u5-C8',2,'sa','auto','알쏭달쏭 프로그램에서 쓰는 주사위의 전개도예요. 2가 보일 때, 2와 수직인 면 가운데 눈의 수가 가장 큰 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u5-C8","difficulty":2,"kind":"sa","stem":"알쏭달쏭 프로그램에서 쓰는 주사위의 전개도예요. 2가 보일 때, 2와 수직인 면 가운데 눈의 수가 가장 큰 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["2와 평행한 면은 5예요.","2와 수직인 면은 나머지 1, 3, 4, 6이에요.","가장 큰 수는 6이에요."],"mis":"M5-2-u5-X13","asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"알쏭달쏭 프로그램에서 쓰는 주사위의 전개도예요. 5가 보일 때, 5와 수직인 면 가운데 눈의 수가 가장 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["5와 평행한 면은 2예요.","5와 수직인 면은 나머지 1, 3, 4, 6이에요.","가장 작은 수는 1이에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}},{"stem":"알쏭달쏭 프로그램에서 쓰는 주사위의 전개도예요. 4가 보일 때, 4와 수직인 면 가운데 눈의 수가 가장 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["4와 평행한 면은 3이에요.","4와 수직인 면은 나머지 1, 2, 5, 6이에요.","가장 작은 수는 1이에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L08_challenge#2','math',5,2,'u5','L08','tb_g5_2_math_u5_L08_challenge','lesson_challenge','M5-2-u5-C8',2,'mc','auto','명령을 반복하는 횟수가 아주 많을 때 알맞은 해결 방법은 어느 것인가요?',ARRAY['M5-2-u5-X17']::text[],true,'{"seq":2,"concept":"M5-2-u5-C8","difficulty":2,"kind":"mc","stem":"명령을 반복하는 횟수가 아주 많을 때 알맞은 해결 방법은 어느 것인가요?","options":[{"t":"몇 번 굴려 보고 되풀이되는 규칙을 찾는다","correct":true},{"t":"반복 횟수만큼 모두 굴려 본다","mis":"M5-2-u5-X17"},{"t":"눈의 수를 모두 더한다","mis":"M5-2-u5-X17"},{"t":"시작하는 수를 바꾼다","mis":"M5-2-u5-X17"}],"explanation":["평행한 면과 수직인 면을 먼저 찾아요.","몇 번 실행해 되풀이되는 규칙을 찾으면 끝까지 굴리지 않아도 돼요.","정답은 「몇 번 굴려 보고 되풀이되는 규칙을 찾는다」예요."],"variant_rule":{"alt":[{"stem":"주사위 굴리기 결과가 2번마다 처음 수로 되풀이돼요. 10번 실행한 결과는 어떻게 알 수 있나요?","options":[{"t":"10은 2로 나누어떨어지므로 처음 수와 같다","correct":true},{"t":"10번 모두 굴려야만 알 수 있다","mis":"M5-2-u5-X17"},{"t":"1번 실행한 결과와 같다","mis":"M5-2-u5-X17"},{"t":"알 수 없다","mis":"M5-2-u5-X17"}],"explanation":["평행한 면과 수직인 면을 먼저 찾아요.","몇 번 실행해 되풀이되는 규칙을 찾으면 끝까지 굴리지 않아도 돼요.","정답은 「10은 2로 나누어떨어지므로 처음 수와 같다」예요."]},{"stem":"주사위 전개도에서 평행한 두 면의 눈의 수를 바르게 말한 것은 어느 것인가요?","options":[{"t":"평행한 두 면의 눈의 수를 더하면 7이다","correct":true},{"t":"이웃한 두 면의 눈의 수를 더하면 7이다","mis":"M5-2-u5-X12"},{"t":"평행한 두 면의 눈의 수는 같다","mis":"M5-2-u5-X12"},{"t":"평행한 두 면의 눈의 수를 더하면 6이다","mis":"M5-2-u5-X12"}],"explanation":["평행한 면과 수직인 면을 먼저 찾아요.","몇 번 실행해 되풀이되는 규칙을 찾으면 끝까지 굴리지 않아도 돼요.","정답은 「평행한 두 면의 눈의 수를 더하면 7이다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L08_challenge#3','math',5,2,'u5','L08','tb_g5_2_math_u5_L08_challenge','lesson_challenge','M5-2-u5-C8',3,'sa','auto','프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 작은 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 3이 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u5-C8","difficulty":3,"kind":"sa","stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 작은 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 3이 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["① 3과 평행한 면 4가 보이게 굴려요.","② 4와 수직인 면 1, 2, 5, 6 가운데 가장 작은 수는 1이에요.","그래서 1이 보여요."],"mis":"M5-2-u5-X17","asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 큰 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 2가 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["① 2와 평행한 면 5가 보이게 굴려요.","② 5와 수직인 면 1, 3, 4, 6 가운데 가장 큰 수는 6이에요.","그래서 6이 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.