INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L08_challenge#4','math',5,2,'u5','L08','tb_g5_2_math_u5_L08_challenge','lesson_challenge','M5-2-u5-C8',3,'sa','auto','프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 작은 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 1이 보이게 놓고 시작해 9번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u5-C8","difficulty":3,"kind":"sa","stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 작은 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 1이 보이게 놓고 시작해 9번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["몇 번만 실행해 보면 1 → 2 → 1 → 2 → 1이에요.","2번마다 처음 수로 되풀이돼요.","그래서 9번 실행하면 2가 보여요."],"mis":"M5-2-u5-X17","asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 큰 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 6이 보이게 놓고 시작해 10번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["몇 번만 실행해 보면 6 → 5 → 6 → 5 → 6이에요.","2번마다 처음 수로 되풀이돼요.","그래서 10번 실행하면 6이 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}},{"stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 큰 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 2가 보이게 놓고 시작해 7번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["몇 번만 실행해 보면 2 → 6 → 5 → 6 → 5예요.","2번째부터 2번마다 되풀이돼요.","그래서 7번 실행하면 6이 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L08_challenge#5','math',5,2,'u5','L08','tb_g5_2_math_u5_L08_challenge','lesson_challenge','M5-2-u5-C8',3,'mc','auto','알쏭달쏭 프로그램에서 쓰는 주사위의 전개도예요. 눈의 수 2와 수직인 면의 눈의 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u5-X12','M5-2-u5-X13']::text[],true,'{"seq":5,"concept":"M5-2-u5-C8","difficulty":3,"kind":"mc","stem":"알쏭달쏭 프로그램에서 쓰는 주사위의 전개도예요. 눈의 수 2와 수직인 면의 눈의 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"1, 3, 4, 6","correct":true},{"t":"1, 3, 4, 5","mis":"M5-2-u5-X12"},{"t":"3, 4, 5, 6","mis":"M5-2-u5-X12"},{"t":"1, 3, 4, 5, 6","mis":"M5-2-u5-X13"}],"explanation":["2와 평행한 면은 5 하나예요.","나머지 네 면이 2와 수직이에요.","정답은 1, 3, 4, 6이에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"알쏭달쏭 프로그램에서 쓰는 주사위의 전개도예요. 눈의 수 5와 수직인 면의 눈의 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"1, 3, 4, 6","correct":true},{"t":"1, 2, 3, 4","mis":"M5-2-u5-X12"},{"t":"2, 3, 4, 6","mis":"M5-2-u5-X12"},{"t":"1, 2, 3, 4, 6","mis":"M5-2-u5-X13"}],"explanation":["5와 평행한 면은 2 하나예요.","나머지 네 면이 5와 수직이에요.","정답은 1, 3, 4, 6이에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}},{"stem":"알쏭달쏭 프로그램에서 쓰는 주사위의 전개도예요. 눈의 수 4와 수직인 면의 눈의 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"1, 2, 5, 6","correct":true},{"t":"1, 2, 3, 5","mis":"M5-2-u5-X12"},{"t":"2, 3, 5, 6","mis":"M5-2-u5-X12"},{"t":"1, 2, 3, 5, 6","mis":"M5-2-u5-X13"}],"explanation":["4와 평행한 면은 3 하나예요.","나머지 네 면이 4와 수직이에요.","정답은 1, 2, 5, 6이에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L08_challenge#6','math',5,2,'u5','L08','tb_g5_2_math_u5_L08_challenge','lesson_challenge','M5-2-u5-C8',3,'error','auto','알쏭달쏭 프로그램을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-2-u5-X17','M5-2-u5-X12','M5-2-u5-X13']::text[],true,'{"seq":6,"concept":"M5-2-u5-C8","difficulty":3,"kind":"error","stem":"알쏭달쏭 프로그램을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 「4에서 시작해 가장 큰 수를 고르는 명령으로 1번 하면 5가 보여.」","correct":true,"mis_target":"M5-2-u5-X17"},{"t":"지우 — 「4와 평행한 면은 3이야.」","mis":"M5-2-u5-X12"},{"t":"윤수 — 「3과 수직인 면 가운데 가장 큰 수는 6이야.」","mis":"M5-2-u5-X13"}],"explanation":["이 주사위는 1과 6, 2와 5, 3과 4가 평행해요.","명령은 평행한 면으로 굴린 뒤 그 면과 수직인 면 가운데에서 골라요.","태민의 말이 틀렸어요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알쏭달쏭 프로그램을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"연희 — 「반복 횟수가 많으면 끝까지 다 굴려야만 알 수 있어.」","correct":true,"mis_target":"M5-2-u5-X17"},{"t":"세영 — 「몇 번 굴려 보고 되풀이되는 것을 찾으면 돼.」","mis":"M5-2-u5-X17"},{"t":"민지 — 「평행한 두 면의 수를 더하면 7이야.」","mis":"M5-2-u5-X12"}],"explanation":["이 주사위는 1과 6, 2와 5, 3과 4가 평행해요.","명령은 평행한 면으로 굴린 뒤 그 면과 수직인 면 가운데에서 골라요.","연희의 말이 틀렸어요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}},{"stem":"이번에는 다른 보기예요. 알쏭달쏭 프로그램을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"달곰 — 「1과 평행한 면은 바로 옆에 붙은 5야.」","correct":true,"mis_target":"M5-2-u5-X12"},{"t":"여울 — 「1과 평행한 면은 6이야.」","mis":"M5-2-u5-X12"},{"t":"순달 — 「1과 수직인 면은 2, 3, 4, 5야.」","mis":"M5-2-u5-X13"}],"explanation":["이 주사위는 1과 6, 2와 5, 3과 4가 평행해요.","명령은 평행한 면으로 굴린 뒤 그 면과 수직인 면 가운데에서 골라요.","달곰의 말이 틀렸어요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L08_challenge#7','math',5,2,'u5','L08','tb_g5_2_math_u5_L08_challenge','lesson_challenge','M5-2-u5-C8',3,'sa','auto','주사위의 마주 보는 면의 눈의 수의 합은 7이에요(단원 평가). 눈의 수가 3인 면과 수직인 면의 눈의 수의 합은 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u5-C8","difficulty":3,"kind":"sa","stem":"주사위의 마주 보는 면의 눈의 수의 합은 7이에요(단원 평가). 눈의 수가 3인 면과 수직인 면의 눈의 수의 합은 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["3과 마주 보는(평행한) 면은 7 − 3 = 4예요.","수직인 면은 나머지 1, 2, 5, 6이에요.","1 + 2 + 5 + 6 = 14예요."],"mis":"M5-2-u5-X13","asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"주사위의 마주 보는 면의 눈의 수의 합은 7이에요(단원 평가). 눈의 수가 1인 면과 수직인 면의 눈의 수의 합은 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["1과 마주 보는(평행한) 면은 7 − 1 = 6이에요.","수직인 면은 나머지 2, 3, 4, 5예요.","2 + 3 + 4 + 5 = 14예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}},{"stem":"주사위의 마주 보는 면의 눈의 수의 합은 7이에요(단원 평가). 눈의 수가 2인 면과 수직인 면의 눈의 수의 합은 얼마인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["2와 마주 보는(평행한) 면은 7 − 2 = 5예요.","수직인 면은 나머지 1, 3, 4, 6이에요.","1 + 3 + 4 + 6 = 14예요."],"ass