INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L08_challenge#9','math',5,2,'u5','L08','tb_g5_2_math_u5_L08_challenge','lesson_challenge','M5-2-u5-C8',4,'sa','auto','프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 작은 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 1이 보이게 놓고 시작해 6번 실행했어요. 실행할 때마다 보이는 눈의 수를 적으면 1은 몇 번 나오나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u5-C8","difficulty":4,"kind":"sa","stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 작은 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 1이 보이게 놓고 시작해 6번 실행했어요. 실행할 때마다 보이는 눈의 수를 적으면 1은 몇 번 나오나요? 숫자로 쓰세요.","answer":["3"],"explanation":["1번씩 실행해 보면 2, 1, 2, 1, 2, 1이에요.","1이 나온 횟수를 세어요.","그래서 3번이에요."],"mis":"M5-2-u5-X17","asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 큰 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 6이 보이게 놓고 시작해 9번 실행했어요. 실행할 때마다 보이는 눈의 수를 적으면 5는 몇 번 나오나요? 숫자로 쓰세요.","answer":["5"],"explanation":["1번씩 실행해 보면 5, 6, 5, 6, 5, 6, 5, 6, 5예요.","5가 나온 횟수를 세어요.","그래서 5번이에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}},{"stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 큰 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 4가 보이게 놓고 시작해 6번 실행했어요. 실행할 때마다 보이는 눈의 수를 적으면 6은 몇 번 나오나요? 숫자로 쓰세요.","answer":["3"],"explanation":["1번씩 실행해 보면 6, 5, 6, 5, 6, 5예요.","6이 나온 횟수를 세어요.","그래서 3번이에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_L08_challenge#10','math',5,2,'u5','L08','tb_g5_2_math_u5_L08_challenge','lesson_challenge','M5-2-u5-C8',4,'essay','teacher','교과서 122쪽 주사위의 전개도를 보고 눈의 수 1에서 시작해 「보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 작은 면이 보이게 굴리기」를 6번 반복하려고 해요. 6번을 모두 굴리지 않고 결과를 구하는 방법과 결과를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u5-C8","difficulty":4,"kind":"essay","stem":"교과서 122쪽 주사위의 전개도를 보고 눈의 수 1에서 시작해 「보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 작은 면이 보이게 굴리기」를 6번 반복하려고 해요. 6번을 모두 굴리지 않고 결과를 구하는 방법과 결과를 쓰세요.","answer_guide":{"answer":"예: 1에서 시작하면 평행한 6으로 굴린 뒤 6과 수직인 2, 3, 4, 5 가운데 가장 작은 2가 보인다. 2에서는 평행한 5로 굴린 뒤 1, 3, 4, 6 가운데 가장 작은 1이 보인다. 그래서 1 → 2 → 1 → 2로 2번 반복할 때마다 처음 눈의 수 1이 나온다. 6번은 2번씩 세 번이므로 1이 보인다.","scoring_points":["1번·2번 실행 결과(2, 1)을 구했는가","2번마다 처음 수가 다시 나온다고 썼는가","6번 실행하면 1이라고 결론지었는가"]},"explanation":["1 → 2, 2 → 1로 바뀌어요.","2번 반복할 때마다 처음 수 1이 다시 나와요.","6번 실행하면 1이 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_a#1','math',5,2,'u5','','tb_g5_2_math_u5_review_a','unit_review','M5-2-u5-C2',1,'mc','auto','문제로 마무리 1번의 물건이에요. 가: 면이 모두 직사각형인 휴지 상자 / 나: 양쪽 면이 사다리꼴인 과자 상자 / 다: 삼각형 면이 있는 샌드위치 상자 / 라: 면이 모두 직사각형인 지우개. 직육면체 모양을 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u5-X18','M5-2-u5-X02']::text[],true,'{"seq":1,"concept":"M5-2-u5-C2","difficulty":1,"kind":"mc","stem":"문제로 마무리 1번의 물건이에요. 가: 면이 모두 직사각형인 휴지 상자 / 나: 양쪽 면이 사다리꼴인 과자 상자 / 다: 삼각형 면이 있는 샌드위치 상자 / 라: 면이 모두 직사각형인 지우개. 직육면체 모양을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 라","correct":true},{"t":"가","mis":"M5-2-u5-X18"},{"t":"가, 나, 라","mis":"M5-2-u5-X02"},{"t":"가, 다, 라","mis":"M5-2-u5-X02"}],"explanation":["직육면체는 직사각형 6개로 둘러싸인 입체도형이에요.","정사각형도 직사각형이니 정사각형 6개로 둘러싸인 것도 직육면체예요.","정답은 가, 라예요."],"variant_rule":{"alt":[{"stem":"형성 평가 그림이에요. 가: 원 모양 면이 있는 통 / 나: 삼각형 면만 있는 뿔 / 다: 정사각형 6개로 둘러싸인 상자 / 라: 삼각형 면이 있는 기둥 / 마: 직사각형 6개로 둘러싸인 상자 / 바: 꼭짓점이 뾰족한 원뿔. 직육면체를 모두 고른 것은 어느 것인가요?","options":[{"t":"다, 마","correct":true},{"t":"마","mis":"M5-2-u5-X06"},{"t":"다, 라, 마","mis":"M5-2-u5-X02"},{"t":"나, 다, 마","mis":"M5-2-u5-X02"}],"explanation":["직육면체는 직사각형 6개로 둘러싸인 입체도형이에요.","정사각형도 직사각형이니 정사각형 6개로 둘러싸인 것도 직육면체예요.","정답은 다, 마예요."]},{"stem":"교과서 107쪽 그림이에요. 가: 위와 아래가 원 모양인 통 / 나: 직사각형 6개로 둘러싸인 상자 / 다: 위와 아래가 삼각형 모양인 기둥 / 라: 정사각형 6개로 둘러싸인 상자. 직육면체를 모두 고른 것은 어느 것인가요?","options":[{"t":"나, 라","correct":true},{"t":"나","mis":"M5-2-u5-X06"},{"t":"가, 나, 라","mis":"M5-2-u5-X02"},{"t":"나, 다, 라","mis":"M5-2-u5-X02"}],"explanation":["직육면체는 직사각형 6개로 둘러싸인 입체도형이에요.","정사각형도 직사각형이니 정사각형 6개로 둘러싸인 것도 직육면체예요.","정답은 나, 라예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED