INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_a#9','math',5,2,'u5','','tb_g5_2_math_u5_review_a','unit_review','M5-2-u5-C3',2,'mc','auto','직육면체와 정육면체에 대해 친구들이 말했어요. 지우 「직육면체는 직사각형 6개로 둘러싸인 입체도형을 말해요.」 · 윤수 「직육면체는 옆면이 서로 평행해요.」 · 서연 「정육면체는 모서리의 길이가 서로 달라요.」 · 태민 「정육면체는 평행한 면이 모두 3쌍이에요.」 바르게 설명한 친구를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u5-X12','M5-2-u5-X19']::text[],true,'{"seq":9,"concept":"M5-2-u5-C3","difficulty":2,"kind":"mc","stem":"직육면체와 정육면체에 대해 친구들이 말했어요. 지우 「직육면체는 직사각형 6개로 둘러싸인 입체도형을 말해요.」 · 윤수 「직육면체는 옆면이 서로 평행해요.」 · 서연 「정육면체는 모서리의 길이가 서로 달라요.」 · 태민 「정육면체는 평행한 면이 모두 3쌍이에요.」 바르게 설명한 친구를 모두 고른 것은 어느 것인가요?","options":[{"t":"지우, 태민","correct":true},{"t":"지우, 윤수","mis":"M5-2-u5-X12"},{"t":"서연, 태민","mis":"M5-2-u5-X19"},{"t":"지우, 윤수, 태민","mis":"M5-2-u5-X12"}],"explanation":["직육면체는 직사각형 6개, 정육면체는 정사각형 6개로 둘러싸여 있고, 면 6·모서리 12·꼭짓점 8로 수가 같아요.","직육면체의 옆면은 이웃하면 수직이고, 정육면체는 모서리의 길이가 모두 같아요.","바르게 설명한 친구는 지우, 태민이에요."],"variant_rule":{"alt":[{"stem":"직육면체와 정육면체에 대해 친구들이 말했어요. 연희 「정육면체는 면의 크기가 모두 같아요.」 · 세영 「정육면체는 정사각형으로 둘러싸여 있어요.」 · 민지 「정육면체는 모든 모서리의 길이가 달라요.」 바르게 설명한 친구를 모두 고른 것은 어느 것인가요?","options":[{"t":"연희, 세영","correct":true},{"t":"세영, 민지","mis":"M5-2-u5-X19"},{"t":"연희, 민지","mis":"M5-2-u5-X19"},{"t":"연희, 세영, 민지","mis":"M5-2-u5-X19"}],"explanation":["직육면체는 직사각형 6개, 정육면체는 정사각형 6개로 둘러싸여 있고, 면 6·모서리 12·꼭짓점 8로 수가 같아요.","직육면체의 옆면은 이웃하면 수직이고, 정육면체는 모서리의 길이가 모두 같아요.","바르게 설명한 친구는 연희, 세영이에요."]},{"stem":"직육면체와 정육면체에 대해 친구들이 말했어요. 지우 「직육면체와 정육면체는 면, 모서리, 꼭짓점의 수가 각각 같아요.」 · 윤수 「직육면체와 정육면체의 면은 8개로 같아요.」 · 서연 「정육면체는 모서리의 길이가 모두 달라요.」 · 태민 「직육면체는 한 꼭짓점에서 세 모서리가 만나요.」 바르게 설명한 친구를 모두 고른 것은 어느 것인가요?","options":[{"t":"지우, 태민","correct":true},{"t":"지우, 윤수","mis":"M5-2-u5-X05"},{"t":"서연, 태민","mis":"M5-2-u5-X19"},{"t":"윤수, 서연","mis":"M5-2-u5-X05"}],"explanation":["직육면체는 직사각형 6개, 정육면체는 정사각형 6개로 둘러싸여 있고, 면 6·모서리 12·꼭짓점 8로 수가 같아요.","직육면체의 옆면은 이웃하면 수직이고, 정육면체는 모서리의 길이가 모두 같아요.","바르게 설명한 친구는 지우, 태민이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_a#10','math',5,2,'u5','','tb_g5_2_math_u5_review_a','unit_review','M5-2-u5-C6',2,'mc','auto','문제로 마무리 10번 — 이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?',ARRAY['M5-2-u5-X14','M5-2-u5-X02']::text[],true,'{"seq":10,"concept":"M5-2-u5-C6","difficulty":2,"kind":"mc","stem":"문제로 마무리 10번 — 이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?","options":[{"t":"접었을 때 겹치는 면이 있다","correct":true},{"t":"접었을 때 만나는 선분의 길이가 다르다","mis":"M5-2-u5-X14"},{"t":"면이 5개뿐이다","mis":"M5-2-u5-X14"},{"t":"직사각형이 아닌 면이 있다","mis":"M5-2-u5-X02"}],"explanation":["전개도는 면 6개가 겹치지 않게 접혀 직육면체를 둘러싸야 해요.","접은 모양을 떠올려 겹치는 면, 만나는 선분의 길이, 면의 수를 살펴봐요.","까닭은 「접었을 때 겹치는 면이 있다」예요."],"asset":{"type":"geo","items":[{"w":150,"h":60,"seg":[[[0,0],[0,30]],[[0,0],[120,0]],[[0,30],[90,30]],[[90,30],[90,60]],[[90,60],[150,60]],[[120,0],[120,30]],[[120,30],[150,30]],[[150,30],[150,60]]],"dash":[[[30,0],[30,30]],[[60,0],[60,30]],[[90,0],[90,30]],[[90,30],[120,30]],[[120,30],[120,60]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"교과서 117쪽 ⑤의 라 — 이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?","options":[{"t":"접었을 때 만나는 선분의 길이가 다르다","correct":true},{"t":"접었을 때 겹치는 면이 있다","mis":"M5-2-u5-X14"},{"t":"면이 5개뿐이다","mis":"M5-2-u5-X14"},{"t":"직사각형이 아닌 면이 있다","mis":"M5-2-u5-X02"}],"explanation":["전개도는 면 6개가 겹치지 않게 접혀 직육면체를 둘러싸야 해요.","접은 모양을 떠올려 겹치는 면, 만나는 선분의 길이, 면의 수를 살펴봐요.","까닭은 「접었을 때 만나는 선분의 길이가 다르다」예요."],"asset":{"type":"geo","items":[{"w":192,"h":108,"seg":[[[0,36],[0,72]],[[0,36],[60,36]],[[0,72],[156,72]],[[60,0],[60,36]],[[60,0],[96,0]],[[96,0],[96,36]],[[96,36],[192,36]],[[156,72],[156,108]],[[156,108],[192,108]],[[192,36],[192,108]]],"dash":[[[60,36],[60,72]],[[60,36],[96,36]],[[96,36],[96,72]],[[156,36],[156,72]],[[156,72],[192,72]]]}],"tag":false}},{"stem":"교과서 117쪽 ⑤의 마 — 이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?","options":[{"t":"면이 5개뿐이다","correct":true},{"t":"접었을 때 겹치는 면이 있다","mis":"M5-2-u5-X14"},{"t":"접었을 때 만나는 선분의 길이가 다르다","mis":"M5-2-u5-X14"},{"t":"직사각형이 아닌 면이 있다","mis":"M5-2-u5-X02"}],"explanation":["전개도는 면 6개가 겹치지 않게 접혀 직육면체를 둘러싸야 해요.","접은 모양을 떠올려 겹치는 면, 만나는 선분의 길이, 면의 수를 살펴봐요.","까닭은 「면이 5개뿐이다」예요."],"asset":{"type":"geo","items":[{"w":120,"h":60,"seg":[[[0,0],[0,60]],[[0,0],[120,0]],[[0,60],[30,60]],[[30,30],[30,60]],[[30,30],[120,30]],[[120,0],[120,30]]],"dash":[[[0,30],[30,30]],[[30,0],[30,30]],[[60,0],[60,30]],[[90,0],[90,30]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_a#11','math',5,2,'u5','','tb_g5_2_math_u5_review_a','unit_review','M5-2-u5-C3',2,'sa','auto','한 모서리의 길이가 3 cm인 정육면체 모양이에요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M5-2-u5-C3","difficulty":2,"kind":"sa","stem":"한 모서리의 길이가 3 cm인 정육면체 모양이에요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["정육면체는 모서리 12개의 길이가 모두 같아요.","3 × 12 = 36이에요.","그래서 36 cm예요."],"mis":"M5-2-u5-X07","asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33,111],"3 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"과자 상자 — 한 모서리의 길이가 5 cm인 정육면체 모양이에요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["정육면체는 모서리 12개의 길이가 모두 같아요.","5 × 12 = 60이에요.","그래서 60 cm예요."],"asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33,111],"5 cm"]]}],"tag":false}},{"stem":"한 모서리의 길이가 8 cm인 정육면체 모양이에요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["96"],"explanation":["정육면체는 모서리 12개의 길이가 모두 같아요.","8 × 12 = 96이에요.","그래서 96 cm예요."],"asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33,111],"8 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_a#12','math',5,2,'u5','','tb_g5_2_math_u5_review_a','unit_review','M5-2-u5-C4',2,'sa','auto','직육면체의 겨냥도에서 보이는 면, 보이는 모서리, 보이는 꼭짓점의 수의 합은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M5-2-u5-C4","difficulty":2,"kind":"sa","stem":"직육면체의 겨냥도에서 보이는 면, 보이는 모서리, 보이는 꼭짓점의 수의 합은 몇 개인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["보이는 면 3, 모서리 9, 꼭짓점 7이에요.","3 + 9 + 7 = 19예요.","그래서 19개예요."],"mis":"M5-2-u5-X10","asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체의 겨냥도에서 보이지 않는 면과 보이지 않는 꼭짓점의 수의 합은 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["보이지 않는 면 3, 꼭짓점 1이에요.","3 + 1 = 4예요.","그래서 4개예요."],"asset":{"type":"geo","items":[{"w":110.0,"h":66.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,44,"ne"],"ㅇ":[110.0,44,"e"],"ㅂ":[0,66.0,"sw"],"ㅅ":[88,66.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체의 겨냥도에서 실선으로 그린 모서리와 점선으로 그린 모서리의 수의 합은 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["실선 9개, 점선 3개예요.","9 + 3 = 12예요.","그래서 12개예요."],"asset":{"type":"geo","items":[{"w":110.0,"h":66.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,44,"ne"],"ㅇ":[110.0,44,"e"],"ㅂ":[0,66.0,"sw"],"ㅅ":[88,66.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_a#13','math',5,2,'u5','','tb_g5_2_math_u5_review_a','unit_review','M5-2-u5-C5',2,'sa','auto','수학익힘 77쪽에 나온 가로 8 cm, 세로 6 cm, 높이 5 cm인 직육면체예요. 면 ㅁㅂㅅㅇ이 밑면일 때 다른 밑면의 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M5-2-u5-C5","difficulty":2,"kind":"sa","stem":"수학익힘 77쪽에 나온 가로 8 cm, 세로 6 cm, 높이 5 cm인 직육면체예요. 면 ㅁㅂㅅㅇ이 밑면일 때 다른 밑면의 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["다른 밑면은 면 ㄱㄴㄷㄹ이에요.","이 면은 8 cm, 6 cm인 직사각형이에요.","(8 + 6) × 2 = 28이에요."],"mis":"M5-2-u5-X12","asset":{"type":"geo","items":[{"w":143.0,"h":104.0,"pts":{"ㄱ":[39.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,39.0,"w"],"ㄷ":[104,39.0,"sw"],"ㅁ":[39.0,65,"ne"],"ㅇ":[143.0,65,"e"],"ㅂ":[0,104.0,"sw"],"ㅅ":[104,104.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[52.0,112.0],"8 cm"],[[139.5,88.5],"6 cm"],[[86,71.5],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가에 나온 가로 9 cm, 세로 4 cm, 높이 6 cm인 직육면체예요. 면 ㄴㅂㅅㄷ이 밑면일 때 다른 밑면의 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["다른 밑면은 면 ㄱㅁㅇㄹ이에요.","이 면은 9 cm, 6 cm인 직사각형이에요.","(9 + 6) × 2 = 30이에요."],"asset":{"type":"geo","items":[{"w":143.0,"h":104.0,"pts":{"ㄱ":[26.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,26.0,"w"],"ㄷ":[117,26.0,"sw"],"ㅁ":[26.0,78,"ne"],"ㅇ":[143.0,78,"e"],"ㅂ":[0,104.0,"sw"],"ㅅ":[117,104.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"poly":[["ㄴ","ㅂ","ㅅ","ㄷ"]],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[58.5,112.0],"9 cm"],[[146.0,95.0],"4 cm"],[[99,65.0],"6 cm"]]}],"tag":false}},{"stem":"문제로 마무리 8번에 나온 가로 5 cm, 세로 3 cm, 높이 4 cm인 직육면체예요. 면 ㄱㄴㄷㄹ이 밑면일 때 다른 밑면의 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["다른 밑면은 면 ㅁㅂㅅㅇ이에요.","이 면은 5 cm, 3 cm인 직사각형이에요.","(5 + 3) × 2 = 16이에요."],"asset":{"type":"geo","items":[{"w":143.0,"h":121.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[110,33.0,"sw"],"ㅁ":[33.0,88,"ne"],"ㅇ":[143.0,88,"e"],"ㅂ":[0,121.0,"sw"],"ㅅ":[110,121.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"poly":[["ㄱ","ㄴ","ㄷ","ㄹ"]],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[55.0,129.0],"5 cm"],[[142.5,108.5],"3 cm"],[[92,77.0],"4 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_a#14','math',5,2,'u5','','tb_g5_2_math_u5_review_a','unit_review','M5-2-u5-C8',2,'sa','auto','프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 큰 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 4가 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M5-2-u5-C8","difficulty":2,"kind":"sa","stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 큰 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 4가 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["① 4와 평행한 면 3이 보이게 굴려요.","② 3과 수직인 면 1, 2, 5, 6 가운데 가장 큰 수는 6이에요.","그래서 6이 보여요."],"mis":"M5-2-u5-X17","asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 작은 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 1이 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["① 1과 평행한 면 6이 보이게 굴려요.","② 6과 수직인 면 2, 3, 4, 5 가운데 가장 작은 수는 2예요.","그래서 2가 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}},{"stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 큰 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 6이 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["① 6과 평행한 면 1이 보이게 굴려요.","② 1과 수직인 면 2, 3, 4, 5 가운데 가장 큰 수는 5예요.","그래서 5가 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_a#15','math',5,2,'u5','','tb_g5_2_math_u5_review_a','unit_review','M5-2-u5-C7',2,'sa','auto','교과서 120~121쪽 「짜잔! 나만의 전개도」예요. 「똑똑! 수학 탐험대」에서 전개도의 한 면에 ★를 표시했어요. 전개도를 접었을 때 ★로 표시한 면과 수직인 면에 모두 표시하면 몇 개의 면에 표시하게 되나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M5-2-u5-C7","difficulty":2,"kind":"sa","stem":"교과서 120~121쪽 「짜잔! 나만의 전개도」예요. 「똑똑! 수학 탐험대」에서 전개도의 한 면에 ★를 표시했어요. 전개도를 접었을 때 ★로 표시한 면과 수직인 면에 모두 표시하면 몇 개의 면에 표시하게 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["직육면체의 전개도를 접으면 면 6개·모서리 12개가 돼요.","★ 면과 평행한 면 하나를 빼면 6 − 2 = 4(개)예요.","그래서 4예요."],"mis":"M5-2-u5-X13","asset":{"type":"geo","items":[{"w":144,"h":132,"poly":[[[0,48],[24,48],[24,84],[0,84]]],"seg":[[[0,48],[0,84]],[[0,48],[72,48]],[[0,84],[72,84]],[[72,0],[72,48]],[[72,0],[96,0]],[[72,84],[72,132]],[[72,132],[96,132]],[[96,0],[96,48]],[[96,48],[144,48]],[[96,84],[96,132]],[[96,84],[144,84]],[[144,48],[144,84]]],"dash":[[[24,48],[24,84]],[[72,48],[72,84]],[[72,48],[96,48]],[[72,84],[96,84]],[[96,48],[96,84]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"교과서 120~121쪽 「짜잔! 나만의 전개도」예요. 「꾸미기 모드」에서 전개도를 접었을 때 서로 평행한 면을 같은 색으로 칠하려고 해요. 색은 모두 몇 가지가 필요한가요? 숫자로 쓰세요.","answer":["3"],"explanation":["직육면체의 전개도를 접으면 면 6개·모서리 12개가 돼요.","평행한 면이 3쌍이니 한 쌍에 한 가지씩 3가지예요.","그래서 3이에요."],"asset":{"type":"geo","items":[{"w":144,"h":132,"poly":[[[0,48],[24,48],[24,84],[0,84]]],"seg":[[[0,48],[0,84]],[[0,48],[72,48]],[[0,84],[72,84]],[[72,0],[72,48]],[[72,0],[96,0]],[[72,84],[72,132]],[[72,132],[96,132]],[[96,0],[96,48]],[[96,48],[144,48]],[[96,84],[96,132]],[[96,84],[144,84]],[[144,48],[144,84]]],"dash":[[[24,48],[24,84]],[[72,48],[72,84]],[[72,48],[96,48]],[[72,84],[96,84]],[[96,48],[96,84]]]}],"tag":false}},{"stem":"교과서 116쪽 정육면체의 전개도예요. 전개도를 접었을 때 서로 평행한 면은 모두 몇 쌍인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["전개도를 접으면 마주 보는 면은 평행하고, 만나는 면은 수직이에요.","마주 보는 면끼리 평행해요 — 가와 바, 나와 라, 다와 마.","그래서 3이에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[30,60]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,90],[60,90]],[[60,60],[60,90]],[[60,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[30,60],[60,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"가"],[[15.0,40.0],"나"],[[45.0,40.0],"다"],[[75.0,40.0],"라"],[[105.0,40.0],"마"],[[45.0,70.0],"바"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_a#16','math',5,2,'u5','','tb_g5_2_math_u5_review_a','unit_review','M5-2-u5-C7',2,'mc','auto','가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체(교과서 118쪽)의 전개도에서 옆면 4개만 그렸어요. 빠진 부분은 무엇인가요? 모눈 한 칸은 1 cm예요.',ARRAY['M5-2-u5-X20','M5-2-u5-X14']::text[],true,'{"seq":16,"concept":"M5-2-u5-C7","difficulty":2,"kind":"mc","stem":"가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체(교과서 118쪽)의 전개도에서 옆면 4개만 그렸어요. 빠진 부분은 무엇인가요? 모눈 한 칸은 1 cm예요.","options":[{"t":"가로 3 cm, 세로 2 cm인 직사각형 2개","correct":true},{"t":"가로 3 cm, 세로 5 cm인 직사각형 2개","mis":"M5-2-u5-X20"},{"t":"가로 2 cm, 세로 5 cm인 직사각형 1개","mis":"M5-2-u5-X20"},{"t":"가로 3 cm, 세로 2 cm인 직사각형 1개","mis":"M5-2-u5-X14"}],"explanation":["직육면체의 전개도에는 면 6개가 있어요 — 마주 보는 면은 모양과 크기가 같아요.","이미 그린 면이 직육면체의 어느 면인지 가로·세로·높이로 짝 지어 봐요.","빠진 부분은 「가로 3 cm, 세로 2 cm인 직사각형 2개」예요."],"asset":{"type":"geo","items":[{"w":140,"h":98,"seg":[[[0,0],[0,98]],[[0,0],[140,0]],[[0,98],[42,98]],[[42,70],[42,98]],[[42,70],[140,70]],[[140,0],[140,70]]],"dash":[[[0,70],[42,70]],[[42,0],[42,70]],[[70,0],[70,70]],[[112,0],[112,70]]],"grid":14}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 3 cm, 세로 3 cm, 높이 4 cm인 직육면체(교과서 119쪽)의 전개도에서 정사각형 면 1개와 옆면 1개만 그렸어요. 빠진 부분은 무엇인가요? 모눈 한 칸은 1 cm예요.","options":[{"t":"가로 3 cm, 세로 4 cm인 직사각형 3개와 한 변이 3 cm인 정사각형 1개","correct":true},{"t":"가로 3 cm, 세로 4 cm인 직사각형 4개","mis":"M5-2-u5-X20"},{"t":"한 변이 3 cm인 정사각형 4개","mis":"M5-2-u5-X20"},{"t":"가로 3 cm, 세로 4 cm인 직사각형 3개","mis":"M5-2-u5-X14"}],"explanation":["직육면체의 전개도에는 면 6개가 있어요 — 마주 보는 면은 모양과 크기가 같아요.","이미 그린 면이 직육면체의 어느 면인지 가로·세로·높이로 짝 지어 봐요.","빠진 부분은 「가로 3 cm, 세로 4 cm인 직사각형 3개와 한 변이 3 cm인 정사각형 1개」예요."],"asset":null},{"stem":"가로 4 cm, 세로 1 cm, 높이 3 cm인 직육면체(형성 평가)의 전개도에서 가로 4 cm인 면 3개(4 cm × 1 cm, 4 cm × 3 cm, 4 cm × 1 cm)만 이어 그렸어요. 빠진 부분은 무엇인가요? 모눈 한 칸은 1 cm예요.","options":[{"t":"가로 4 cm, 세로 3 cm인 직사각형 1개와 가로 1 cm, 세로 3 cm인 직사각형 2개","correct":true},{"t":"가로 4 cm, 세로 3 cm인 직사각형 3개","mis":"M5-2-u5-X20"},{"t":"가로 1 cm, 세로 3 cm인 직사각형 2개","mis":"M5-2-u5-X14"},{"t":"가로 4 cm, 세로 1 cm인 직사각형 3개","mis":"M5-2-u5-X20"}],"explanation":["직육면체의 전개도에는 면 6개가 있어요 — 마주 보는 면은 모양과 크기가 같아요.","이미 그린 면이 직육면체의 어느 면인지 가로·세로·높이로 짝 지어 봐요.","빠진 부분은 「가로 4 cm, 세로 3 cm인 직사각형 1개와 가로 1 cm, 세로 3 cm인 직사각형 2개」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_a#17','math',5,2,'u5','','tb_g5_2_math_u5_review_a','unit_review','M5-2-u5-C2',3,'sa','auto','문제로 마무리 8번에 나온 가로 5 cm, 세로 3 cm, 높이 4 cm인 직육면체예요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M5-2-u5-C2","difficulty":3,"kind":"sa","stem":"문제로 마무리 8번에 나온 가로 5 cm, 세로 3 cm, 높이 4 cm인 직육면체예요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["직육면체에는 길이가 같은 모서리가 4개씩 3묶음 있어요.","5 × 4 + 3 × 4 + 4 × 4 = 48이에요.","그래서 48 cm예요."],"mis":"M5-2-u5-X07","asset":{"type":"geo","items":[{"w":143.0,"h":121.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[110,33.0,"sw"],"ㅁ":[33.0,88,"ne"],"ㅇ":[143.0,88,"e"],"ㅂ":[0,121.0,"sw"],"ㅅ":[110,121.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[55.0,129.0],"5 cm"],[[142.5,108.5],"3 cm"],[[92,77.0],"4 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"교과서 118쪽에 나온 가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체예요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["직육면체에는 길이가 같은 모서리가 4개씩 3묶음 있어요.","3 × 4 + 2 × 4 + 5 × 4 = 40이에요.","그래서 40 cm예요."],"asset":{"type":"geo","items":[{"w":88.0,"h":132.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[88.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[66,22.0,"sw"],"ㅁ":[22.0,110,"ne"],"ㅇ":[88.0,110,"e"],"ㅂ":[0,132.0,"sw"],"ㅅ":[66,132.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33.0,140.0],"3 cm"],[[93.0,125.0],"2 cm"],[[48,77.0],"5 cm"]]}],"tag":false}},{"stem":"수학익힘 77쪽에 나온 가로 8 cm, 세로 6 cm, 높이 5 cm인 직육면체예요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["76"],"explanation":["직육면체에는 길이가 같은 모서리가 4개씩 3묶음 있어요.","8 × 4 + 6 × 4 + 5 × 4 = 76이에요.","그래서 76 cm예요."],"asset":{"type":"geo","items":[{"w":143.0,"h":104.0,"pts":{"ㄱ":[39.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,39.0,"w"],"ㄷ":[104,39.0,"sw"],"ㅁ":[39.0,65,"ne"],"ㅇ":[143.0,65,"e"],"ㅂ":[0,104.0,"sw"],"ㅅ":[104,104.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[52.0,112.0],"8 cm"],[[139.5,88.5],"6 cm"],[[86,71.5],"5 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_a#18','math',5,2,'u5','','tb_g5_2_math_u5_review_a','unit_review','M5-2-u5-C3',3,'sa','auto','직육면체 모양의 빵(15 cm, 7 cm, 7 cm)을 잘라 만들 수 있는 가장 큰 정육면체의 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M5-2-u5-C3","difficulty":3,"kind":"sa","stem":"직육면체 모양의 빵(15 cm, 7 cm, 7 cm)을 잘라 만들 수 있는 가장 큰 정육면체의 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["정육면체는 모든 모서리의 길이가 같아요.","빵의 가장 짧은 모서리가 7 cm라 더 길게 자를 수 없어요.","그래서 7 cm예요."],"mis":"M5-2-u5-X08","variant_rule":{"alt":[{"stem":"직육면체 모양의 빵(15 cm, 7 cm, 7 cm)을 잘라 가장 큰 정육면체를 만들었을 때 그 정육면체의 모든 모서리의 길이의 합는 몇 cm인가요? 숫자로 쓰세요.","answer":["84"],"explanation":["정육면체는 모든 모서리의 길이가 같아요.","가장 큰 정육면체의 한 모서리는 7 cm이고 7 × 12 = 84예요.","그래서 84 cm예요."]},{"stem":"정육면체의 모든 모서리의 길이의 합이 96 cm예요. 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["정육면체는 모서리 12개의 길이가 모두 같아요.","96 ÷ 12 = 8이에요.","그래서 8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_a#19','math',5,2,'u5','','tb_g5_2_math_u5_review_a','unit_review','M5-2-u5-C4',3,'sa','auto','단원 평가에 나온 가로 4 cm, 세로 8 cm, 높이 6 cm인 직육면체의 겨냥도예요. 보이지 않는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M5-2-u5-C4","difficulty":3,"kind":"sa","stem":"단원 평가에 나온 가로 4 cm, 세로 8 cm, 높이 6 cm인 직육면체의 겨냥도예요. 보이지 않는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["보이지 않는 모서리 3개는 가로, 세로, 높이 하나씩이에요.","4 + 8 + 6 = 18이에요.","그래서 18 cm예요."],"mis":"M5-2-u5-X10","asset":{"type":"geo","items":[{"w":144.0,"h":180.0,"pts":{"ㄱ":[72.0,0,"nw"],"ㄹ":[144.0,0,"ne"],"ㄴ":[0,72.0,"w"],"ㄷ":[72,72.0,"sw"],"ㅁ":[72.0,108,"ne"],"ㅇ":[144.0,108,"e"],"ㅂ":[0,180.0,"sw"],"ㅅ":[72,180.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[36.0,188.0],"4 cm"],[[124.0,148.0],"8 cm"],[[54,126.0],"6 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가에 나온 가로 6 cm, 세로 9 cm, 높이 5 cm인 직육면체의 겨냥도예요. 보이는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["보이는 모서리 9개는 가로, 세로, 높이가 3개씩이에요.","6 × 3 + 9 × 3 + 5 × 3 = 60이에요.","그래서 60 cm예요."],"asset":{"type":"geo","items":[{"w":147.0,"h":133.0,"pts":{"ㄱ":[63.0,0,"nw"],"ㄹ":[147.0,0,"ne"],"ㄴ":[0,63.0,"w"],"ㄷ":[84,63.0,"sw"],"ㅁ":[63.0,70,"ne"],"ㅇ":[147.0,70,"e"],"ㅂ":[0,133.0,"sw"],"ㅅ":[84,133.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[42.0,141.0],"6 cm"],[[131.5,105.5],"9 cm"],[[66,98.0],"5 cm"]]}],"tag":false}},{"stem":"문제로 마무리 8번에 나온 가로 5 cm, 세로 3 cm, 높이 4 cm인 직육면체의 겨냥도예요. 보이지 않는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["보이지 않는 모서리 3개는 가로, 세로, 높이 하나씩이에요.","5 + 3 + 4 = 12예요.","그래서 12 cm예요."],"asset":{"type":"geo","items":[{"w":143.0,"h":121.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[110,33.0,"sw"],"ㅁ":[33.0,88,"ne"],"ㅇ":[143.0,88,"e"],"ㅂ":[0,121.0,"sw"],"ㅅ":[110,121.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[55.0,129.0],"5 cm"],[[142.5,108.5],"3 cm"],[[92,77.0],"4 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_a#20','math',5,2,'u5','','tb_g5_2_math_u5_review_a','unit_review','M5-2-u5-C6',3,'mc','auto','교과서 117쪽 ⑤의 그림 가~바예요. 직육면체의 전개도가 될 수 있는 것을 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u5-X14']::text[],true,'{"seq":20,"concept":"M5-2-u5-C6","difficulty":3,"kind":"mc","stem":"교과서 117쪽 ⑤의 그림 가~바예요. 직육면체의 전개도가 될 수 있는 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 다, 바","correct":true},{"t":"가, 라, 마","mis":"M5-2-u5-X14"},{"t":"나, 마, 바","mis":"M5-2-u5-X14"},{"t":"가, 라, 바","mis":"M5-2-u5-X14"}],"explanation":["그림마다 접은 모양을 떠올려요.","겹치는 면이 있거나 만나는 선분의 길이가 다르거나 면이 모자라면 전개도가 아니에요.","정답은 가, 다, 바예요."],"asset":{"type":"geo","items":[{"w":108,"h":99,"seg":[[[0,36],[0,63]],[[0,36],[54,36]],[[0,63],[54,63]],[[54,0],[54,36]],[[54,0],[72,0]],[[54,63],[54,99]],[[54,99],[72,99]],[[72,0],[72,36]],[[72,36],[108,36]],[[72,63],[72,99]],[[72,63],[108,63]],[[108,36],[108,63]]],"dash":[[[18,36],[18,63]],[[54,36],[54,63]],[[54,36],[72,36]],[[54,63],[72,63]],[[72,36],[72,63]]]},{"w":64,"h":32,"seg":[[[0,0],[0,32]],[[0,0],[16,0]],[[0,32],[64,32]],[[16,0],[16,16]],[[16,16],[48,16]],[[48,0],[48,16]],[[48,0],[64,0]],[[64,0],[64,32]]],"dash":[[[0,16],[16,16]],[[16,16],[16,32]],[[32,16],[32,32]],[[48,16],[48,32]],[[48,16],[64,16]]]},{"w":108,"h":81,"seg":[[[0,18],[0,45]],[[0,18],[54,18]],[[0,45],[36,45]],[[36,45],[36,81]],[[36,81],[54,81]],[[54,0],[54,18]],[[54,0],[90,0]],[[54,45],[54,81]],[[54,45],[108,45]],[[90,0],[90,18]],[[90,18],[108,18]],[[108,18],[108,45]]],"dash":[[[36,18],[36,45]],[[36,45],[54,45]],[[54,18],[54,45]],[[54,18],[90,18]],[[90,18],[90,45]]]},{"w":128,"h":72,"seg":[[[0,24],[0,48]],[[0,24],[40,24]],[[0,48],[104,48]],[[40,0],[40,24]],[[40,0],[64,0]],[[64,0],[64,24]],[[64,24],[128,24]],[[104,48],[104,72]],[[104,72],[128,72]],[[128,24],[128,72]]],"dash":[[[40,24],[40,48]],[[40,24],[64,24]],[[64