INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_a#21','math',5,2,'u5','','tb_g5_2_math_u5_review_a','unit_review','M5-2-u5-C8',3,'sa','auto','프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 작은 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 1이 보이게 놓고 시작해 6번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M5-2-u5-C8","difficulty":3,"kind":"sa","stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 작은 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 1이 보이게 놓고 시작해 6번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["몇 번만 실행해 보면 1 → 2 → 1 → 2 → 1이에요.","2번마다 처음 수로 되풀이돼요.","그래서 6번 실행하면 1이 보여요."],"mis":"M5-2-u5-X17","asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 큰 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 6이 보이게 놓고 시작해 9번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["몇 번만 실행해 보면 6 → 5 → 6 → 5 → 6이에요.","2번마다 처음 수로 되풀이돼요.","그래서 9번 실행하면 5가 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}},{"stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 큰 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 4가 보이게 놓고 시작해 6번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["몇 번만 실행해 보면 4 → 6 → 5 → 6 → 5예요.","2번째부터 2번마다 되풀이돼요.","그래서 6번 실행하면 5가 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_a#22','math',5,2,'u5','','tb_g5_2_math_u5_review_a','unit_review','M5-2-u5-C7',3,'sa','auto','가로 5 cm, 세로 7 cm, 높이 8 cm인 직육면체를 보고 전개도를 그렸어요(단원 평가). 옆면 4개를 한 줄로 이었을 때, 그 줄의 긴 쪽 길이 ㉠은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M5-2-u5-C7","difficulty":3,"kind":"sa","stem":"가로 5 cm, 세로 7 cm, 높이 8 cm인 직육면체를 보고 전개도를 그렸어요(단원 평가). 옆면 4개를 한 줄로 이었을 때, 그 줄의 긴 쪽 길이 ㉠은 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["옆면 4개의 가로는 5, 7, 5, 7 cm예요.","5 + 7 + 5 + 7 = 24예요.","그래서 24 cm예요."],"mis":"M5-2-u5-X20","asset":{"type":"geo","items":[{"w":144.5,"h":195.5,"pts":{"ㄱ":[59.5,0,"nw"],"ㄹ":[144.5,0,"ne"],"ㄴ":[0,59.5,"w"],"ㄷ":[85,59.5,"sw"],"ㅁ":[59.5,136,"ne"],"ㅇ":[144.5,136,"e"],"ㅂ":[0,195.5,"sw"],"ㅅ":[85,195.5,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[42.5,203.5],"5 cm"],[[130.75,169.75],"7 cm"],[[67,127.5],"8 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 5 cm, 세로 7 cm, 높이 8 cm인 직육면체를 보고 전개도를 그렸어요(단원 평가). 옆면의 세로 ㉡은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["옆면의 세로는 직육면체의 높이예요.","높이가 8 cm이니 ㉡ = 8이에요.","그래서 8 cm예요."],"asset":{"type":"geo","items":[{"w":144.5,"h":195.5,"pts":{"ㄱ":[59.5,0,"nw"],"ㄹ":[144.5,0,"ne"],"ㄴ":[0,59.5,"w"],"ㄷ":[85,59.5,"sw"],"ㅁ":[59.5,136,"ne"],"ㅇ":[144.5,136,"e"],"ㅂ":[0,195.5,"sw"],"ㅅ":[85,195.5,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[42.5,203.5],"5 cm"],[[130.75,169.75],"7 cm"],[[67,127.5],"8 cm"]]}],"tag":false}},{"stem":"가로 3 cm, 세로 6 cm, 높이 5 cm인 직육면체의 모서리를 잘라 전개도를 만들었어요(단원 평가). 옆면 4개를 한 줄로 이었을 때, 그 줄의 긴 쪽 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["옆면 4개의 가로는 3, 6, 3, 6 cm예요.","3 + 6 + 3 + 6 = 18이에요.","그래서 18 cm예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":176.0,"pts":{"ㄱ":[66.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,66.0,"w"],"ㄷ":[66,66.0,"sw"],"ㅁ":[66.0,110,"ne"],"ㅇ":[132.0,110,"e"],"ㅂ":[0,176.0,"sw"],"ㅅ":[66,176.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33.0,184.0],"3 cm"],[[115.0,147.0],"6 cm"],[[48,121.0],"5 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_a#23','math',5,2,'u5','','tb_g5_2_math_u5_review_a','unit_review','M5-2-u5-C4',4,'essay','teacher','직육면체의 겨냥도에서 보이지 않는 면, 모서리, 꼭짓점의 수를 각각 쓰고, 왜 그만큼만 보이지 않는지 그림을 보며 설명하세요.','{}'::text[],false,'{"seq":23,"concept":"M5-2-u5-C4","difficulty":4,"kind":"essay","stem":"직육면체의 겨냥도에서 보이지 않는 면, 모서리, 꼭짓점의 수를 각각 쓰고, 왜 그만큼만 보이지 않는지 그림을 보며 설명하세요.","answer_guide":{"answer":"예: 보이지 않는 면은 3개, 모서리는 3개, 꼭짓점은 1개이다. 앞·위·오른쪽 면이 보이고 뒤·아래·왼쪽 면 3개가 가려진다. 가려진 세 면이 함께 만나는 꼭짓점 하나와 그 꼭짓점에서 만나는 모서리 3개만 보이지 않는다.","scoring_points":["면 3·모서리 3·꼭짓점 1을 썼는가","가려진 면 3개를 말했는가","한 꼭짓점과 거기서 만나는 모서리 3개라고 설명했는가"]},"explanation":["보이지 않는 면은 3개예요.","세 면이 함께 만나는 꼭짓점 1개가 가려져요.","그 꼭짓점에서 만나는 모서리 3개가 점선이에요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_a#24','math',5,2,'u5','','tb_g5_2_math_u5_review_a','unit_review','M5-2-u5-C6',4,'essay','teacher','교과서 116쪽 정육면체의 전개도를 접을 때 면 가와 평행한 면과 수직인 면을 모두 찾고, 어떻게 찾았는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u5-C6","difficulty":4,"kind":"essay","stem":"교과서 116쪽 정육면체의 전개도를 접을 때 면 가와 평행한 면과 수직인 면을 모두 찾고, 어떻게 찾았는지 쓰세요.","answer_guide":{"answer":"예: 면 가와 평행한 면은 면 바이고, 수직인 면은 면 나, 면 다, 면 라, 면 마이다. 접어 보면 면 가와 면 바가 서로 마주 보므로 평행하다. 나머지 네 면은 면 가와 만나므로 수직이다.","scoring_points":["평행한 면 바를 찾았는가","수직인 면 나·다·라·마를 찾았는가","마주 보면 평행, 만나면 수직이라고 설명했는가"]},"explanation":["접으면 면 가와 면 바가 마주 봐요.","나머지 네 면은 면 가와 만나요.","마주 보면 평행, 만나면 수직이에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[30,60]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,90],[60,90]],[[60,60],[60,90]],[[60,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[30,60],[60,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"가"],[[15.0,40.0],"나"],[[45.0,40.0],"다"],[[75.0,40.0],"라"],[[105.0,40.0],"마"],[[45.0,70.0],"바"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_a#25','math',5,2,'u5','','tb_g5_2_math_u5_review_a','unit_review','M5-2-u5-C3',4,'sa','auto','한 모서리가 16 cm인 정육면체 모양의 상자를 끈으로 묶었어요. 끈은 상자의 위·아래 면을 가로지르며 열십자로 두 바퀴 둘렀고, 매듭에 쓴 끈은 18 cm예요. 사용한 끈은 모두 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":25,"concept":"M5-2-u5-C3","difficulty":4,"kind":"sa","stem":"한 모서리가 16 cm인 정육면체 모양의 상자를 끈으로 묶었어요. 끈은 상자의 위·아래 면을 가로지르며 열십자로 두 바퀴 둘렀고, 매듭에 쓴 끈은 18 cm예요. 사용한 끈은 모두 몇 cm인가요? 숫자로 쓰세요.","answer":["146"],"explanation":["끈이 한 바퀴 돌 때 한 모서리 길이만큼 4번 지나가요.","두 바퀴이니 16 × 8 = 128이고, 매듭 18 cm를 더해요.","128 + 18 = 146(cm)예요."],"mis":"M5-2-u5-X07","asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가에 나온 가로 9 cm, 세로 7 cm, 높이 3 cm인 직육면체예요. 길이가 7 cm인 모서리의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["직육면체에서 세로와 길이가 같은 모서리는 모두 4개예요.","7 × 4 = 28이에요.","그래서 28 cm예요."],"asset":{"type":"geo","items":[{"w":150.0,"h":78.0,"pts":{"ㄱ":[42.0,0,"nw"],"ㄹ":[150.0,0,"ne"],"ㄴ":[0,42.0,"w"],"ㄷ":[108,42.0,"sw"],"ㅁ":[42.0,36,"ne"],"ㅇ":[150.0,36,"e"],"ㅂ":[0,78.0,"sw"],"ㅅ":[108,78.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[54.0,86.0],"9 cm"],[[145.0,61.0],"7 cm"],[[90,60.0],"3 cm"]]}],"tag":false}},{"stem":"한 모서리가 3 cm인 정육면체와 교과서 119쪽에 나온 가로 3 cm, 세로 3 cm, 높이 4 cm인 직육면체가 있어요. 두 도형의 모든 모서리의 길이의 합의 차는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["정육면체: 3 × 12 = 36이에요.","직육면체: 3 × 4 + 3 × 4 + 4 × 4 = 40이에요.","차는 40 − 36 = 4(cm)예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_b#1','math',5,2,'u5','','tb_g5_2_math_u5_review_b','unit_review','M5-2-u5-C2',1,'mc','auto','형성 평가 그림이에요. 가: 원 모양 면이 있는 통 / 나: 삼각형 면만 있는 뿔 / 다: 정사각형 6개로 둘러싸인 상자 / 라: 삼각형 면이 있는 기둥 / 마: 직사각형 6개로 둘러싸인 상자 / 바: 꼭짓점이 뾰족한 원뿔. 직육면체를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u5-X06','M5-2-u5-X02']::text[],true,'{"seq":1,"concept":"M5-2-u5-C2","difficulty":1,"kind":"mc","stem":"형성 평가 그림이에요. 가: 원 모양 면이 있는 통 / 나: 삼각형 면만 있는 뿔 / 다: 정사각형 6개로 둘러싸인 상자 / 라: 삼각형 면이 있는 기둥 / 마: 직사각형 6개로 둘러싸인 상자 / 바: 꼭짓점이 뾰족한 원뿔. 직육면체를 모두 고른 것은 어느 것인가요?","options":[{"t":"다, 마","correct":true},{"t":"마","mis":"M5-2-u5-X06"},{"t":"다, 라, 마","mis":"M5-2-u5-X02"},{"t":"나, 다, 마","mis":"M5-2-u5-X02"}],"explanation":["직육면체는 직사각형 6개로 둘러싸인 입체도형이에요.","정사각형도 직사각형이니 정사각형 6개로 둘러싸인 것도 직육면체예요.","정답은 다, 마예요."],"variant_rule":{"alt":[{"stem":"교과서 107쪽 그림이에요. 가: 위와 아래가 원 모양인 통 / 나: 직사각형 6개로 둘러싸인 상자 / 다: 위와 아래가 삼각형 모양인 기둥 / 라: 정사각형 6개로 둘러싸인 상자. 직육면체를 모두 고른 것은 어느 것인가요?","options":[{"t":"나, 라","correct":true},{"t":"나","mis":"M5-2-u5-X06"},{"t":"가, 나, 라","mis":"M5-2-u5-X02"},{"t":"나, 다, 라","mis":"M5-2-u5-X02"}],"explanation":["직육면체는 직사각형 6개로 둘러싸인 입체도형이에요.","정사각형도 직사각형이니 정사각형 6개로 둘러싸인 것도 직육면체예요.","정답은 나, 라예요."]},{"stem":"단원 평가 그림이에요. 가: 직사각형 6개로 둘러싸인 납작한 상자 / 나: 삼각형 면이 있는 기둥 / 다: 위가 좁은 사다리꼴 면이 있는 덩어리 / 라: 정사각형 6개로 둘러싸인 상자. 직육면체를 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 라","correct":true},{"t":"가","mis":"M5-2-u5-X06"},{"t":"가, 나, 라","mis":"M5-2-u5-X02"},{"t":"가, 다, 라","mis":"M5-2-u5-X02"}],"explanation":["직육면체는 직사각형 6개로 둘러싸인 입체도형이에요.","정사각형도 직사각형이니 정사각형 6개로 둘러싸인 것도 직육면체예요.","정답은 가, 라예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=