INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_b#7','math',5,2,'u5','','tb_g5_2_math_u5_review_b','unit_review','M5-2-u5-C6',1,'mc','auto','형성 평가의 전개도를 접었을 때 색칠한 면 가와 수직인 면을 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u5-X12','M5-2-u5-X13']::text[],true,'{"seq":7,"concept":"M5-2-u5-C6","difficulty":1,"kind":"mc","stem":"형성 평가의 전개도를 접었을 때 색칠한 면 가와 수직인 면을 모두 고른 것은 어느 것인가요?","options":[{"t":"면 나, 면 다, 면 라, 면 마","correct":true},{"t":"면 나, 면 다, 면 라, 면 바","mis":"M5-2-u5-X12"},{"t":"면 다, 면 라, 면 마, 면 바","mis":"M5-2-u5-X12"},{"t":"면 나, 면 다, 면 바","mis":"M5-2-u5-X13"}],"explanation":["접었을 때 색칠한 면과 마주 보는 면 바 하나만 평행해요.","나머지 4개의 면은 색칠한 면과 수직으로 만나요 — 밑면이면 이 4개가 옆면이에요.","정답은 면 나, 면 다, 면 라, 면 마예요."],"asset":{"type":"geo","items":[{"w":196,"h":140,"poly":[[[126,0],[196,0],[196,28],[126,28]]],"seg":[[[0,28],[0,70]],[[0,28],[126,28]],[[0,70],[98,70]],[[98,70],[98,140]],[[98,140],[126,140]],[[126,0],[126,28]],[[126,0],[196,0]],[[126,70],[126,140]],[[126,70],[196,70]],[[196,0],[196,70]]],"dash":[[[28,28],[28,70]],[[98,28],[98,70]],[[98,70],[126,70]],[[126,28],[126,70]],[[126,28],[196,28]]],"lab":[[[161.0,9.0],"가"],[[14.0,44.0],"나"],[[63.0,44.0],"다"],[[112.0,44.0],"라"],[[161.0,44.0],"마"],[[112.0,100.0],"바"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"교과서 115쪽 상자의 전개도를 접었을 때 색칠한 면 가와 수직인 면을 모두 고른 것은 어느 것인가요?","options":[{"t":"면 나, 면 다, 면 라, 면 마","correct":true},{"t":"면 나, 면 다, 면 라, 면 바","mis":"M5-2-u5-X12"},{"t":"면 다, 면 라, 면 마, 면 바","mis":"M5-2-u5-X12"},{"t":"면 나, 면 다, 면 바","mis":"M5-2-u5-X13"}],"explanation":["접었을 때 색칠한 면과 마주 보는 면 바 하나만 평행해요.","나머지 4개의 면은 색칠한 면과 수직으로 만나요 — 밑면이면 이 4개가 옆면이에요.","정답은 면 나, 면 다, 면 라, 면 마예요."],"asset":{"type":"geo","items":[{"w":180,"h":135,"poly":[[[120,0],[180,0],[180,30],[120,30]]],"seg":[[[0,30],[0,105]],[[0,30],[120,30]],[[0,105],[120,105]],[[120,0],[120,30]],[[120,0],[180,0]],[[120,105],[120,135]]