INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_b#8','math',5,2,'u5','','tb_g5_2_math_u5_review_b','unit_review','M5-2-u5-C7',1,'mc','auto','형성 평가에 나온 가로 2 cm, 세로 3 cm, 높이 4 cm인 직육면체의 전개도를 그리려고 해요. 그려야 하는 면을 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u5-X14','M5-2-u5-X04','M5-2-u5-X20']::text[],true,'{"seq":8,"concept":"M5-2-u5-C7","difficulty":1,"kind":"mc","stem":"형성 평가에 나온 가로 2 cm, 세로 3 cm, 높이 4 cm인 직육면체의 전개도를 그리려고 해요. 그려야 하는 면을 바르게 말한 것은 어느 것인가요?","options":[{"t":"가로 2 cm, 세로 3 cm인 직사각형 2개, 가로 2 cm, 세로 4 cm인 직사각형 2개, 가로 3 cm, 세로 4 cm인 직사각형 2개","correct":true},{"t":"가로 2 cm, 세로 3 cm인 직사각형 6개","mis":"M5-2-u5-X14"},{"t":"가로 2 cm, 세로 4 cm인 직사각형 3개","mis":"M5-2-u5-X04"},{"t":"가로 2 cm, 세로 3 cm인 직사각형 2개, 가로 2 cm, 세로 4 cm인 직사각형 4개","mis":"M5-2-u5-X20"}],"explanation":["직육면체의 면은 6개이고 마주 보는 두 면은 모양과 크기가 같아요.","가로·세로, 가로·높이, 세로·높이로 된 직사각형이 2개씩이에요.","정답은 「가로 2 cm, 세로 3 cm인 직사각형 2개, 가로 2 cm, 세로 4 cm인 직사각형 2개, 가로 3 cm, 세로 4 cm인 직사각형 2개」예요."],"asset":{"type":"geo","items":[{"w":77.0,"h":121.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[77.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[44,33.0,"sw"],"ㅁ":[33.0,88,"ne"],"ㅇ":[77.0,88,"e"],"ㅂ":[0,121.0,"sw"],"ㅅ":[44,121.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[22.0,129.0],"2 cm"],[[76.5,108.5],"3 cm"],[[26,77.0],"4 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가에 나온 가로 4 cm, 세로 2 cm, 높이 3 cm인 직육면체의 전개도를 그리려고 해요. 그려야 하는 면을 바르게 말한 것은 어느 것인가요?","options":[{"t":"가로 4 cm, 세로 2 cm인 직사각형 2개, 가로 4 cm, 세로 3 cm인 직사각형 2개, 가로 2 cm, 세로 3 cm인 직사각형 2개","correct":true},{"t":"가로 4 cm, 세로 2 cm인 직사각형 6개","mis":"M5-2-u5-X14"},{"t":"가로 4 cm, 세로 3 cm인 직사각형 3개","mis":"M5-2-u5-X04"},{"t":"가로 4 cm, 세로 2 cm인 직사각형 2개, 가로 4 cm, 세로 3 cm인 직사각형 4개","mis":"M5-2-u5-X20"}],"explanation":["직육면체의 면은 6개이고 마주 보