INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_c#7','math',5,2,'u5','','tb_g5_2_math_u5_review_c','unit_review','M5-2-u5-C6',1,'mc','auto','교과서 115쪽 상자의 전개도를 접었을 때 색칠한 면 가와 수직인 면을 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u5-X12','M5-2-u5-X13']::text[],true,'{"seq":7,"concept":"M5-2-u5-C6","difficulty":1,"kind":"mc","stem":"교과서 115쪽 상자의 전개도를 접었을 때 색칠한 면 가와 수직인 면을 모두 고른 것은 어느 것인가요?","options":[{"t":"면 나, 면 다, 면 라, 면 마","correct":true},{"t":"면 나, 면 다, 면 라, 면 바","mis":"M5-2-u5-X12"},{"t":"면 다, 면 라, 면 마, 면 바","mis":"M5-2-u5-X12"},{"t":"면 나, 면 다, 면 바","mis":"M5-2-u5-X13"}],"explanation":["접었을 때 색칠한 면과 마주 보는 면 바 하나만 평행해요.","나머지 4개의 면은 색칠한 면과 수직으로 만나요 — 밑면이면 이 4개가 옆면이에요.","정답은 면 나, 면 다, 면 라, 면 마예요."],"asset":{"type":"geo","items":[{"w":180,"h":135,"poly":[[[120,0],[180,0],[180,30],[120,30]]],"seg":[[[0,30],[0,105]],[[0,30],[120,30]],[[0,105],[120,105]],[[120,0],[120,30]],[[120,0],[180,0]],[[120,105],[120,135]],[[120,135],[180,135]],[[180,0],[180,135]]],"dash":[[[30,30],[30,105]],[[90,30],[90,105]],[[120,30],[120,105]],[[120,30],[180,30]],[[120,105],[180,105]]],"lab":[[[150.0,10.0],"가"],[[15.0,62.5],"나"],[[60.0,62.5],"다"],[[105.0,62.5],"라"],[[150.0,62.5],"마"],[[150.0,115.0],"바"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"교과서 116쪽 정육면체의 전개도를 접었을 때 색칠한 면 가가 밑면이면 옆면을 모두 고른 것은 어느 것인가요?","options":[{"t":"면 나, 면 다, 면 라, 면 마","correct":true},{"t":"면 나, 면 다, 면 라, 면 바","mis":"M5-2-u5-X12"},{"t":"면 다, 면 라, 면 마, 면 바","mis":"M5-2-u5-X12"},{"t":"면 나, 면 다, 면 바","mis":"M5-2-u5-X13"}],"explanation":["접었을 때 색칠한 면과 마주 보는 면 바 하나만 평행해요.","나머지 4개의 면은 색칠한 면과 수직으로 만나요 — 밑면이면 이 4개가 옆면이에요.","정답은 면 나, 면 다, 면 라, 면 마예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"poly":[[[0,0],[30,0],[30,30],[0,30]]],"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[30,60]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,90],[60,90]],[[60,60],[60,90]],[[60,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[30,60],[60,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"가"],[[15.0,40.0],"나"],[[45.0,40.0],"다"],[[75.0,40.0],"라"],[[105.0,40.0],"마"],[[45.0,70.0],"바"]]}],"tag":false}},{"stem":"문제로 마무리 7번 — 전개도를 접었을 때 색칠한 면 바가 밑면이면 옆면을 모두 고른 것은 어느 것인가요?","options":[{"t":"면 나, 면 다, 면 라, 면 마","correct":true},{"t":"면 가, 면 나, 면 다, 면 라","mis":"M5-2-u5-X12"},{"t":"면 가, 면 다, 면 라, 면 마","mis":"M5-2-u5-X12"},{"t":"면 가, 면 나, 면 다","mis":"M5-2-u5-X13"}],"explanation":["접었을 때 색칠한 면과 마주 보는 면 가 하나만 평행해요.","나머지 4개의 면은 색칠한 면과 수직으로 만나요 — 밑면이면 이 4개가 옆면이에요.","정답은 면 나, 면 다, 면 라, 면 마예요."],"asset":{"type":"geo","items":[{"w":180,"h":135,"poly":[[[60,75],[90,75],[90,135],[60,135]]],"seg":[[[0,30],[0,75]],[[0,30],[90,30]],[[0,75],[60,75]],[[60,75],[60,135]],[[60,135],[90,135]],[[90,0],[90,30]],[[90,0],[150,0]],[[90,75],[90,135]],[[90,75],[180,75]],[[150,0],[150,30]],[[150,30],[180,30]],[[180,30],[180,75]]],"dash":[[[60,30],[60,75]],[[60,75],[90,75]],[[90,30],[90,75]],[[90,30],[150,30]],[[150,30],[150,75]]],"lab":[[[120.0,10.0],"가"],[[30.0,47.5],"나"],[[75.0,47.5],"다"],[[120.0,47.5],"라"],[[165.0,47.5],"마"],[[75.0,100.0],"바"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_c#8','math',5,2,'u5','','tb_g5_2_math_u5_review_c','unit_review','M5-2-u5-C7',1,'mc','auto','단원 평가에 나온 가로 4 cm, 세로 2 cm, 높이 3 cm인 직육면체의 전개도를 그리려고 해요. 그려야 하는 면을 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u5-X14','M5-2-u5-X04','M5-2-u5-X20']::text[],true,'{"seq":8,"concept":"M5-2-u5-C7","difficulty":1,"kind":"mc","stem":"단원 평가에 나온 가로 4 cm, 세로 2 cm, 높이 3 cm인 직육면체의 전개도를 그리려고 해요. 그려야 하는 면을 바르게 말한 것은 어느 것인가요?","options":[{"t":"가로 4 cm, 세로 2 cm인 직사각형 2개, 가로 4 cm, 세로 3 cm인 직사각형 2개, 가로 2 cm, 세로 3 cm인 직사각형 2개","correct":true},{"t":"가로 4 cm, 세로 2 cm인 직사각형 6개","mis":"M5-2-u5-X14"},{"t":"가로 4 cm, 세로 3 cm인 직사각형 3개","mis":"M5-2-u5-X04"},{"t":"가로 4 cm, 세로 2 cm인 직사각형 2개, 가로 4 cm, 세로 3 cm인 직사각형 4개","mis":"M5-2-u5-X20"}],"explanation":["직육면체의 면은 6개이고 마주 보는 두 면은 모양과 크기가 같아요.","가로·세로, 가로·높이, 세로·높이로 된 직사각형이 2개씩이에요.","정답은 「가로 4 cm, 세로 2 cm인 직사각형 2개, 가로 4 cm, 세로 3 cm인 직사각형 2개, 가로 2 cm, 세로 3 cm인 직사각형 2개」예요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[44.0,96.0],"4 cm"],[[115.0,81.0],"2 cm"],[[70,55.0],"3 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가에 나온 가로 2 cm, 세로 3 cm, 높이 3 cm인 직육면체의 전개도를 그리려고 해요. 그려야 하는 면을 바르게 말한 것은 어느 것인가요?","options":[{"t":"가로 2 cm, 세로 3 cm인 직사각형 2개, 가로 2 cm, 세로 3 cm인 직사각형 2개, 가로 3 cm, 세로 3 cm인 직사각형 2개","correct":true},{"t":"가로 2 cm, 세로 3 cm인 직사각형 6개","mis":"M5-2-u5-X14"},{"t":"가로 2 cm, 세로 3 cm인 직사각형 3개","mis":"M5-2-u5-X04"},{"t":"가로 2 cm, 세로 3 cm인 직사각형 2개, 가로 2 cm, 세로 3 cm인 직사각형 4개","mis":"M5-2-u5-X20"}],"explanation":["직육면체의 면은 6개이고 마주 보는