INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_c#21','math',5,2,'u5','','tb_g5_2_math_u5_review_c','unit_review','M5-2-u5-C8',3,'sa','auto','프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 큰 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 4가 보이게 놓고 시작해 6번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M5-2-u5-C8","difficulty":3,"kind":"sa","stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 큰 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 4가 보이게 놓고 시작해 6번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["몇 번만 실행해 보면 4 → 6 → 5 → 6 → 5예요.","2번째부터 2번마다 되풀이돼요.","그래서 6번 실행하면 5가 보여요."],"mis":"M5-2-u5-X17","asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 큰 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 2가 보이게 놓고 시작해 7번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["몇 번만 실행해 보면 2 → 6 → 5 → 6 → 5예요.","2번째부터 2번마다 되풀이돼요.","그래서 7번 실행하면 6이 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}},{"stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 작은 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 1이 보이게 놓고 시작해 6번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["몇 번만 실행해 보면 1 → 2 → 1 → 2 → 1이에요.","2번마다 처음 수로 되풀이돼요.","그래서 6번 실행하면 1이 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_c#22','math',5,2,'u5','','tb_g5_2_math_u5_review_c','unit_review','M5-2-u5-C7',3,'sa','auto','가로 3 cm, 세로 6 cm, 높이 5 cm인 직육면체의 모서리를 잘라 전개도를 만들었어요(단원 평가). 옆면 4개를 한 줄로 이었을 때, 그 줄의 긴 쪽 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M5-2-u5-C7","difficulty":3,"kind":"sa","stem":"가로 3 cm, 세로 6 cm, 높이 5 cm인 직육면체의 모서리를 잘라 전개도를 만들었어요(단원 평가). 옆면 4개를 한 줄로 이었을 때, 그 줄의 긴 쪽 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["옆면 4개의 가로는 3, 6, 3, 6 cm예요.","3 + 6 + 3 + 6 = 18이에요.","그래서 18 cm예요."],"mis":"M5-2-u5-X20","asset":{"type":"geo","items":[{"w":132.0,"h":176.0,"pts":{"ㄱ":[66.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,66.0,"w"],"ㄷ":[66,66.0,"sw"],"ㅁ":[66.0,110,"ne"],"ㅇ":[132.0,110,"e"],"ㅂ":[0,176.0,"sw"],"ㅅ":[66,176.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33.0,184.0],"3 cm"],[[115.0,147.0],"6 cm"],[[48,121.0],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가에 나온 가로 7 cm, 세로 3 cm인 직육면체의 모든 모서리의 길이의 합이 56 cm예요. 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["길이가 같은 모서리가 4개씩이니 가로·세로·높이 하나씩의 합은 56 ÷ 4 = 14예요.","높이는 14 − 7 − 3 = 4예요.","그래서 4 cm예요."],"asset":null},{"stem":"가로 5 cm, 세로 7 cm, 높이 8 cm인 직육면체를 보고 전개도를 그렸어요(단원 평가). 옆면 4개를 한 줄로 이었을 때, 그 줄의 긴 쪽 길이 ㉠은 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["옆면 4개의 가로는 5, 7, 5, 7 cm예요.","5 + 7 + 5 + 7 = 24예요.","그래서 24 cm예요."],"asset":{"type":"geo","items":[{"w":144.5,"h":195.5,"pts":{"ㄱ":[59.5,0,"nw"],"ㄹ":[144.5,0,"ne"],"ㄴ":[0,59.5,"w"],"ㄷ":[85,59.5,"sw"],"ㅁ":[59.5,136,"ne"],"ㅇ":[144.5,136,"e"],"ㅂ":[0,195.5,"sw"],"ㅅ":[85,195.5,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[42.5,203.5],"5 cm"],[[130.75,169.75],"7 cm"],[[67,127.5],"8 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_c#23','math',5,2,'u5','','tb_g5_2_math_u5_review_c','unit_review','M5-2-u5-C5',4,'essay','teacher','삼촌네 과일 가게에서 상자를 눕혀 놓은 것을 보고 순달이가 「바닥에 닿은 면이 아니니까 옆에 선 두 면은 밑면이 될 수 없어.」라고 했어요. 이 말이 맞는지 판단하고, 밑면과 옆면의 뜻을 넣어 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M5-2-u5-C5","difficulty":4,"kind":"essay","stem":"삼촌네 과일 가게에서 상자를 눕혀 놓은 것을 보고 순달이가 「바닥에 닿은 면이 아니니까 옆에 선 두 면은 밑면이 될 수 없어.」라고 했어요. 이 말이 맞는지 판단하고, 밑면과 옆면의 뜻을 넣어 까닭을 쓰세요.","answer_guide":{"answer":"예: 이 말은 틀렸다. 밑면은 놓인 위치가 아니라 계속 늘여도 만나지 않는 서로 평행한 두 면을 말한다. 옆에 선 두 면도 서로 평행하므로 밑면이 될 수 있다. 그때 이 두 면과 수직으로 만나는 나머지 4개의 면이 옆면이 된다.","scoring_points":["틀렸다고 판단했는가","밑면은 서로 평행한 두 면이라고 썼는가","옆면은 밑면과 수직인 면 4개라고 썼는가"]},"explanation":["밑면은 위치가 아니라 평행한 관계로 정해요.","옆에 선 두 면도 평행하면 밑면이에요.","밑면과 수직인 4개의 면이 옆면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_c#24','math',5,2,'u5','','tb_g5_2_math_u5_review_c','unit_review','M5-2-u5-C6',4,'essay','teacher','교과서 117쪽 ⑤의 나예요. 친구가 「면이 6개니까 직육면체의 전개도야.」라고 했어요. 친구의 말이 맞는지 판단하고, 전개도가 되려면 무엇을 따져 보아야 하는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u5-C6","difficulty":4,"kind":"essay","stem":"교과서 117쪽 ⑤의 나예요. 친구가 「면이 6개니까 직육면체의 전개도야.」라고 했어요. 친구의 말이 맞는지 판단하고, 전개도가 되려면 무엇을 따져 보아야 하는지 쓰세요.","answer_guide":{"answer":"예: 친구의 말은 틀렸다. 이 그림은 접었을 때 양쪽 위의 두 면이 같은 자리에서 겹치고 한쪽은 비므로 전개도가 아니다. 전개도가 되려면 면의 수뿐 아니라 접었을 때 겹치는 면이 없는지, 만나는 두 선분의 길이가 같은지를 따져 보아야 한다.","scoring_points":["틀렸다고 판단했는가","접었을 때 겹치는 면이 있다고 썼는가","겹치는 면·만나는 선분의 길이를 따져야 한다고 썼는가"]},"explanation":["접은 모양을 떠올려요.","위쪽에 붙은 두 면이 같은 자리에서 겹쳐요.","면의 수뿐 아니라 겹침과 만나는 선분의 길이를 따져요."],"asset":{"type":"geo","items":[{"w":120,"h":60,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[120,60]],[[30,0],[30,30]],[[30,30],[90,30]],[[90,0],[90,30]],[[90,0],[120,0]],[[120,0],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]],[[90,30],[120,30]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_c#25','math',5,2,'u5','','tb_g5_2_math_u5_review_c','unit_review','M5-2-u5-C3',4,'sa','auto','한 모서리가 3 cm인 정육면체와 교과서 119쪽에 나온 가로 3 cm, 세로 3 cm, 높이 4 cm인 직육면체가 있어요. 두 도형의 모든 모서리의 길이의 합의 차는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":25,"concept":"M5-2-u5-C3","difficulty":4,"kind":"sa","stem":"한 모서리가 3 cm인 정육면체와 교과서 119쪽에 나온 가로 3 cm, 세로 3 cm, 높이 4 cm인 직육면체가 있어요. 두 도형의 모든 모서리의 길이의 합의 차는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["정육면체: 3 × 12 = 36이에요.","직육면체: 3 × 4 + 3 × 4 + 4 × 4 = 40이에요.","차는 40 − 36 = 4(cm)예요."],"mis":"M5-2-u5-X07","variant_rule":{"alt":[{"stem":"단원 평가에 나온 가로 6 cm, 세로 9 cm, 높이 5 cm인 직육면체의 겨냥도예요. 보이는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["보이는 모서리 9개는 가로, 세로, 높이가 3개씩이에요.","6 × 3 + 9 × 3 + 5 × 3 = 60이에요.","그래서 60 cm예요."],"asset":{"type":"geo","items":[{"w":147.0,"h":133.0,"pts":{"ㄱ":[63.0,0,"nw"],"ㄹ":[147.0,0,"ne"],"ㄴ":[0,63.0,"w"],"ㄷ":[84,63.0,"sw"],"ㅁ":[63.0,70,"ne"],"ㅇ":[147.0,70,"e"],"ㅂ":[0,133.0,"sw"],"ㅅ":[84,133.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[42.0,141.0],"6 cm"],[[131.5,105.5],"9 cm"],[[66,98.0],"5 cm"]]}],"tag":false}},{"stem":"한 모서리가 16 cm인 정육면체 모양의 상자를 끈으로 묶었어요. 끈은 상자의 위·아래 면을 가로지르며 열십자로 두 바퀴 둘렀고, 매듭에 쓴 끈은 18 cm예요. 사용한 끈은 모두 몇 cm인가요? 숫자로 쓰세요.","answer":["146"],"explanation":["끈이 한 바퀴 돌 때 한 모서리 길이만큼 4번 지나가요.","두 바퀴이니 16 × 8 = 128이고, 매듭 18 cm를 더해요.","128 + 18 = 146(cm)예요."],"asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_d#1','math',5,2,'u5','','tb_g5_2_math_u5_review_d','unit_review','M5-2-u5-C2',1,'mc','auto','단원 평가 그림이에요. 가: 직사각형 6개로 둘러싸인 납작한 상자 / 나: 삼각형 면이 있는 기둥 / 다: 위가 좁은 사다리꼴 면이 있는 덩어리 / 라: 정사각형 6개로 둘러싸인 상자. 직육면체를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u5-X06','M5-2-u5-X02']::text[],true,'{"seq":1,"concept":"M5-2-u5-C2","difficulty":1,"kind":"mc","stem":"단원 평가 그림이에요. 가: 직사각형 6개로 둘러싸인 납작한 상자 / 나: 삼각형 면이 있는 기둥 / 다: 위가 좁은 사다리꼴 면이 있는 덩어리 / 라: 정사각형 6개로 둘러싸인 상자. 직육면체를 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 라","correct":true},{"t":"가","mis":"M5-2-u5-X06"},{"t":"가, 나, 라","mis":"M5-2-u5-X02"},{"t":"가, 다, 라","mis":"M5-2-u5-X02"}],"explanation":["직육면체는 직사각형 6개로 둘러싸인 입체도형이에요.","정사각형도 직사각형이니 정사각형 6개로 둘러싸인 것도 직육면체예요.","정답은 가, 라예요."],"variant_rule":{"alt":[{"stem":"문제로 마무리 1번의 물건이에요. 가: 면이 모두 직사각형인 휴지 상자 / 나: 양쪽 면이 사다리꼴인 과자 상자 / 다: 삼각형 면이 있는 샌드위치 상자 / 라: 면이 모두 직사각형인 지우개. 직육면체 모양을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 라","correct":true},{"t":"가","mis":"M5-2-u5-X18"},{"t":"가, 나, 라","mis":"M5-2-u5-X02"},{"t":"가, 다, 라","mis":"M5-2-u5-X02"}],"explanation":["직육면체는 직사각형 6개로 둘러싸인 입체도형이에요.","정사각형도 직사각형이니 정사각형 6개로 둘러싸인 것도 직육면체예요.","정답은 가, 라예요."]},{"stem":"형성 평가 그림이에요. 가: 원 모양 면이 있는 통 / 나: 삼각형 면만 있는 뿔 / 다: 정사각형 6개로 둘러싸인 상자 / 라: 삼각형 면이 있는 기둥 / 마: 직사각형 6개로 둘러싸인 상자 / 바: 꼭짓점이 뾰족한 원뿔. 직육면체를 모두 고른 것은 어느 것인가요?","options":[{"t":"다, 마","correct":true},{"t":"마","mis":"M5-2-u5-X06"},{"t":"다, 라, 마","mis":"M5-2-u5-X02"},{"t":"나, 다, 마","mis":"M5-2-u5-X02"}],"explanation":["직육면체는 직사각형 6개로 둘러싸인 입체도형이에요.","정사각형도 직사각형이니 정사각형 6개로 둘러싸인 것도 직육면체예요.","정답은 다, 마예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_d#2','math',5,2,'u5','','tb_g5_2_math_u5_review_d','unit_review','M5-2-u5-C2',1,'mc','auto','단원 평가(심화)예요. 정육면체에서 「면과 면이 만나는 선분」의 이름은 무엇인가요?',ARRAY['M5-2-u5-X03','M5-2-u5-X16']::text[],true,'{"seq":2,"concept":"M5-2-u5-C2","difficulty":1,"kind":"mc","stem":"단원 평가(심화)예요. 정육면체에서 「면과 면이 만나는 선분」의 이름은 무엇인가요?","options":[{"t":"모서리","correct":true},{"t":"꼭짓점","mis":"M5-2-u5-X03"},{"t":"면","mis":"M5-2-u5-X03"},{"t":"겨냥도","mis":"M5-2-u5-X16"}],"explanation":["직육면체를 둘러싼 직사각형 부분은 면이에요.","면과 면이 만나는 선분은 모서리, 모서리와 모서리가 만나는 점은 꼭짓점이에요.","정답은 「모서리」예요."],"asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"문제로 마무리 2번이에요. 직육면체에서 화살표가 가리키는 「면과 면이 만나는 선분」의 이름은 무엇인가요?","options":[{"t":"모서리","correct":true},{"t":"꼭짓점","mis":"M5-2-u5-X03"},{"t":"면","mis":"M5-2-u5-X03"},{"t":"밑면","mis":"M5-2-u5-X11"}],"explanation":["직육면체를 둘러싼 직사각형 부분은 면이에요.","면과 면이 만나는 선분은 모서리, 모서리와 모서리가 만나는 점은 꼭짓점이에요.","정답은 「모서리」예요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"형성 평가예요. 직육면체에서 「모서리와 모서리가 만나는 점」의 이름은 무엇인가요?","options":[{"t":"꼭짓점","correct":true},{"t":"모서리","mis":"M5-2-u5-X03"},{"t":"면","mis":"M5-2-u5-X03"},{"t":"옆면","mis":"M5-2-u5-X11"}],"explanation":["직육면체를 둘러싼 직사각형 부분은 면이에요.","면과 면이 만나는 선분은 모서리, 모서리와 모서리가 만나는 점은 꼭짓점이에요.","정답은 「꼭짓점」이에요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
