INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_d#4','math',5,2,'u5','','tb_g5_2_math_u5_review_d','unit_review','M5-2-u5-C4',1,'mc','auto','형성 평가의 겨냥도예요. 이 겨냥도가 잘못된 까닭은 어느 것인가요?',ARRAY['M5-2-u5-X09','M5-2-u5-X10']::text[],true,'{"seq":4,"concept":"M5-2-u5-C4","difficulty":1,"kind":"mc","stem":"형성 평가의 겨냥도예요. 이 겨냥도가 잘못된 까닭은 어느 것인가요?","options":[{"t":"보이는 모서리를 점선으로, 보이지 않는 모서리를 실선으로 그렸다","correct":true},{"t":"보이지 않는 모서리를 그리지 않았다","mis":"M5-2-u5-X09"},{"t":"모서리를 13개 그렸다","mis":"M5-2-u5-X10"},{"t":"잘못된 곳이 없다","mis":"M5-2-u5-X10"}],"explanation":["겨냥도는 보이는 모서리를 실선, 보이지 않는 모서리를 점선으로 그려요.","이 그림은 실선과 점선이 서로 바뀌었어요.","정답은 「보이는 모서리를 점선으로, 보이지 않는 모서리를 실선으로 그렸다」예요."],"asset":{"type":"geo","items":[{"w":154.0,"h":110.0,"pts":{"ㄱ":[44.0,0,"nw"],"ㄹ":[154.0,0,"ne"],"ㄴ":[0,44.0,"w"],"ㄷ":[110,44.0,"sw"],"ㅁ":[44.0,66,"ne"],"ㅇ":[154.0,66,"e"],"ㅂ":[0,110.0,"sw"],"ㅅ":[110,110.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄴ","ㄷ"],["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"문제로 마무리 4번의 겨냥도예요. 잘못된 부분을 모두 바르게 말한 것은 어느 것인가요?","options":[{"t":"보이지 않는 모서리 하나를 실선으로, 보이는 모서리 하나를 점선으로 그렸다","correct":true},{"t":"보이지 않는 모서리 하나를 실선으로 그렸다","mis":"M5-2-u5-X09"},{"t":"보이는 모서리 하나를 점선으로 그렸다","mis":"M5-2-u5-X10"},{"t":"잘못된 곳이 없다","mis":"M5-2-u5-X09"}],"explanation":["겨냥도는 보이는 모서리를 실선, 보이지 않는 모서리를 점선으로 그려요.","그림에서 실선과 점선이 바뀐 곳을 하나씩 찾아봐요.","정답은 「보이지 않는 모서리 하나를 실선으로, 보이는 모서리 하나를 점선으로 그렸다」예요."],"asset":{"type":"geo","items":[{"w":154.0,"h":110.0,"pts":{"ㄱ":[44.0,0,"nw"],"ㄹ":[154.0,0,"ne"],"ㄴ":[0,44.0,"w"],"ㄷ":[110,44.0,"sw"],"ㅁ":[44.0,66,"ne"],"ㅇ":[154.0,66,"e"],"ㅂ":[0,110.0,"sw"],"ㅅ":[110,110.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅅ","ㅇ"],["ㅁ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅂ","ㅅ