INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_d#7','math',5,2,'u5','','tb_g5_2_math_u5_review_d','unit_review','M5-2-u5-C6',1,'mc','auto','교과서 116쪽 정육면체의 전개도를 접었을 때 색칠한 면 가가 밑면이면 옆면을 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u5-X12','M5-2-u5-X13']::text[],true,'{"seq":7,"concept":"M5-2-u5-C6","difficulty":1,"kind":"mc","stem":"교과서 116쪽 정육면체의 전개도를 접었을 때 색칠한 면 가가 밑면이면 옆면을 모두 고른 것은 어느 것인가요?","options":[{"t":"면 나, 면 다, 면 라, 면 마","correct":true},{"t":"면 나, 면 다, 면 라, 면 바","mis":"M5-2-u5-X12"},{"t":"면 다, 면 라, 면 마, 면 바","mis":"M5-2-u5-X12"},{"t":"면 나, 면 다, 면 바","mis":"M5-2-u5-X13"}],"explanation":["접었을 때 색칠한 면과 마주 보는 면 바 하나만 평행해요.","나머지 4개의 면은 색칠한 면과 수직으로 만나요 — 밑면이면 이 4개가 옆면이에요.","정답은 면 나, 면 다, 면 라, 면 마예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"poly":[[[0,0],[30,0],[30,30],[0,30]]],"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[30,60]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,90],[60,90]],[[60,60],[60,90]],[[60,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[30,60],[60,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"가"],[[15.0,40.0],"나"],[[45.0,40.0],"다"],[[75.0,40.0],"라"],[[105.0,40.0],"마"],[[45.0,70.0],"바"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"문제로 마무리 7번 — 전개도를 접었을 때 색칠한 면 바가 밑면이면 옆면을 모두 고른 것은 어느 것인가요?","options":[{"t":"면 나, 면 다, 면 라, 면 마","correct":true},{"t":"면 가, 면 나, 면 다, 면 라","mis":"M5-2-u5-X12"},{"t":"면 가, 면 다, 면 라, 면 마","mis":"M5-2-u5-X12"},{"t":"면 가, 면 나, 면 다","mis":"M5-2-u5-X13"}],"explanation":["접었을 때 색칠한 면과 마주 보는 면 가 하나만 평행해요.","나머지 4개의 면은 색칠한 면과 수직으로 만나요 — 밑면이면 이 4개가 옆면이에요.","정답은 면 나, 면 다, 면 라, 면 마예요."],"asset":{"type":"geo","items":[{"w":180,"h":135,"poly":[[[60,75],[90,75],[90,135],[60,135]]],"seg":[[[0,30],[0,75]],[[0,30],[90,30]],[[0,75],[60,75]],[[60,75],[60,135]],[[60,135],[90,135]],[[90,0],[90,30]],[[90,0],[150,