INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_d#9','math',5,2,'u5','','tb_g5_2_math_u5_review_d','unit_review','M5-2-u5-C3',2,'mc','auto','직육면체에 대해 친구들이 말했어요. 태민 「면 ㄱㄴㄷㄹ과 평행한 면은 면 ㅁㅂㅅㅇ이에요.」 · 지우 「면 ㄷㅅㅇㄹ을 밑면이라고 하면 옆면은 4개예요.」 · 윤수 「면 ㄴㅂㅅㄷ은 밑면이 될 수 없어요.」 바르게 설명한 친구를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u5-X11']::text[],true,'{"seq":9,"concept":"M5-2-u5-C3","difficulty":2,"kind":"mc","stem":"직육면체에 대해 친구들이 말했어요. 태민 「면 ㄱㄴㄷㄹ과 평행한 면은 면 ㅁㅂㅅㅇ이에요.」 · 지우 「면 ㄷㅅㅇㄹ을 밑면이라고 하면 옆면은 4개예요.」 · 윤수 「면 ㄴㅂㅅㄷ은 밑면이 될 수 없어요.」 바르게 설명한 친구를 모두 고른 것은 어느 것인가요?","options":[{"t":"태민, 지우","correct":true},{"t":"태민, 윤수","mis":"M5-2-u5-X11"},{"t":"지우, 윤수","mis":"M5-2-u5-X11"},{"t":"태민, 지우, 윤수","mis":"M5-2-u5-X11"}],"explanation":["마주 보는 면끼리 평행하고 평행한 두 면은 어느 쌍이든 밑면이 될 수 있어요.","밑면이 정해지면 그와 수직인 4개의 면이 옆면이에요.","바르게 설명한 친구는 태민, 지우예요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체와 정육면체에 대해 친구들이 말했어요. 지우 「직육면체는 직사각형 6개로 둘러싸인 입체도형을 말해요.」 · 윤수 「직육면체는 옆면이 서로 평행해요.」 · 서연 「정육면체는 모서리의 길이가 서로 달라요.」 · 태민 「정육면체는 평행한 면이 모두 3쌍이에요.」 바르게 설명한 친구를 모두 고른 것은 어느 것인가요?","options":[{"t":"지우, 태민","correct":true},{"t":"지우, 윤수","mis":"M5-2-u5-X12"},{"t":"서연, 태민","mis":"M5-2-u5-X19"},{"t":"지우, 윤수, 태민","mis":"M5-2-u5-X12"}],"explanation":["직육면체는 직사각형 6개, 정육면체는 정사각형 6개로 둘러싸여 있고, 면 6·모서리 12·꼭짓점 8로 수가 같아요.","직육면체의 옆면은 이웃하면 수직이고, 정육면체는 모서리의 길이가 모두 같아요.","바르게 설명한 친구는 지우, 태민이에요."],"asset":null},{"stem":"직육면체와 정육면체에 대해 친구들이 말했어요. 연희 「정육면체는 면의 크기가 모두 같아요.」 · 세영 「정육면체는 정사각형으로 둘러싸여 있어요.」 · 민지 「정육면체는 모든 모서리의 길이가 달라요.」 바르게 설명한 친구를 모두 고른 것은 어느 것인가요?","options":[{"t":"연희, 세영","correct":true},{"t":"세영, 민지","mis":"M5-2-u5-X19"},{"t":"연희, 민지","mis":"M5-2-u5-X19"},{"t":"연희, 세영, 민지","mis":"M5-2-u5-X19"}],"explanation":["직육면체는 직사각형 6개, 정육면체는 정사각형 6개로 둘러싸여 있고, 면 6·모서리 12·꼭짓점 8로 수가 같아요.","직육면체의 옆면은 이웃하면 수직이고, 정육면체는 모서리의 길이가 모두 같아요.","바르게 설명한 친구는 연희, 세영이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
