INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_d#11','math',5,2,'u5','','tb_g5_2_math_u5_review_d','unit_review','M5-2-u5-C3',2,'sa','auto','끈으로 묶은 상자 — 한 모서리의 길이가 16 cm인 정육면체 모양이에요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M5-2-u5-C3","difficulty":2,"kind":"sa","stem":"끈으로 묶은 상자 — 한 모서리의 길이가 16 cm인 정육면체 모양이에요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["192"],"explanation":["정육면체는 모서리 12개의 길이가 모두 같아요.","16 × 12 = 192예요.","그래서 192 cm예요."],"mis":"M5-2-u5-X07","asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33,111],"16 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"한 모서리의 길이가 3 cm인 정육면체 모양이에요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["정육면체는 모서리 12개의 길이가 모두 같아요.","3 × 12 = 36이에요.","그래서 36 cm예요."],"asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33,111],"3 cm"]]}],"tag":false}},{"stem":"과자 상자 — 한 모서리의 길이가 5 cm인 정육면체 모양이에요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["정육면체는 모서리 12개의 길이가 모두 같아요.","5 × 12 = 60이에요.","그래서 60 cm예요."],"asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33,111],"5 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_d#12','math',5,2,'u5','','tb_g5_2_math_u5_review_d','unit_review','M5-2-u5-C4',2,'sa','auto','직육면체의 겨냥도에서 보이는 모서리와 보이지 않는 꼭짓점의 수의 차는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M5-2-u5-C4","difficulty":2,"kind":"sa","stem":"직육면체의 겨냥도에서 보이는 모서리와 보이지 않는 꼭짓점의 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["보이는 것은 면 3, 모서리 9, 꼭짓점 7 — 보이지 않는 것은 면 3, 모서리 3, 꼭짓점 1이에요.","9 − 1 = 8이에요.","그래서 8개예요."],"mis":"M5-2-u5-X10","asset":{"type":"geo","items":[{"w":121.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[121.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[88,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[121.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[88,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체의 겨냥도에서 보이는 면, 보이는 모서리, 보이는 꼭짓점의 수의 합은 몇 개인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["보이는 면 3, 모서리 9, 꼭짓점 7이에요.","3 + 9 + 7 = 19예요.","그래서 19개예요."],"asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체의 겨냥도에서 보이지 않는 면과 보이지 않는 꼭짓점의 수의 합은 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["보이지 않는 면 3, 꼭짓점 1이에요.","3 + 1 = 4예요.","그래서 4개예요."],"asset":{"type":"geo","items":[{"w":110.0,"h":66.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,44,"ne"],"ㅇ":[110.0,44,"e"],"ㅂ":[0,66.0,"sw"],"ㅅ":[88,66.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_d#13','math',5,2,'u5','','tb_g5_2_math_u5_review_d','unit_review','M5-2-u5-C5',2,'sa','auto','교과서 118쪽에 나온 가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체예요. 면 ㄷㅅㅇㄹ이 밑면일 때 다른 밑면의 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":13,"concept":"M5-2-u5-C5","difficulty":2,"kind":"sa","stem":"교과서 118쪽에 나온 가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체예요. 면 ㄷㅅㅇㄹ이 밑면일 때 다른 밑면의 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["다른 밑면은 면 ㄴㅂㅁㄱ이에요.","이 면은 2 cm, 5 cm인 직사각형이에요.","(2 + 5) × 2 = 14예요."],"mis":"M5-2-u5-X12","asset":{"type":"geo","items":[{"w":88.0,"h":132.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[88.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[66,22.0,"sw"],"ㅁ":[22.0,110,"ne"],"ㅇ":[88.0,110,"e"],"ㅂ":[0,132.0,"sw"],"ㅅ":[66,132.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"poly":[["ㄷ","ㅅ","ㅇ","ㄹ"]],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33.0,140.0],"3 cm"],[[93.0,125.0],"2 cm"],[[48,77.0],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"수학익힘 77쪽에 나온 가로 8 cm, 세로 6 cm, 높이 5 cm인 직육면체예요. 면 ㅁㅂㅅㅇ이 밑면일 때 다른 밑면의 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["다른 밑면은 면 ㄱㄴㄷㄹ이에요.","이 면은 8 cm, 6 cm인 직사각형이에요.","(8 + 6) × 2 = 28이에요."],"asset":{"type":"geo","items":[{"w":143.0,"h":104.0,"pts":{"ㄱ":[39.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,39.0,"w"],"ㄷ":[104,39.0,"sw"],"ㅁ":[39.0,65,"ne"],"ㅇ":[143.0,65,"e"],"ㅂ":[0,104.0,"sw"],"ㅅ":[104,104.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"poly":[["ㅁ","ㅂ","ㅅ","ㅇ"]],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[52.0,112.0],"8 cm"],[[139.5,88.5],"6 cm"],[[86,71.5],"5 cm"]]}],"tag":false}},{"stem":"단원 평가에 나온 가로 9 cm, 세로 4 cm, 높이 6 cm인 직육면체예요. 면 ㄴㅂㅅㄷ이 밑면일 때 다른 밑면의 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["다른 밑면은 면 ㄱㅁㅇㄹ이에요.","이 면은 9 cm, 6 cm인 직사각형이에요.","(9 + 6) × 2 = 30이에요."],"asset":{"type":"geo","items":[{"w":143.0,"h":104.0,"pts":{"ㄱ":[26.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,26.0,"w"],"ㄷ":[117,26.0,"sw"],"ㅁ":[26.0,78,"ne"],"ㅇ":[143.0,78,"e"],"ㅂ":[0,104.0,"sw"],"ㅅ":[117,104.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"poly":[["ㄴ","ㅂ","ㅅ","ㄷ"]],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[58.5,112.0],"9 cm"],[[146.0,95.0],"4 cm"],[[99,65.0],"6 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_d#14','math',5,2,'u5','','tb_g5_2_math_u5_review_d','unit_review','M5-2-u5-C8',2,'sa','auto','프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 작은 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 2가 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M5-2-u5-C8","difficulty":2,"kind":"sa","stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 작은 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 2가 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["① 2와 평행한 면 5가 보이게 굴려요.","② 5와 수직인 면 1, 3, 4, 6 가운데 가장 작은 수는 1이에요.","그래서 1이 보여요."],"mis":"M5-2-u5-X17","asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 큰 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 4가 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["① 4와 평행한 면 3이 보이게 굴려요.","② 3과 수직인 면 1, 2, 5, 6 가운데 가장 큰 수는 6이에요.","그래서 6이 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}},{"stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 작은 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 1이 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["① 1과 평행한 면 6이 보이게 굴려요.","② 6과 수직인 면 2, 3, 4, 5 가운데 가장 작은 수는 2예요.","그래서 2가 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_d#15','math',5,2,'u5','','tb_g5_2_math_u5_review_d','unit_review','M5-2-u5-C6',2,'sa','auto','교과서 116쪽 정육면체의 전개도예요. 전개도를 접었을 때 면 가와 수직인 면은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M5-2-u5-C6","difficulty":2,"kind":"sa","stem":"교과서 116쪽 정육면체의 전개도예요. 전개도를 접었을 때 면 가와 수직인 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["전개도를 접으면 마주 보는 면은 평행하고, 만나는 면은 수직이에요.","평행한 면 바를 뺀 나머지 6 − 2 = 4(개)예요.","그래서 4예요."],"mis":"M5-2-u5-X13","asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[30,60]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,90],[60,90]],[[60,60],[60,90]],[[60,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[30,60],[60,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"가"],[[15.0,40.0],"나"],[[45.0,40.0],"다"],[[75.0,40.0],"라"],[[105.0,40.0],"마"],[[45.0,70.0],"바"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"교과서 120~121쪽 「짜잔! 나만의 전개도」예요. 「똑똑! 수학 탐험대」에서 전개도의 한 면에 ★를 표시했어요. 전개도를 접었을 때 ★로 표시한 면과 수직인 면에 모두 표시하면 몇 개의 면에 표시하게 되나요? 숫자로 쓰세요.","answer":["4"],"explanation":["직육면체의 전개도를 접으면 면 6개·모서리 12개가 돼요.","★ 면과 평행한 면 하나를 빼면 6 − 2 = 4(개)예요.","그래서 4예요."],"asset":{"type":"geo","items":[{"w":144,"h":132,"poly":[[[0,48],[24,48],[24,84],[0,84]]],"seg":[[[0,48],[0,84]],[[0,48],[72,48]],[[0,84],[72,84]],[[72,0],[72,48]],[[72,0],[96,0]],[[72,84],[72,132]],[[72,132],[96,132]],[[96,0],[96,48]],[[96,48],[144,48]],[[96,84],[96,132]],[[96,84],[144,84]],[[144,48],[144,84]]],"dash":[[[24,48],[24,84]],[[72,48],[72,84]],[[72,48],[96,48]],[[72,84],[96,84]],[[96,48],[96,84]]]}],"tag":false}},{"stem":"교과서 120~121쪽 「짜잔! 나만의 전개도」예요. 「꾸미기 모드」에서 전개도를 접었을 때 서로 평행한 면을 같은 색으로 칠하려고 해요. 색은 모두 몇 가지가 필요한가요? 숫자로 쓰세요.","answer":["3"],"explanation":["직육면체의 전개도를 접으면 면 6개·모서리 12개가 돼요.","평행한 면이 3쌍이니 한 쌍에 한 가지씩 3가지예요.","그래서 3이에요."],"asset":{"type":"geo","items":[{"w":144,"h":132,"poly":[[[0,48],[24,48],[24,84],[0,84]]],"seg":[[[0,48],[0,84]],[[0,48],[72,48]],[[0,84],[72,84]],[[72,0],[72,48]],[[72,0],[96,0]],[[72,84],[72,132]],[[72,132],[96,132]],[[96,0],[96,48]],[[96,48],[144,48]],[[96,84],[96,132]],[[96,84],[144,84]],[[144,48],[144,84]]],"dash":[[[24,48],[24,84]],[[72,48],[72,84]],[[72,48],[96,48]],[[72,84],[96,84]],[[96,48],[96,84]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_d#16','math',5,2,'u5','','tb_g5_2_math_u5_review_d','unit_review','M5-2-u5-C7',2,'mc','auto','교과서 119쪽 — 한 모서리가 3 cm인 정육면체의 전개도를 그리려고 해요. 그려야 하는 면은 어느 것인가요?',ARRAY['M5-2-u5-X19','M5-2-u5-X04','M5-2-u5-X14']::text[],true,'{"seq":16,"concept":"M5-2-u5-C7","difficulty":2,"kind":"mc","stem":"교과서 119쪽 — 한 모서리가 3 cm인 정육면체의 전개도를 그리려고 해요. 그려야 하는 면은 어느 것인가요?","options":[{"t":"한 변이 3 cm인 정사각형 6개","correct":true},{"t":"가로 3 cm, 세로 6 cm인 직사각형 6개","mis":"M5-2-u5-X19"},{"t":"한 변이 3 cm인 정사각형 4개","mis":"M5-2-u5-X04"},{"t":"한 변이 3 cm인 정사각형 5개","mis":"M5-2-u5-X14"}],"explanation":["정육면체의 면은 모두 크기가 같은 정사각형이에요.","한 모서리가 3 cm이니 한 변이 3 cm인 정사각형이에요.","면이 6개니 6개를 그려요."],"variant_rule":{"alt":[{"stem":"가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체(교과서 118쪽)의 전개도에서 옆면 4개만 그렸어요. 빠진 부분은 무엇인가요? 모눈 한 칸은 1 cm예요.","options":[{"t":"가로 3 cm, 세로 2 cm인 직사각형 2개","correct":true},{"t":"가로 3 cm, 세로 5 cm인 직사각형 2개","mis":"M5-2-u5-X20"},{"t":"가로 2 cm, 세로 5 cm인 직사각형 1개","mis":"M5-2-u5-X20"},{"t":"가로 3 cm, 세로 2 cm인 직사각형 1개","mis":"M5-2-u5-X14"}],"explanation":["직육면체의 전개도에는 면 6개가 있어요 — 마주 보는 면은 모양과 크기가 같아요.","이미 그린 면이 직육면체의 어느 면인지 가로·세로·높이로 짝 지어 봐요.","빠진 부분은 「가로 3 cm, 세로 2 cm인 직사각형 2개」예요."],"asset":{"type":"geo","items":[{"w":140,"h":98,"seg":[[[0,0],[0,98]],[[0,0],[140,0]],[[0,98],[42,98]],[[42,70],[42,98]],[[42,70],[140,70]],[[140,0],[140,70]]],"dash":[[[0,70],[42,70]],[[42,0],[42,70]],[[70,0],[70,70]],[[112,0],[112,70]]],"grid":14}],"tag":false}},{"stem":"가로 3 cm, 세로 3 cm, 높이 4 cm인 직육면체(교과서 119쪽)의 전개도에서 정사각형 면 1개와 옆면 1개만 그렸어요. 빠진 부분은 무엇인가요? 모눈 한 칸은 1 cm예요.","options":[{"t":"가로 3 cm, 세로 4 cm인 직사각형 3개와 한 변이 3 cm인 정사각형 1개","correct":true},{"t":"가로 3 cm, 세로 4 cm인 직사각형 4개","mis":"M5-2-u5-X20"},{"t":"한 변이 3 cm인 정사각형 4개","mis":"M5-2-u5-X20"},{"t":"가로 3 cm, 세로 4 cm인 직사각형 3개","mis":"M5-2-u5-X14"}],"explanation":["직육면체의 전개도에는 면 6개가 있어요 — 마주 보는 면은 모양과 크기가 같아요.","이미 그린 면이 직육면체의 어느 면인지 가로·세로·높이로 짝 지어 봐요.","빠진 부분은 「가로 3 cm, 세로 4 cm인 직사각형 3개와 한 변이 3 cm인 정사각형 1개」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_d#17','math',5,2,'u5','','tb_g5_2_math_u5_review_d','unit_review','M5-2-u5-C2',3,'sa','auto','단원 평가에 나온 가로 4 cm, 세로 8 cm, 높이 6 cm인 직육면체예요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M5-2-u5-C2","difficulty":3,"kind":"sa","stem":"단원 평가에 나온 가로 4 cm, 세로 8 cm, 높이 6 cm인 직육면체예요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["직육면체에는 길이가 같은 모서리가 4개씩 3묶음 있어요.","4 × 4 + 8 × 4 + 6 × 4 = 72예요.","그래서 72 cm예요."],"mis":"M5-2-u5-X07","asset":{"type":"geo","items":[{"w":144.0,"h":180.0,"pts":{"ㄱ":[72.0,0,"nw"],"ㄹ":[144.0,0,"ne"],"ㄴ":[0,72.0,"w"],"ㄷ":[72,72.0,"sw"],"ㅁ":[72.0,108,"ne"],"ㅇ":[144.0,108,"e"],"ㅂ":[0,180.0,"sw"],"ㅅ":[72,180.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[36.0,188.0],"4 cm"],[[124.0,148.0],"8 cm"],[[54,126.0],"6 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"문제로 마무리 8번에 나온 가로 5 cm, 세로 3 cm, 높이 4 cm인 직육면체예요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["직육면체에는 길이가 같은 모서리가 4개씩 3묶음 있어요.","5 × 4 + 3 × 4 + 4 × 4 = 48이에요.","그래서 48 cm예요."],"asset":{"type":"geo","items":[{"w":143.0,"h":121.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[110,33.0,"sw"],"ㅁ":[33.0,88,"ne"],"ㅇ":[143.0,88,"e"],"ㅂ":[0,121.0,"sw"],"ㅅ":[110,121.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[55.0,129.0],"5 cm"],[[142.5,108.5],"3 cm"],[[92,77.0],"4 cm"]]}],"tag":false}},{"stem":"교과서 118쪽에 나온 가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체예요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["직육면체에는 길이가 같은 모서리가 4개씩 3묶음 있어요.","3 × 4 + 2 × 4 + 5 × 4 = 40이에요.","그래서 40 cm예요."],"asset":{"type":"geo","items":[{"w":88.0,"h":132.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[88.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[66,22.0,"sw"],"ㅁ":[22.0,110,"ne"],"ㅇ":[88.0,110,"e"],"ㅂ":[0,132.0,"sw"],"ㅅ":[66,132.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33.0,140.0],"3 cm"],[[93.0,125.0],"2 cm"],[[48,77.0],"5 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_d#18','math',5,2,'u5','','tb_g5_2_math_u5_review_d','unit_review','M5-2-u5-C3',3,'sa','auto','정육면체의 모든 모서리의 길이의 합이 96 cm예요. 한 면의 넓이는 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M5-2-u5-C3","difficulty":3,"kind":"sa","stem":"정육면체의 모든 모서리의 길이의 합이 96 cm예요. 한 면의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["한 모서리의 길이는 96 ÷ 12 = 8(cm)예요.","정육면체의 면은 한 변이 8 cm인 정사각형이에요.","넓이는 8 × 8 = 64(cm²)예요."],"mis":"M5-2-u5-X07","variant_rule":{"alt":[{"stem":"직육면체 모양의 빵(15 cm, 7 cm, 7 cm)을 잘라 만들 수 있는 가장 큰 정육면체의 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["정육면체는 모든 모서리의 길이가 같아요.","빵의 가장 짧은 모서리가 7 cm라 더 길게 자를 수 없어요.","그래서 7 cm예요."]},{"stem":"직육면체 모양의 빵(15 cm, 7 cm, 7 cm)을 잘라 가장 큰 정육면체를 만들었을 때 그 정육면체의 모든 모서리의 길이의 합는 몇 cm인가요? 숫자로 쓰세요.","answer":["84"],"explanation":["정육면체는 모든 모서리의 길이가 같아요.","가장 큰 정육면체의 한 모서리는 7 cm이고 7 × 12 = 84예요.","그래서 84 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_d#19','math',5,2,'u5','','tb_g5_2_math_u5_review_d','unit_review','M5-2-u5-C4',3,'sa','auto','교과서 118쪽에 나온 가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체의 겨냥도예요. 보이는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":19,"concept":"M5-2-u5-C4","difficulty":3,"kind":"sa","stem":"교과서 118쪽에 나온 가로 3 cm, 세로 2 cm, 높이 5 cm인 직육면체의 겨냥도예요. 보이는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["보이는 모서리 9개는 가로, 세로, 높이가 3개씩이에요.","3 × 3 + 2 × 3 + 5 × 3 = 30이에요.","그래서 30 cm예요."],"mis":"M5-2-u5-X10","asset":{"type":"geo","items":[{"w":88.0,"h":132.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[88.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[66,22.0,"sw"],"ㅁ":[22.0,110,"ne"],"ㅇ":[88.0,110,"e"],"ㅂ":[0,132.0,"sw"],"ㅅ":[66,132.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33.0,140.0],"3 cm"],[[93.0,125.0],"2 cm"],[[48,77.0],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"단원 평가에 나온 가로 4 cm, 세로 8 cm, 높이 6 cm인 직육면체의 겨냥도예요. 보이지 않는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["보이지 않는 모서리 3개는 가로, 세로, 높이 하나씩이에요.","4 + 8 + 6 = 18이에요.","그래서 18 cm예요."],"asset":{"type":"geo","items":[{"w":144.0,"h":180.0,"pts":{"ㄱ":[72.0,0,"nw"],"ㄹ":[144.0,0,"ne"],"ㄴ":[0,72.0,"w"],"ㄷ":[72,72.0,"sw"],"ㅁ":[72.0,108,"ne"],"ㅇ":[144.0,108,"e"],"ㅂ":[0,180.0,"sw"],"ㅅ":[72,180.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[36.0,188.0],"4 cm"],[[124.0,148.0],"8 cm"],[[54,126.0],"6 cm"]]}],"tag":false}},{"stem":"단원 평가에 나온 가로 6 cm, 세로 9 cm, 높이 5 cm인 직육면체의 겨냥도예요. 보이는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["보이는 모서리 9개는 가로, 세로, 높이가 3개씩이에요.","6 × 3 + 9 × 3 + 5 × 3 = 60이에요.","그래서 60 cm예요."],"asset":{"type":"geo","items":[{"w":147.0,"h":133.0,"pts":{"ㄱ":[63.0,0,"nw"],"ㄹ":[147.0,0,"ne"],"ㄴ":[0,63.0,"w"],"ㄷ":[84,63.0,"sw"],"ㅁ":[63.0,70,"ne"],"ㅇ":[147.0,70,"e"],"ㅂ":[0,133.0,"sw"],"ㅅ":[84,133.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[42.0,141.0],"6 cm"],[[131.5,105.5],"9 cm"],[[66,98.0],"5 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_d#20','math',5,2,'u5','','tb_g5_2_math_u5_review_d','unit_review','M5-2-u5-C6',3,'mc','auto','문제로 마무리 10번의 그림 가~다예요. 직육면체의 전개도가 될 수 없는 것을 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u5-X14']::text[],true,'{"seq":20,"concept":"M5-2-u5-C6","difficulty":3,"kind":"mc","stem":"문제로 마무리 10번의 그림 가~다예요. 직육면체의 전개도가 될 수 없는 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"가","correct":true},{"t":"나","mis":"M5-2-u5-X14"},{"t":"다","mis":"M5-2-u5-X14"},{"t":"가, 다","mis":"M5-2-u5-X14"}],"explanation":["그림마다 접은 모양을 떠올려요.","겹치는 면이 있거나 만나는 선분의 길이가 다르거나 면이 모자라면 전개도가 아니에요.","정답은 가예요."],"asset":{"type":"geo","items":[{"w":80,"h":32,"seg":[[[0,0],[0,16]],[[0,0],[64,0]],[[0,16],[48,16]],[[48,16],[48,32]],[[48,32],[80,32]],[[64,0],[64,16]],[[64,16],[80,16]],[[80,16],[80,32]]],"dash":[[[16,0],[16,16]],[[32,0],[32,16]],[[48,0],[48,16]],[[48,16],[64,16]],[[64,16],[64,32]]]},{"w":64,"h":48,"seg":[[[0,32],[0,48]],[[0,32],[16,32]],[[0,48],[32,48]],[[16,16],[16,32]],[[16,16],[32,16]],[[32,0],[32,16]],[[32,0],[64,0]],[[32,32],[32,48]],[[32,32],[48,32]],[[48,16],[48,32]],[[48,16],[64,16]],[[64,0],[64,16]]],"dash":[[[16,32],[16,48]],[[16,32],[32,32]],[[32,16],[32,32]],[[32,16],[48,16]],[[48,0],[48,16]]]},{"w":64,"h":48,"seg":[[[0,16],[0,32]],[[0,16],[16,16]],[[0,32],[32,32]],[[16,0],[16,16]],[[16,0],[32,0]],[[32,0],[32,16]],[[32,16],[64,16]],[[32,32],[32,48]],[[32,48],[48,48]],[[48,32],[48,48]],[[48,32],[64,32]],[[64,16],[64,32]]],"dash":[[[16,16],[16,32]],[[16,16],[32,16]],[[32,16],[32,32]],[[32,32],[48,32]],[[48,16],[48,32]]]}],"tag":true},"variant_rule":{"alt":[{"stem":"교과서 117쪽 ⑤의 그림 가~바예요. 직육면체의 전개도가 될 수 있는 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 다, 바","correct":true},{"t":"가, 라, 마","mis":"M5-2-u5-X14"},{"t":"나, 마, 바","mis":"M5-2-u5-X14"},{"t":"가, 라, 바","mis":"M5-2-u5-X14"}],"explanation":["그림마다 접은 모양을 떠올려요.","겹치는 면이 있거나 만나는 선분의 길이가 다르거나 면이 모자라면 전개도가 아니에요.","정답은 가, 다, 바예요."],"asset":{"type":"geo","items":[{"w":108,"h":99,"seg":[[[0,36],[0,63]],[[0,36],[54,36]],[[0,63],[54,63]],[[54,0],[54,36]],[[54,0],[72,0]],[[54,63],[54,99]],[[54,99],[72,99]],[[72,0],[72,36]],[[72,36],[108,36]],[[72,63],[72,99]],[[72,63],[108,63]],[[108,36],[108,63]]],"dash":[[[18,36],[18,63]],[[54,36],[54,63]],[[54,36],[72,36]],[[54,63],[72,63]],[[72,36],[72,63]]]},{"w":64,"h":32,"seg":[[[0,0],[0,32]],[[0,0],[16,0]],[[0,32],[64,32]],[[16,0],[16,16]],[[16,16],[48,16]],[[48,0],[48,16]],[[48,0],[64,0]],[[64,0],[64,32]]],"dash":[[[0,16],[16,16]],[[16,16],[16,32]],[[32,16],[32,32]],[[48,16],[48,32]],[[48,16],[64,16]]]},{"w":108,"h":81,"seg":[[[0,18],[0,45]],[[0,18],[54,18]],[[0,45],[36,45]],[[36,45],[36,81]],[[36,81],[54,81]],[[54,0],[54,18]],[[54,0],[90,0]],[[54,45],[54,81]],[[54,45],[108,45]],[[90,0],[90,18]],[[90,18],[108,18]],[[108,18],[108,45]]],"dash":[[[36,18],[36,45]],[[36,45],[54,45]],[[54,18],[54,45]],[[54,18],[90,18]],[[90,18],[90,45]]]},{"w":128,"h":72,"seg":[[[0,24],[0,48]],[[0,24],[40,24]],[[0,48],[104,48]],[[40,0],[40,24]],[[40,0],[64,0]],[[64,0],[64,24]],[[64,24],[128,24]],[[104,48],[104,72]],[[104,72],[128,72]],[[128,24],[128,72]]],"dash":[[[40,24],[40,48]],[[40,24],[64,24]],[[64,24],[64,48]],[[104,24],[104,48]],[[104,48],[128,48]]]},{"w":64,"h":32,"seg":[[[0,0],[0,32]],[[0,0],[64,0]],[[0,32],[16,32]],[[16,16],[16,32]],[[16,16],[64,16]],[[64,0],[64,16]]],"dash":[[[0,16],[16,16]],[[16,0],[16,16]],[[32,0],[32,16]],[[48,0],[48,16]]]},{"w":80,"h":32,"seg":[[[0,0],[0,16]],[[0,0],[48,0]],[[0,16],[32,16]],[[32,16],[32,32]],[[32,32],[80,32]],[[48,0],[48,16]],[[48,16],[80,16]],[[80,16],[80,32]]],"dash":[[[16,0],[16,16]],[[32,0],[32,16]],[[32,16],[48,16]],[[48,16],[48,32]],[[64,16],[64,32]]]}],"tag":true}},{"stem":"형성 평가의 그림 가~다예요. 정육면체의 전개도가 될 수 없는 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"나, 다","correct":true},{"t":"가, 다","mis":"M5-2-u5-X14"},{"t":"가, 나","mis":"M5-2-u5-X14"},{"t":"나","mis":"M5-2-u5-X14"}],"explanation":["그림마다 접은 모양을 떠올려요.","겹치는 면이 있거나 만나는 선분의 길이가 다르거나 면이 모자라면 전개도가 아니에요.","정답은 나, 다예요."],"asset":{"type":"geo","items":[{"w":80,"h":32,"seg":[[[0,0],[0,16]],[[0,0],[48,0]],[[0,16],[32,16]],[[32,16],[32,32]],[[32,32],[80,32]],[[48,0],[48,16]],[[48,16],[80,16]],[[80,16],[80,32]]],"dash":[[[16,0],[16,16]],[[32,0],[32,16]],[[32,16],[48,16]],[[48,16],[48,32]],[[64,16],[64,32]]]},{"w":80,"h":32,"seg":[[[0,0],[0,16]],[[0,0],[80,0]],[[0,16],[16,16]],[[16,16],[16,32]],[[16,32],[32,32]],[[32,16],[32,32]],[[32,16],[80,16]],[[80,0],[80,16]]],"dash":[[[16,0],[16,16]],[[16,16],[32,16]],[[32,0],[32,16]],[[48,0],[48,16]],[[64,0],[64,16]]]},{"w":64,"h":32,"seg":[[[0,0],[0,32]],[[0,0],[16,0]],[[0,32],[64,32]],[[16,0],[16,16]],[[16,16],[48,16]],[[48,0],[48,16]],[[48,0],[64,0]],[[64,0],[64,32]]],"dash":[[[0,16],[16,16]],[[16,16],[16,32]],[[32,16],[32,32]],[[48,16],[48,32]],[[48,16],[64,16]]]}],"tag":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_d#21','math',5,2,'u5','','tb_g5_2_math_u5_review_d','unit_review','M5-2-u5-C8',3,'sa','auto','프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 큰 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 2가 보이게 놓고 시작해 7번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M5-2-u5-C8","difficulty":3,"kind":"sa","stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 큰 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 2가 보이게 놓고 시작해 7번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["몇 번만 실행해 보면 2 → 6 → 5 → 6 → 5예요.","2번째부터 2번마다 되풀이돼요.","그래서 7번 실행하면 6이 보여요."],"mis":"M5-2-u5-X17","asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 작은 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 1이 보이게 놓고 시작해 6번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["몇 번만 실행해 보면 1 → 2 → 1 → 2 → 1이에요.","2번마다 처음 수로 되풀이돼요.","그래서 6번 실행하면 1이 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}},{"stem":"프로그램 — 「시작하기」를 누르면 [보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 큰 면이 보이게 굴리기]를 반복하고 주사위를 보여 줍니다(대괄호 안 두 명령을 1번으로 셉니다). 주사위의 전개도를 보고, 눈의 수 6이 보이게 놓고 시작해 9번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["몇 번만 실행해 보면 6 → 5 → 6 → 5 → 6이에요.","2번마다 처음 수로 되풀이돼요.","그래서 9번 실행하면 5가 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_d#22','math',5,2,'u5','','tb_g5_2_math_u5_review_d','unit_review','M5-2-u5-C2',3,'sa','auto','단원 평가에 나온 가로 7 cm, 세로 3 cm인 직육면체의 모든 모서리의 길이의 합이 56 cm예요. 높이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M5-2-u5-C2","difficulty":3,"kind":"sa","stem":"단원 평가에 나온 가로 7 cm, 세로 3 cm인 직육면체의 모든 모서리의 길이의 합이 56 cm예요. 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["길이가 같은 모서리가 4개씩이니 가로·세로·높이 하나씩의 합은 56 ÷ 4 = 14예요.","높이는 14 − 7 − 3 = 4예요.","그래서 4 cm예요."],"mis":"M5-2-u5-X07","variant_rule":{"alt":[{"stem":"가로 5 cm, 세로 7 cm, 높이 8 cm인 직육면체를 보고 전개도를 그렸어요(단원 평가). 옆면 4개를 한 줄로 이었을 때, 그 줄의 긴 쪽 길이 ㉠은 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["옆면 4개의 가로는 5, 7, 5, 7 cm예요.","5 + 7 + 5 + 7 = 24예요.","그래서 24 cm예요."],"asset":{"type":"geo","items":[{"w":144.5,"h":195.5,"pts":{"ㄱ":[59.5,0,"nw"],"ㄹ":[144.5,0,"ne"],"ㄴ":[0,59.5,"w"],"ㄷ":[85,59.5,"sw"],"ㅁ":[59.5,136,"ne"],"ㅇ":[144.5,136,"e"],"ㅂ":[0,195.5,"sw"],"ㅅ":[85,195.5,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[42.5,203.5],"5 cm"],[[130.75,169.75],"7 cm"],[[67,127.5],"8 cm"]]}],"tag":false}},{"stem":"가로 5 cm, 세로 7 cm, 높이 8 cm인 직육면체를 보고 전개도를 그렸어요(단원 평가). 옆면의 세로 ㉡은 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["옆면의 세로는 직육면체의 높이예요.","높이가 8 cm이니 ㉡ = 8이에요.","그래서 8 cm예요."],"asset":{"type":"geo","items":[{"w":144.5,"h":195.5,"pts":{"ㄱ":[59.5,0,"nw"],"ㄹ":[144.5,0,"ne"],"ㄴ":[0,59.5,"w"],"ㄷ":[85,59.5,"sw"],"ㅁ":[59.5,136,"ne"],"ㅇ":[144.5,136,"e"],"ㅂ":[0,195.5,"sw"],"ㅅ":[85,195.5,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[42.5,203.5],"5 cm"],[[130.75,169.75],"7 cm"],[[67,127.5],"8 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_d#23','math',5,2,'u5','','tb_g5_2_math_u5_review_d','unit_review','M5-2-u5-C5',4,'essay','teacher','■ + ▲의 값을 구하려고 해요(단원 평가). 「정육면체에서 서로 평행한 면은 모두 ■쌍 있습니다.」 「직육면체에서 한 꼭짓점에서 만나는 면은 모두 ▲개입니다.」 풀이 과정을 쓰고 답을 구하세요.','{}'::text[],false,'{"seq":23,"concept":"M5-2-u5-C5","difficulty":4,"kind":"essay","stem":"■ + ▲의 값을 구하려고 해요(단원 평가). 「정육면체에서 서로 평행한 면은 모두 ■쌍 있습니다.」 「직육면체에서 한 꼭짓점에서 만나는 면은 모두 ▲개입니다.」 풀이 과정을 쓰고 답을 구하세요.","answer_guide":{"answer":"예: 정육면체에서 서로 평행한 면은 앞·뒤, 위·아래, 왼쪽·오른쪽으로 모두 3쌍이므로 ■ = 3이다. 직육면체에서 한 꼭짓점에서 만나는 면은 모두 3개이므로 ▲ = 3이다. 따라서 ■ + ▲ = 3 + 3 = 6이다.","scoring_points":["■ = 3(평행한 면 3쌍)을 구했는가","▲ = 3(한 꼭짓점의 면 3개)을 구했는가","3 + 3 = 6을 구했는가"]},"explanation":["평행한 면은 3쌍이에요 — ■ = 3.","한 꼭짓점에서 면 3개가 만나요 — ▲ = 3.","3 + 3 = 6이에요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_d#24','math',5,2,'u5','','tb_g5_2_math_u5_review_d','unit_review','M5-2-u5-C8',4,'essay','teacher','교과서 122쪽 주사위의 전개도를 보고 눈의 수 1에서 시작해 「보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 작은 면이 보이게 굴리기」를 6번 반복하려고 해요. 6번을 모두 굴리지 않고 결과를 구하는 방법과 결과를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u5-C8","difficulty":4,"kind":"essay","stem":"교과서 122쪽 주사위의 전개도를 보고 눈의 수 1에서 시작해 「보이는 면과 평행한 면이 보이게 굴리기 → 보이는 면과 수직인 면 중에서 눈의 수가 가장 작은 면이 보이게 굴리기」를 6번 반복하려고 해요. 6번을 모두 굴리지 않고 결과를 구하는 방법과 결과를 쓰세요.","answer_guide":{"answer":"예: 1에서 시작하면 평행한 6으로 굴린 뒤 6과 수직인 2, 3, 4, 5 가운데 가장 작은 2가 보인다. 2에서는 평행한 5로 굴린 뒤 1, 3, 4, 6 가운데 가장 작은 1이 보인다. 그래서 1 → 2 → 1 → 2로 2번 반복할 때마다 처음 눈의 수 1이 나온다. 6번은 2번씩 세 번이므로 1이 보인다.","scoring_points":["1번·2번 실행 결과(2, 1)을 구했는가","2번마다 처음 수가 다시 나온다고 썼는가","6번 실행하면 1이라고 결론지었는가"]},"explanation":["1 → 2, 2 → 1로 바뀌어요.","2번 반복할 때마다 처음 수 1이 다시 나와요.","6번 실행하면 1이 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"4"],[[15.0,40.0],"2"],[[45.0,40.0],"1"],[[75.0,40.0],"5"],[[105.0,40.0],"6"],[[15.0,70.0],"3"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g5_2_math_u5_review_d#25','math',5,2,'u5','','tb_g5_2_math_u5_review_d','unit_review','M5-2-u5-C4',4,'sa','auto','단원 평가에 나온 가로 6 cm, 세로 9 cm, 높이 5 cm인 직육면체의 겨냥도예요. 보이는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":25,"concept":"M5-2-u5-C4","difficulty":4,"kind":"sa","stem":"단원 평가에 나온 가로 6 cm, 세로 9 cm, 높이 5 cm인 직육면체의 겨냥도예요. 보이는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["보이는 모서리 9개는 가로, 세로, 높이가 3개씩이에요.","6 × 3 + 9 × 3 + 5 × 3 = 60이에요.","그래서 60 cm예요."],"mis":"M5-2-u5-X10","asset":{"type":"geo","items":[{"w":147.0,"h":133.0,"pts":{"ㄱ":[63.0,0,"nw"],"ㄹ":[147.0,0,"ne"],"ㄴ":[0,63.0,"w"],"ㄷ":[84,63.0,"sw"],"ㅁ":[63.0,70,"ne"],"ㅇ":[147.0,70,"e"],"ㅂ":[0,133.0,"sw"],"ㅅ":[84,133.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[42.0,141.0],"6 cm"],[[131.5,105.5],"9 cm"],[[66,98.0],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"한 모서리가 16 cm인 정육면체 모양의 상자를 끈으로 묶었어요. 끈은 상자의 위·아래 면을 가로지르며 열십자로 두 바퀴 둘렀고, 매듭에 쓴 끈은 18 cm예요. 사용한 끈은 모두 몇 cm인가요? 숫자로 쓰세요.","answer":["146"],"explanation":["끈이 한 바퀴 돌 때 한 모서리 길이만큼 4번 지나가요.","두 바퀴이니 16 × 8 = 128이고, 매듭 18 cm를 더해요.","128 + 18 = 146(cm)예요."],"asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"단원 평가에 나온 가로 9 cm, 세로 7 cm, 높이 3 cm인 직육면체예요. 길이가 7 cm인 모서리의 길이를 모두 더하면 몇 cm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["직육면체에서 세로와 길이가 같은 모서리는 모두 4개예요.","7 × 4 = 28이에요.","그래서 28 cm예요."],"asset":{"type":"geo","items":[{"w":150.0,"h":78.0,"pts":{"ㄱ":[42.0,0,"nw"],"ㄹ":[150.0,0,"ne"],"ㄴ":[0,42.0,"w"],"ㄷ":[108,42.0,"sw"],"ㅁ":[42.0,36,"ne"],"ㅇ":[150.0,36,"e"],"ㅂ":[0,78.0,"sw"],"ㅅ":[108,78.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[54.0,86.0],"9 cm"],[[145.0,61.0],"7 cm"],[[90,60.0],"3 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
